function DetailOperationSpecificCell({
  index,
  isReadOnly,
  readOnlyItem,
  operationMap,
  form,
  reResolveRowCost,
  t,
}: {
  index: number;
  isReadOnly: boolean;
  readOnlyItem?: IInstallationOrderDetail;
  operationMap: Map<string, IProductionOperation>;
  form: UseFormReturn<InstallationOrderFormValues>;
  reResolveRowCost: (index: number, patch: Partial<IInstallationOrderDetail>) => void;
  t: TFunction;
}) {
  const watchedOpId = useWatch({
    control: form.control,
    name: `details.${index}.productionOperationId`,
  });
  const watchedSpecificId = useWatch({
    control: form.control,
    name: `details.${index}.operationSpecificId`,
  });
  const opId = isReadOnly ? (readOnlyItem?.productionOperationId ?? watchedOpId) : watchedOpId;
  const specificId = isReadOnly
    ? (readOnlyItem?.operationSpecificId ?? watchedSpecificId)
    : watchedSpecificId;
  const op = opId ? operationMap.get(opId) : undefined;
  const specific =
    op?.productionOperationSpecifics?.find((s) => s.id === specificId) ||
    readOnlyItem?.operationSpecific;

  if (isReadOnly) {
    const title =
      specific?.name ||
      readOnlyItem?.operationSpecificNameSnapshot;
    const subtitle = specific?.code || readOnlyItem?.operationSpecificCodeSnapshot;
    return <DoubleLineCell title={title} subtitle={subtitle} />;
  }

  const specificOptions = (op?.productionOperationSpecifics ?? []).map((item) => ({
    value: item.id,
    label: item.name ?? '',
    code: item.code,
    optionData: item,
  }));

  return (
    <FormField
      control={form.control}
      name={`details.${index}.operationSpecificId`}
      render={({ field }) => (
        <FormItem className="w-full">
          <FormControl>
            <Combobox
              options={specificOptions}
              value={field.value ?? undefined}
              onValueChange={(val) => {
                const newSpecId = val ?? '';
                field.onChange(newSpecId);
                reResolveRowCost(index, {
                  operationSpecificId: newSpecId || null,
                });
              }}
              placeholder={
                t('common:component.placeholder.select', {
                  defaultValue: 'Chọn đặc thù',
                }) as string
              }
              disabled={isReadOnly || !opId || specificOptions.length === 0}
              codePrefix=""
            />
          </FormControl>
          <FormMessage />
        </FormItem>
      )}
    />
  );
}

function DetailCostCell({
  index,
  isReadOnly,
  readOnlyItem,
  form,
  resolveActiveCost,
}: {
  index: number;
  isReadOnly: boolean;
  readOnlyItem?: IInstallationOrderDetail;
  form: UseFormReturn<InstallationOrderFormValues>;
  resolveActiveCost: (row: IInstallationOrderDetail) => IProductionCost | undefined;
}) {
  const row = useWatch({ control: form.control, name: `details.${index}` });
  const liveRow = (isReadOnly ? (readOnlyItem ?? row) : row) as unknown as IInstallationOrderDetail;
  if (!liveRow) return <DoubleLineCell fallback="-" />;
  const activeCost = resolveActiveCost(liveRow);
  if (!activeCost) return <DoubleLineCell fallback="-" />;
  return <DoubleLineCell title={activeCost.name} subtitle={activeCost.code} />;
}

function DetailIsMappedToCostCell({
  index,
  isReadOnly,
  readOnlyItem,
  form,
  resolveActiveCost,
  t,
}: {
  index: number;
  isReadOnly: boolean;
  readOnlyItem?: IInstallationOrderDetail;
  form: UseFormReturn<InstallationOrderFormValues>;
  resolveActiveCost: (row: IInstallationOrderDetail) => IProductionCost | undefined;
  t: TFunction;
}) {

