export type InstallationOrderTableShellProps<T extends object = Record<string, unknown>> = {
  readonly columns: readonly ResizableWrapTableColumn<T>[];
  readonly data: readonly T[];
  readonly getRowId: (row: T) => string;
  readonly emptyMessage: string;
  readonly totalCount?: number;
  readonly filteredCount?: number;
  readonly maxBodyHeight?: number | string;
  readonly tableMinWidth?: number;
  readonly canAddDetail?: boolean;
  readonly isReadOnly?: boolean;
  readonly onAddClick?: () => void;
  readonly disabledAdd?: boolean;
  readonly toolbarActions?: React.ReactNode;
  readonly hideToolbar?: boolean;
  readonly toolbarProps?: ResizableWrapTableToolbarProps;
  readonly showPagination?: boolean;
  readonly defaultPageSize?: number;
  readonly pageSizeOptions?: readonly number[];
};

export const DETAIL_TABLE_MAX_BODY_HEIGHT = '60vh';

type FieldArrayRowIdentity = {
  readonly fieldId?: string;
  readonly id?: string;
  readonly sourceKey?: string;
};

export const getStableRowId = (row?: FieldArrayRowIdentity | null) =>
  row?.fieldId ?? row?.sourceKey ?? row?.id ?? '';

export function useFieldIndexMap(fields: ReadonlyArray<{ fieldId?: string; id?: string }>) {
  return useMemo(() => {
    const map = new Map<string, number>();
    fields.forEach((field, index) => {
      const stableId = getStableRowId(field);
      if (stableId) {
        map.set(stableId, index);
      }
    });
    return map;
  }, [fields]);
}

export function FkDoubleLineCell({
  item,
  fallback = '—',
}: {
  item?: { name?: string | null; code?: string | null } | null;
  fallback?: string;
}) {
  if (!item || (!item.name && !item.code)) {
    return <DoubleLineCell title={fallback} />;
  }
  return <DoubleLineCell title={item.name ?? undefined} subtitle={item.code ?? undefined} />;
}

export function InstallationOrderTableShell<T extends object = Record<string, unknown>>({
  columns,
  data,
  getRowId,
  emptyMessage,
  totalCount,
  filteredCount,
  maxBodyHeight = DETAIL_TABLE_MAX_BODY_HEIGHT,
  tableMinWidth = 1200,
  toolbarActions,
  hideToolbar = false,
  toolbarProps,
  showPagination,
  defaultPageSize = 20,
  pageSizeOptions = [10, 20, 50, 100, 200, 500],
}: InstallationOrderTableShellProps<T>) {
  const hasCustomRight = !!toolbarActions || !!toolbarProps?.rightActions;

  const mergedToolbarProps: ResizableWrapTableToolbarProps | undefined = hideToolbar
    ? undefined
    : {
        totalCount: toolbarProps?.totalCount ?? totalCount ?? data.length,
        filteredCount: toolbarProps?.filteredCount ?? filteredCount,
        ...toolbarProps,
        rightActions: hasCustomRight ? (
          <div className="flex justify-end items-center gap-2">
            {toolbarProps?.rightActions}
            {toolbarActions}
          </div>
        ) : undefined,
      };

  return (
    <ResizableWrapTable
      columns={columns as unknown as ResizableWrapTableColumn<Record<string, unknown>>[]}
      data={data as unknown as readonly Record<string, unknown>[]}
      getRowId={getRowId as unknown as (row: Record<string, unknown>) => string}
      emptyMessage={emptyMessage}
      maxBodyHeight={maxBodyHeight}
      tableMinWidth={tableMinWidth}
      toolbarProps={mergedToolbarProps}
      showPagination={showPagination ?? data.length > 20}
      defaultPageSize={defaultPageSize}
      pageSizeOptions={pageSizeOptions}
    />
  );
}

