322:                 .Select(d => d.InventoryTransferExcessRecoveryId)
323:                 .Distinct()
324:                 .ToListAsync();
325: 
326:             decimal iterRecovery = 0;
327:             if (iterIds.Count > 0)
328:             {
329:                 iterRecovery = await txRepo.Query()
330:                     .Where(x => iterIds.Contains(x.SourceDocumentId!.Value) && x.QuantityIn > 0)
331:                     .SumAsync(x => x.QuantityIn * x.UnitPrice);
332:             }
333: 
334:             return itCost - iterRecovery;
335:         }
336:         catch (Exception ex)
