343:     public async Task<Result<MaterialCostBreakdownDto>> GetMaterialCostBreakdownAsync(Guid receiptId)
344:     {
345:         try
346:         {
347:             var receipt = await _repository.Query()
348:                 .Where(x => x.Id == receiptId)
349:                 .Select(x => new { x.ProductionOrderId })
350:                 .FirstOrDefaultAsync();
351: 
352:             if (receipt?.ProductionOrderId == null)
353:                 return Result<MaterialCostBreakdownDto>.Success(new MaterialCostBreakdownDto());
354: 
355:             var productionOrderId = receipt.ProductionOrderId.Value;
356: 
357:             // Load ITs with their code
358:             var its = await _unitOfWork.GetRepository<InventoryTransfer>()
359:                 .Query()
360:                 .Where(x => x.ProductionOrderId == productionOrderId && x.IsPosted)
361:                 .Select(x => new { x.Id, x.Code })
362:                 .ToListAsync();
363: 
364:             if (its.Count == 0)
365:                 return Result<MaterialCostBreakdownDto>.Success(new MaterialCostBreakdownDto());
366: 
367:             var itIds = its.Select(x => x.Id).ToList();
368:             var txRepo = _unitOfWork.GetRepository<InventoryTransaction>();
369: 
370:             // Load IT transaction lines
371:             var itLines = await txRepo.Query()
372:                 .Where(x => itIds.Contains(x.SourceDocumentId!.Value) && x.QuantityOut > 0)
373:                 .Select(x => new
374:                 {
375:                     x.SourceDocumentId,
376:                     x.MaterialCodeSnapshot,
377:                     x.MaterialNameSnapshot,
378:                     x.ModelCodeSnapshot,
379:                     x.ModelNameSnapshot,
380:                     x.StockUnitOfMeasureCodeSnapshot,
381:                     x.QuantityOut,
382:                     x.UnitPrice,
383:                 })
384:                 .ToListAsync();
385: 
386:             var itGroups = its.Select(it =>
387:             {
388:                 var lines = itLines
389:                     .Where(l => l.SourceDocumentId == it.Id)
390:                     .Select(l => new MaterialTransactionLineDto
391:                     {
392:                         MaterialCodeSnapshot = l.MaterialCodeSnapshot,
393:                         MaterialNameSnapshot = l.MaterialNameSnapshot,
394:                         ModelCodeSnapshot = l.ModelCodeSnapshot,
395:                         ModelNameSnapshot = l.ModelNameSnapshot,
396:                         UnitOfMeasureCodeSnapshot = l.StockUnitOfMeasureCodeSnapshot,
397:                         Quantity = l.QuantityOut,
398:                         UnitPrice = l.UnitPrice,
399:                         TotalValue = l.QuantityOut * l.UnitPrice,
400:                     })
401:                     .ToList();
402: 
403:                 return new ItCostGroupDto
404:                 {
405:                     ItId = it.Id,
406:                     ItCode = it.Code,
407:                     TotalValue = lines.Sum(l => l.TotalValue),
408:                     Lines = lines,
409:                 };
410:             }).ToList();
411: 
412:             // Load ITER groups
413:             var iterDetailRepo = _unitOfWork.GetRepository<InventoryTransferExcessRecoveryDetail>();
414:             var iterMap = await iterDetailRepo.Query()
415:                 .Where(d => itIds.Contains(d.SourceTransferDetail.InventoryTransferId))
416:                 .Select(d => new { d.InventoryTransferExcessRecoveryId, d.InventoryTransferExcessRecovery.Code })
417:                 .Distinct()
418:                 .ToListAsync();
419: 
420:             var iterGroups = new List<IterRecoveryGroupDto>();
421:             if (iterMap.Count > 0)
422:             {
423:                 var iterIds = iterMap.Select(x => x.InventoryTransferExcessRecoveryId).Distinct().ToList();
424:                 var iterLines = await txRepo.Query()
425:                     .Where(x => iterIds.Contains(x.SourceDocumentId!.Value) && x.QuantityIn > 0)
426:                     .Select(x => new
427:                     {
428:                         x.SourceDocumentId,
429:                         x.MaterialCodeSnapshot,
430:                         x.MaterialNameSnapshot,
431:                         x.ModelCodeSnapshot,
432:                         x.ModelNameSnapshot,
433:                         x.StockUnitOfMeasureCodeSnapshot,
434:                         x.QuantityIn,
435:                         x.UnitPrice,
436:                     })
437:                     .ToListAsync();
438: 
439:                 iterGroups = iterMap
440:                     .GroupBy(x => x.InventoryTransferExcessRecoveryId)
441:                     .Select(g =>
442:                     {
443:                         var lines = iterLines
444:                             .Where(l => l.SourceDocumentId == g.Key)
445:                             .Select(l => new MaterialTransactionLineDto
446:                             {
447:                                 MaterialCodeSnapshot = l.MaterialCodeSnapshot,
448:                                 MaterialNameSnapshot = l.MaterialNameSnapshot,
449:                                 ModelCodeSnapshot = l.ModelCodeSnapshot,
450:                                 ModelNameSnapshot = l.ModelNameSnapshot,
451:                                 UnitOfMeasureCodeSnapshot = l.StockUnitOfMeasureCodeSnapshot,
452:                                 Quantity = l.QuantityIn,
453:                                 UnitPrice = l.UnitPrice,
454:                                 TotalValue = l.QuantityIn * l.UnitPrice,
455:                             })
456:                             .ToList();
457: 
458:                         return new IterRecoveryGroupDto
459:                         {
460:                             IterId = g.Key,
461:                             IterCode = g.First().Code,
462:                             TotalValue = lines.Sum(l => l.TotalValue),
463:                             Lines = lines,
464:                         };
465:                     })
466:                     .ToList();
467:             }
468: 
469:             var totalIt = itGroups.Sum(g => g.TotalValue);
470:             var totalIter = iterGroups.Sum(g => g.TotalValue);
471: 
472:             return Result<MaterialCostBreakdownDto>.Success(new MaterialCostBreakdownDto
473:             {
474:                 TotalItCost = totalIt,
475:                 TotalIterRecovery = totalIter,
476:                 NetMaterialCost = totalIt - totalIter,
477:                 ItGroups = itGroups,
478:                 IterGroups = iterGroups,
479:             });
480:         }
481:         catch (Exception ex)
482:         {
483:             _logger.Error(ex, "Lỗi khi lấy chi tiết CP NVL. ReceiptId={Id}", receiptId);
484:             return Result<MaterialCostBreakdownDto>.Failure("Lỗi hệ thống khi lấy chi tiết chi phí NVL.");
485:         }
486:     }
