574: 
575:             var receiptIds = await _unitOfWork.GetRepository<FinishedGoodsReceiptDetail>().Query()
576:                 .Where(d => !d.IsSiteDelivered
577:                     && d.ProjectId == projectId
578:                     && closedIds.Contains(d.FinishedGoodsReceiptId))
579:                 .Select(d => d.FinishedGoodsReceiptId)
580:                 .Distinct()
581:                 .ToListAsync();
582: 
583:             if (receiptIds.Count == 0)
584:                 return Result<List<FinishedGoodsReceiptDto>>.Success([]);
585: 
586:             var receipts = await _repository.Query()
587:                 .Include(r => r.Details)
588:                 .Where(r => receiptIds.Contains(r.Id))
589:                 .ToListAsync();
590: 
591:             var dtos = _mapper.Map<List<FinishedGoodsReceiptDto>>(receipts);
592:             foreach (var dto in dtos)
593:             {
594:                 if (dto.Details != null)
595:                     dto.Details = dto.Details.Where(d => !d.IsSiteDelivered && d.ProjectId == projectId).ToList();
596:             }
597: 
598:             // Chặn double-pack: bỏ các kiện (receipt-detail) đã được đóng vào 1 phiếu đóng kiện khác
599:             // (loại trừ phiếu đang sửa qua excludeDeliveryPackingId để kiện của chính nó vẫn hiện).
600:             var candidateDetailIds = dtos
601:                 .Where(d => d.Details != null)
602:                 .SelectMany(d => d.Details)
603:                 .Select(d => d.Id)
604:                 .Distinct()
605:                 .ToList();
606:             if (candidateDetailIds.Count > 0)
607:             {
608:                 var packedReq = new GetPackedReceiptDetailIdsRequest();
609:                 packedReq.ReceiptDetailIds.AddRange(candidateDetailIds.Select(id => id.ToString()));
610:                 if (excludeDeliveryPackingId.HasValue && excludeDeliveryPackingId.Value != Guid.Empty)
611:                     packedReq.ExcludeDeliveryPackingId = excludeDeliveryPackingId.Value.ToString();
612:                 var packedResp = await _serviceDeskGrpcClient.GetPackedReceiptDetailIdsAsync(packedReq);
613:                 var packedIds = packedResp.PackedReceiptDetailIds
614:                     .Where(s => Guid.TryParse(s, out _))
615:                     .Select(Guid.Parse)
616:                     .ToHashSet();
617:                 if (packedIds.Count > 0)
618:                     foreach (var dto in dtos)
619:                         if (dto.Details != null)
620:                             dto.Details = dto.Details.Where(d => !packedIds.Contains(d.Id)).ToList();
621:             }
622: 
623:             // Enrich model (ModelCode/ModelName) để hiển thị khi đóng kiện — model không snapshot ở
624:             // receipt-detail, lấy từ snapshot packing (gRPC ServiceDesk đã resolve ModelId → code/name).
625:             var packingIds = dtos
626:                 .Where(d => d.Details != null)
627:                 .SelectMany(d => d.Details)
628:                 .Select(d => d.FinishedGoodsPackingId)
629:                 .Where(id => id != Guid.Empty)
630:                 .Distinct()
631:                 .ToList();
632:             if (packingIds.Count > 0)
633:             {
634:                 var snapReq = new GetFinishedGoodsPackingSnapshotsByIdsRequest();
635:                 snapReq.PackingIds.AddRange(packingIds.Select(id => id.ToString()));
636:                 var snapResp = await _serviceDeskGrpcClient.GetFinishedGoodsPackingSnapshotsByIdsAsync(snapReq);
637:                 var snapByPacking = snapResp.Items.ToDictionary(
638:                     i => i.PackingId,
639:                     i => i,
640:                     StringComparer.OrdinalIgnoreCase);
641:                 foreach (var dto in dtos)
642:                 {
643:                     if (dto.Details == null) continue;
644:                     foreach (var d in dto.Details)
645:                         if (snapByPacking.TryGetValue(d.FinishedGoodsPackingId.ToString(), out var snap))
646:                         {
647:                             d.ModelCode = snap.ModelCode;
648:                             d.ModelName = snap.ModelName;
649:                             d.FinishedGoodId = Guid.TryParse(snap.FinishedGoodId, out var fgId) ? fgId : null;
650:                             d.ModelId = Guid.TryParse(snap.ModelId, out var mId) ? mId : null;
651:                         }
652:                 }
653:             }
654: 
655:             await _masterDataGrpcClient.EnrichWorkItemsAsync(dtos, _logger);
656:             return Result<List<FinishedGoodsReceiptDto>>.Success(dtos);
