      receipts.forEach((receipt) => {
        receipt.details?.forEach((detail) => {
          // Check if already added
          if (existingPackingIds.includes(detail.finishedGoodsPackingId)) return;

          // Check combo key match with ITPs
          const isMatch = itpKeys.some((itp) => {
            const matchFg = !itp.finishedGoodId || itp.finishedGoodId === detail.finishedGoodId;
            const matchModel = !itp.modelId || itp.modelId === detail.modelId;
            // Note: detail doesn't have designModelId, so we match on 2 keys.
            return matchFg && matchModel;
