536:       } else if (parts[0] === 'processes' && parts.length >= 3) {
537:         const index = Number.parseInt(parts[1], 10);
538:         messages.push(
539:           t
540:             ? t('installationOrder:validation.tabErrorRow', {
541:                 tab: t('installationOrder:tab.processes', { defaultValue: 'Quy trình' }),
542:                 index: index + 1,
543:                 message: errorNode.message,
544:                 defaultValue: `[Tab Quy trình] Dòng ${index + 1}: ${errorNode.message}`,
545:               })
546:             : `[Tab Quy trình] Dòng ${index + 1}: ${errorNode.message}`,
547:         );
548:       } else if (parts[0] === 'semiFinishedGoods' && parts.length >= 3) {
549:         const index = Number.parseInt(parts[1], 10);
550:         messages.push(
551:           t
552:             ? t('installationOrder:validation.tabErrorRow', {
