import { useState, useMemo, useEffect } from 'react';
import { useTranslation } from 'react-i18next';
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  Button,
  Checkbox,
  TableSkeleton,
} from '@shared/ui';
import {
  ResizableWrapTable,
  type ResizableWrapTableColumn,
  DoubleLineCell,
} from '@shared/components';
import { useFinishedGoodsReceipt } from '@/routes/_app/inventory/finished-goods-receipt/_hooks/use-finished-goods-receipt';
import { useFinishedGoodsPacking } from '@/routes/_app/logistic/finished-goods-packing/_hooks/use-finished-goods-packing';
import { useMechanicalPackingList } from '@/routes/_app/logistic/mechanical-packing-list/_hooks/use-mechanical-packing-list';
import type { InstallationOrderPackingRow } from '../installation-order-form.schema';

interface PackingSelectionDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  projectId?: string | null;
  refDocId?: string | null;
  onSelect: (packings: InstallationOrderPackingRow[]) => void;
  existingPackingIds: string[];
  itpKeys: {
    finishedGoodId?: string | null;
    modelId?: string | null;
    designModelId?: string | null;
  }[];
}

export function PackingSelectionDialog({
  open,
  onOpenChange,
  projectId,
  refDocId,
  onSelect,
  existingPackingIds,
  itpKeys,
}: PackingSelectionDialogProps) {
  const { t } = useTranslation(['installationOrder', 'action', 'common']);

  // 1. Fetch physically received receipts if projectId is available
  const { getAvailableForSiteDeliveryQuery } = useFinishedGoodsReceipt({
    availableForSiteDelivery: {
      projectId: projectId || '',
      isEnable: open && !!projectId,
    },
  });

  const packingIds = useMemo(() => {
    const receipts = getAvailableForSiteDeliveryQuery.data?.data || [];
    const ids: string[] = [];
    receipts.forEach((r) => {
      r.details?.forEach((d) => {
        if (d.finishedGoodsPackingId) {
          ids.push(d.finishedGoodsPackingId);
        }
      });
    });
    return Array.from(new Set(ids));
  }, [getAvailableForSiteDeliveryQuery.data?.data]);

  // 2. Fetch full FinishedGoodsPacking records (including MechanicalPackingList and Details)
  const { byIdsQuery: packingByIdsQuery } = useFinishedGoodsPacking({
    byIds: {
      ids: packingIds,
      includes: ['MechanicalPackingList', 'Details', 'PackingCodes'],
      isEnable: open && !!projectId && packingIds.length > 0,
    },
  });

  // 3. Fetch mechanical packings as fallback if projectId is missing but refDocId exists
  const { pagingQuery: mechanicalPackingQuery } = useMechanicalPackingList({
    queryParam: {
      paging: {
        params: {
          page: 1,
          pageSize: 1000,
        },
        filterKeys: {
          projectId: projectId || undefined,
          productionOrderRefDocId: !projectId && refDocId ? refDocId : undefined,
        },
        isEnable: open && !projectId && !!refDocId,
      },
    },
  });

  const [selectedPackings, setSelectedPackings] = useState<
    Record<string, InstallationOrderPackingRow>
  >({});

  useEffect(() => {
    if (open) {
      setSelectedPackings({});
    }
  }, [open]);

  const eligiblePackings = useMemo(() => {
    const list: InstallationOrderPackingRow[] = [];
    const addedIds = new Set(existingPackingIds);

    if (projectId) {
      // Móc từ FinishedGoodsPacking đã thực nhập kho
      const packings = packingByIdsQuery.data?.data || [];
      packings.forEach((pkg) => {
        if (!pkg.id || addedIds.has(pkg.id)) return;

        const fgId = pkg.finishedGoodId || pkg.mechanicalPackingList?.finishedGoodId;
        const mId = pkg.modelId || pkg.mechanicalPackingList?.modelId;
        const dmId = pkg.designModelId || pkg.mechanicalPackingList?.designModelId;

        // Check combo key match with ITPs
        const isMatch = itpKeys.some((itp) => {
          const matchFg = !itp.finishedGoodId || itp.finishedGoodId === fgId;
          const matchModel = !itp.modelId || itp.modelId === mId;
          const matchDesign = !itp.designModelId || itp.designModelId === dmId;
          return matchFg && matchModel && matchDesign;
        });

        if (isMatch) {
          addedIds.add(pkg.id);
          list.push({
            id: pkg.id,
            order: 0,
            finishedGoodId: fgId || null,
            finishedGoodCodeSnapshot: pkg.mechanicalPackingList?.finishedGoodsCode || null,
            finishedGoodNameSnapshot: pkg.mechanicalPackingList?.finishedGoodsName || null,
            modelId: mId || null,
            modelCodeSnapshot:
              pkg.modelCode || pkg.mechanicalPackingList?.modelCode || null,
            modelNameSnapshot:
              pkg.modelName || pkg.mechanicalPackingList?.modelName || null,
            designModelId: dmId || null,
            designModelCodeSnapshot:
              pkg.designModelCode || pkg.mechanicalPackingList?.designModelCode || null,
            designModelNameSnapshot:
              pkg.designModelName || pkg.mechanicalPackingList?.designModelName || null,
            mechanicalPackingListId:
              pkg.mechanicalPackingListId || pkg.mechanicalPackingList?.id || null,
            mechanicalPackingListCodeSnapshot: pkg.mechanicalPackingList?.code || null,
            mechanicalPackingListNameSnapshot: null,
            details: pkg.details,
          } as InstallationOrderPackingRow);
        }
      });
    } else if (refDocId) {
      // Fallback móc từ MechanicalPackingList
      const mpls = mechanicalPackingQuery.data?.data || [];
      mpls.forEach((mpl) => {
        if (!mpl.id || addedIds.has(mpl.id)) return;

        // Check combo key match
        const isMatch = itpKeys.some((itp) => {
          const matchFg = !itp.finishedGoodId || itp.finishedGoodId === mpl.finishedGoodId;
          const matchModel = !itp.modelId || itp.modelId === mpl.modelId;
          const matchDesign = !itp.designModelId || itp.designModelId === mpl.designModelId;
          return matchFg && matchModel && matchDesign;
        });

        if (isMatch) {
          addedIds.add(mpl.id);
          list.push({
            id: mpl.id,
            order: 0,
            finishedGoodId: mpl.finishedGoodId || null,
            finishedGoodCodeSnapshot: mpl.finishedGoodsCode || null,
            finishedGoodNameSnapshot: mpl.finishedGoodsName || null,
            modelId: mpl.modelId || null,
            modelCodeSnapshot: mpl.modelCode || null,
            modelNameSnapshot: mpl.modelName || null,
            designModelId: mpl.designModelId || null,
            designModelCodeSnapshot: mpl.designModelCode || null,
            designModelNameSnapshot: mpl.designModelName || null,
            mechanicalPackingListId: mpl.id,
            mechanicalPackingListCodeSnapshot: mpl.code || null,
            mechanicalPackingListNameSnapshot: null,
          } as InstallationOrderPackingRow);
        }
      });
    }

    return list;
  }, [
    projectId,
    refDocId,
    packingByIdsQuery.data?.data,
    mechanicalPackingQuery.data?.data,
    existingPackingIds,
    itpKeys,
  ]);

  const handleSelectAll = (checked: boolean) => {
    if (checked) {
      const newSelected: Record<string, InstallationOrderPackingRow> = {};
      eligiblePackings.forEach((p, idx) => {
        const key = p.id || p.mechanicalPackingListId || `${idx}`;
        newSelected[key] = p;
      });
      setSelectedPackings(newSelected);
    } else {
      setSelectedPackings({});
    }
  };

  const columns: ResizableWrapTableColumn<InstallationOrderPackingRow>[] = useMemo(
    () => [
      {
        id: 'select',
        header: '',
        defaultWidth: 45,
        minWidth: 40,
        headerAlign: 'center',
        cellClassName: 'text-center',
        headerCell: () => (
          <div className="flex justify-center items-center">
            <Checkbox
              checked={
                eligiblePackings.length > 0 &&
                Object.keys(selectedPackings).length === eligiblePackings.length
              }
              onCheckedChange={(checked) => handleSelectAll(!!checked)}
            />
          </div>
        ),
        cell: (row, idx) => {
          const key = row.id || row.mechanicalPackingListId || `${idx}`;
          const isSelected = !!selectedPackings[key];
          return (
            <div className="flex justify-center items-center">
              <Checkbox
                checked={isSelected}
                onCheckedChange={(checked) => {
                  if (checked) {
                    setSelectedPackings((prev) => ({ ...prev, [key]: row }));
                  } else {
                    setSelectedPackings((prev) => {
                      const next = { ...prev };
                      delete next[key];
                      return next;
                    });
                  }
                }}
              />
            </div>
          );
        },
      },
      {
        id: 'stt',
        header: t('common:stt', { defaultValue: 'STT' }),
        defaultWidth: 55,
        minWidth: 50,
        headerAlign: 'center',
        cellClassName: 'text-center',
        cell: (_row, idx) => (
          <span className="text-xs font-medium text-muted-foreground">{idx + 1}</span>
        ),
      },
      {
        id: 'finishedGood',
        header: t('installationOrder:columnTitle.finishedGoodCode', { defaultValue: 'Mã ITP' }),
        defaultWidth: 160,
        minWidth: 140,
        cell: (row) => (
          <DoubleLineCell
            title={row.finishedGoodNameSnapshot}
            subtitle={row.finishedGoodCodeSnapshot ? `#${row.finishedGoodCodeSnapshot}` : undefined}
            fallback="—"
          />
        ),
      },
      {
        id: 'designModel',
        header: t('installationOrder:columnTitle.designModel', { defaultValue: 'Model thiết kế' }),
        defaultWidth: 140,
        minWidth: 120,
        cell: (row) => (
          <span className="text-xs">
            {row.designModelNameSnapshot || row.designModelCodeSnapshot || '—'}
          </span>
        ),
      },
      {
        id: 'model',
        header: t('installationOrder:columnTitle.model', { defaultValue: 'Model người dùng' }),
        defaultWidth: 140,
        minWidth: 120,
        cell: (row) => (
          <span className="text-xs">
            {row.modelNameSnapshot || row.modelCodeSnapshot || '—'}
          </span>
        ),
      },
      {
        id: 'mechanicalPackingList',
        header: t('installationOrder:columnTitle.mechanicalPackingList', {
          defaultValue: 'Mã Packing List',
        }),
        defaultWidth: 160,
        minWidth: 130,
        cell: (row) => (
          <span className="text-xs font-medium">
            {row.mechanicalPackingListCodeSnapshot
              ? `#${row.mechanicalPackingListCodeSnapshot}`
              : (row.mechanicalPackingListNameSnapshot || '—')}
          </span>
        ),
      },
    ],
    [eligiblePackings.length, selectedPackings, t],
  );

  const handleConfirm = () => {
    onSelect(Object.values(selectedPackings));
    onOpenChange(false);
  };

  const isLoading = projectId
    ? getAvailableForSiteDeliveryQuery.isFetching || packingByIdsQuery.isFetching
    : mechanicalPackingQuery.isFetching;

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="w-full sm:max-w-212.5 p-5">
        <DialogHeader>
          <DialogTitle>
            {t('installationOrder:action.selectPacking', { defaultValue: 'Chọn cụm nhập kho' })}
          </DialogTitle>
        </DialogHeader>

        <div className="border rounded-md overflow-hidden max-h-125 flex flex-col">
          {isLoading ? (
            <TableSkeleton columns={6} rows={4} showToolbar={false} showHeader={true} />
          ) : (
            <ResizableWrapTable
              data={eligiblePackings}
              columns={columns}
              emptyMessage={t('installationOrder:empty.eligiblePackings', {
                defaultValue: 'Không tìm thấy cụm nào đủ điều kiện hoặc đã được chọn hết.',
              })}
            />
          )}
        </div>

        <div className="flex justify-end gap-2 mt-4">
          <Button variant="outline" onClick={() => onOpenChange(false)}>
            {t('action:cancel', { defaultValue: 'Hủy' })}
          </Button>
          <Button onClick={handleConfirm} disabled={Object.keys(selectedPackings).length === 0}>
            {t('action:confirm', { defaultValue: 'Xác nhận' })}
          </Button>
        </div>
      </DialogContent>
    </Dialog>
  );
}

