  onSave,
  isReadOnly = false,
}: ProcessOperationDetailModalProps) {
  const { t } = useTranslation(['installationOrder', 'action', 'common']);
  const [items, setItems] = useState<ProcessOperationDetailItem[]>([]);
  const [selectedDetailItem, setSelectedDetailItem] = useState<{
    id: string;
    name: string;
    code: string;
  } | null>(null);

  useEffect(() => {
    if (open) {
      setItems(
        (initialDetails || []).map((item, idx) => ({
          ...item,
          order: item.order ?? idx + 1,
        })),
      );
      setSelectedDetailItem(null);
    }
  }, [open, initialDetails]);

  const handleAddDetail = useCallback(() => {
    if (!selectedDetailItem?.id) return;

    setItems((prev) => [
      ...prev,
      {
        productionOperationDetailId: selectedDetailItem.id,
        productionOperationDetailCodeSnapshot:
          selectedDetailItem.code || selectedDetailItem.name || '',
        productionOperationDetailNameSnapshot:
          selectedDetailItem.name || selectedDetailItem.code || '',
        order: prev.length + 1,
      },
    ]);
    setSelectedDetailItem(null);
  }, [selectedDetailItem]);

  const handleDeleteDetail = useCallback((index: number) => {
    setItems((prev) =>
      prev.filter((_, i) => i !== index).map((item, i) => ({ ...item, order: i + 1 })),
    );
  }, []);

  const handleReorder = useCallback((fromIndex: number, toIndex: number) => {
    setItems((prev) => {
      const next = [...prev];
      const [moved] = next.splice(fromIndex, 1);
      next.splice(toIndex, 0, moved);
      return next.map((item, i) => ({ ...item, order: i + 1 }));
    });
  }, []);

  const handleSave = useCallback(() => {
    onSave(items);
    onOpenChange(false);
  }, [items, onSave, onOpenChange]);

  const columns = useMemo<SortableWrapTableColumn<ProcessOperationDetailItem>[]>(
    () => [
      {
        id: 'stt',
        header: t('common:stt', { defaultValue: 'STT' }),
        defaultWidth: 65,
        minWidth: 50,
        maxWidth: 80,
        headerAlign: 'center',
        cellAlign: 'center',
        cell: (_row, displayIndex) => (
          <span className="text-muted-foreground font-medium text-xs">{displayIndex + 1}</span>
        ),
      },
      {
        id: 'productionOperationDetailNameSnapshot',
        header: t('installationOrder:columnTitle.operationDetail', {
          defaultValue: 'Chi tiết công đoạn',
        }),
        defaultWidth: 340,
        minWidth: 200,
        cell: (row) => (
          <div className="flex flex-col text-xs">
            <span className="font-semibold text-foreground">
              {row.productionOperationDetailNameSnapshot || '—'}
            </span>
            {row.productionOperationDetailCodeSnapshot && (
              <span className="text-[10px] text-muted-foreground">
                #{row.productionOperationDetailCodeSnapshot}
              </span>
            )}
          </div>
        ),
      },
      ...(!isReadOnly
        ? [
            {
              id: 'actions',
              header: '',
              defaultWidth: 50,
              minWidth: 40,
              maxWidth: 60,
              cellAlign: 'center',
              cell: (_row, displayIndex) => (
                <RowActionButton
                  icon={Trash2}
                  title={t('action:delete', { defaultValue: 'Xóa' })}
                  variant="destructive"
                  onClick={() => handleDeleteDetail(displayIndex)}
                />
              ),
            } as SortableWrapTableColumn<ProcessOperationDetailItem>,
          ]
        : []),
    ],
    [isReadOnly, t, handleDeleteDetail],
  );

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-162.5 p-5 gap-4">
        <DialogHeader>
          <DialogTitle className="text-base font-bold flex items-center gap-2">
            <span>
              {t('installationOrder:processDetailModal.title', {
                defaultValue: 'Quản lý Chi tiết công đoạn',
              })}
            </span>
            {operationName && (
              <span className="text-primary font-normal text-sm">({operationName})</span>
            )}
          </DialogTitle>
        </DialogHeader>

        {!isReadOnly && (
          <div className="flex items-center gap-2 bg-muted/40 p-3 rounded-lg border">
            <div className="flex-1">
              <LazyCombobox
                entityCode="MasterData.ProductionOperationDetail"
                extraKeys={['code', 'name', 'productionOperationId']}
                extraFilters={
                  productionOperationId
                    ? `productionOperationId==${productionOperationId}`
                    : 'productionOperationId==00000000-0000-0000-0000-000000000000'
                }
                enabled={!!productionOperationId}
                excludeValues={
                  items.map((i) => i.productionOperationDetailId).filter(Boolean) as string[]
                }
                disabled={!productionOperationId}
                value={selectedDetailItem?.id ?? ''}
                onSelectOption={(opt) => {
                  if (opt?.value) {
                    setSelectedDetailItem({
                      id: opt.value,
                      name: opt.label || '',
                      code: opt.code || '',
                    });
                  } else {
                    setSelectedDetailItem(null);
                  }
                }}
                placeholder={
                  productionOperationId
                    ? t('installationOrder:placeholder.operationDetail', {
                        defaultValue: 'Chọn chi tiết công đoạn...',
                      })
                    : t('installationOrder:placeholder.selectOperationFirst', {
                        defaultValue: 'Vui lòng chọn công đoạn trước...',
                      })
                }
                className="w-full text-xs"
              />
            </div>
            <Button
              type="button"
              size="sm"
              onClick={handleAddDetail}
              disabled={!selectedDetailItem?.id || !productionOperationId}
              className="gap-1 text-xs shrink-0"
            >
              <Plus className="h-4 w-4" />
              {t('action:add', { defaultValue: 'Thêm' })}
            </Button>
          </div>
        )}

        <div className="border rounded-md overflow-hidden min-h-55 max-h-95">
          <SortableWrapTable<ProcessOperationDetailItem>
            headerVariant="sub-primary"
            columns={columns}
            data={items}
            getRowId={(row, index) =>
              row.productionOperationDetailId || row.id || `detail-${index}`
            }
            onReorder={handleReorder}
            enableDrag={!isReadOnly}
            emptyMessage={t('installationOrder:processDetailModal.empty', {
              defaultValue: 'Chưa có bước chi tiết nào. Thêm mới chi tiết công đoạn ở trên.',
            })}
          />
        </div>

        <DialogFooter className="gap-2 sm:gap-0">
          <Button type="button" variant="outline" size="sm" onClick={() => onOpenChange(false)}>
            {t('action:cancel', { defaultValue: 'Hủy' })}
          </Button>
          {!isReadOnly && (
            <Button type="button" size="sm" onClick={handleSave}>
              {t('action:saveAndApply', { defaultValue: 'Lưu & Áp dụng' })}
            </Button>
          )}
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

