import { useTranslation } from 'react-i18next';
import { Plus, Trash2, GripVertical, Check } from 'lucide-react';
import {
  Button,
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from '@shared/ui';
import {
  LazyCombobox,
  RowActionButton,
  SortableWrapTable,
  type SortableWrapTableColumn,
} from '@shared/components';

export interface ProcessOperationDetailItem {
  id?: string;
  productionOperationDetailId?: string | null;
  productionOperationDetailCodeSnapshot?: string | null;
  productionOperationDetailNameSnapshot?: string | null;
  order?: number;
}

interface ProcessOperationDetailModalProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  operationName?: string;
  productionOperationId?: string | null;
  initialDetails?: ProcessOperationDetailItem[];
  onSave: (details: ProcessOperationDetailItem[]) => void;
  isReadOnly?: boolean;
}

export function ProcessOperationDetailModal({
  open,
  onOpenChange,
  operationName,
  productionOperationId,
  initialDetails = [],
  onSave,
  isReadOnly = false,
}: ProcessOperationDetailModalProps) {
  const { t } = useTranslation(['installationOrder', 'action', 'common']);
  const [items, setItems] = useState<ProcessOperationDetailItem[]>([]);
  const [selectedDetailItem, setSelectedDetailItem] = useState<{
    id: string;
    name: string;
    code: string;
  } | null>(null);

  useEffect(() => {
    if (open) {
      setItems(
        (initialDetails || []).map((item, idx) => ({
          ...item,
          order: item.order ?? idx + 1,
        })),
      );
      setSelectedDetailItem(null);
    }
  }, [open, initialDetails]);

  const handleAddDetail = useCallback(() => {
    if (!selectedDetailItem?.id) return;

    setItems((prev) => [
      ...prev,
      {
        productionOperationDetailId: selectedDetailItem.id,
        productionOperationDetailCodeSnapshot:
          selectedDetailItem.code || selectedDetailItem.name || '',
        productionOperationDetailNameSnapshot:
          selectedDetailItem.name || selectedDetailItem.code || '',
        order: prev.length + 1,
      },
    ]);
    setSelectedDetailItem(null);
  }, [selectedDetailItem]);

  const handleDeleteDetail = useCallback((index: number) => {
    setItems((prev) =>
      prev.filter((_, i) => i !== index).map((item, i) => ({ ...item, order: i + 1 })),
    );
  }, []);

  const handleReorder = useCallback((fromIndex: number, toIndex: number) => {
    setItems((prev) => {
      const next = [...prev];
      const [moved] = next.splice(fromIndex, 1);
      next.splice(toIndex, 0, moved);
      return next.map((item, i) => ({ ...item, order: i + 1 }));
    });
  }, []);

  const handleSave = useCallback(() => {
    onSave(items);
    onOpenChange(false);
  }, [items, onSave, onOpenChange]);

  const columns = useMemo<SortableWrapTableColumn<ProcessOperationDetailItem>[]>(
    () => [
      {
        id: 'stt',
        header: t('common:stt', { defaultValue: 'STT' }),
        defaultWidth: 65,
        minWidth: 50,
        maxWidth: 80,
        headerAlign: 'center',
        cellAlign: 'center',
        cell: (_row, displayIndex) => (
          <span className="text-muted-foreground font-medium text-xs">{displayIndex + 1}</span>
        ),
      },
      {
        id: 'productionOperationDetailNameSnapshot',
        header: t('installationOrder:columnTitle.operationDetail', {
          defaultValue: 'Chi tiết công đoạn',
        }),
        defaultWidth: 340,
        minWidth: 200,
        cell: (row) => (
          <div className="flex flex-col text-xs">
            <span className="font-semibold text-foreground">
              {row.productionOperationDetailNameSnapshot || '—'}
            </span>
            {row.productionOperationDetailCodeSnapshot && (
              <span className="text-[10px] text-muted-foreground">
                #{row.productionOperationDetailCodeSnapshot}
              </span>
            )}
          </div>
        ),
      },
      ...(!isReadOnly
        ? [
            {
              id: 'actions',
              header: '',
              defaultWidth: 50,
              minWidth: 40,
              maxWidth: 60,
              cellAlign: 'center',
              cell: (_row, displayIndex) => (
                <RowActionButton
                  icon={Trash2}
                  title={t('action:delete', { defaultValue: 'Xóa' })}
                  variant="destructive"
                  onClick={() => handleDeleteDetail(displayIndex)}
                />
              ),
            } as SortableWrapTableColumn<ProcessOperationDetailItem>,
          ]
        : []),
    ],
    [isReadOnly, t, handleDeleteDetail],
  );

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-xl sm:max-w-2xl max-h-[85vh] h-[78vh] flex flex-col p-6 overflow-hidden">
        <DialogHeader className="pb-3 border-b shrink-0">
          <DialogTitle className="text-lg font-bold flex items-center gap-2">
            <span className="w-1.5 h-4 bg-primary rounded-full" />
            <span>
              {t('installationOrder:processDetailModal.title', {
                defaultValue: 'Quản lý Chi tiết công đoạn',
              })}
            </span>
            {operationName && (
              <span className="inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium bg-primary/10 text-primary border border-primary/20">
                {operationName}
              </span>
            )}
          </DialogTitle>
          <DialogDescription className="text-sm text-muted-foreground">
            {t('installationOrder:processDetailModal.description', {
              defaultValue:
                'Cấu hình và sắp xếp thứ tự các bước chi tiết thực hiện cho công đoạn này.',
            })}
          </DialogDescription>
        </DialogHeader>

        <div className="flex-1 min-h-0 py-3 flex flex-col gap-3 overflow-hidden">
          {!isReadOnly && (
            <div className="flex items-center gap-2 bg-muted/40 p-3 rounded-lg border shrink-0">
              <div className="flex-1 min-w-0">
                <LazyCombobox
                  entityCode="MasterData.ProductionOperationDetail"
                  extraKeys={['code', 'name', 'productionOperationId']}
                  extraFilters={
                    productionOperationId
                      ? `productionOperationId==${productionOperationId}`
                      : 'productionOperationId==00000000-0000-0000-0000-000000000000'
                  }
                  enabled={!!productionOperationId}
                  excludeValues={
                    items.map((i) => i.productionOperationDetailId).filter(Boolean) as string[]
                  }
                  disabled={!productionOperationId}
                  value={selectedDetailItem?.id ?? ''}
                  onSelectOption={(opt) => {
                    if (opt?.value) {
                      setSelectedDetailItem({
                        id: opt.value,
                        name: opt.label || '',
                        code: opt.code || '',
                      });
                    } else {
                      setSelectedDetailItem(null);
                    }
                  }}
                  placeholder={
                    productionOperationId
                      ? t('installationOrder:placeholder.operationDetail', {
                          defaultValue: 'Chọn chi tiết công đoạn...',
                        })
                      : t('installationOrder:placeholder.selectOperationFirst', {
                          defaultValue: 'Vui lòng chọn công đoạn trước...',
                        })
                  }
                  className="w-full text-xs"
                />
              </div>
              <Button
                type="button"
                size="sm"
                onClick={handleAddDetail}
                disabled={!selectedDetailItem?.id || !productionOperationId}
                className="gap-1.5 text-xs shrink-0"
              >
                <Plus className="h-4 w-4" />
                {t('action:add', { defaultValue: 'Thêm' })}
              </Button>
            </div>
          )}

          <div className="flex items-center justify-between text-xs text-muted-foreground px-1 shrink-0">
            <div className="flex items-center gap-1.5">
              <GripVertical className="w-3.5 h-3.5 text-muted-foreground" />
              <span>
                {isReadOnly
                  ? t('installationOrder:processDetailModal.stepListReadOnly', {
                      defaultValue: 'Danh sách các bước chi tiết',
                    })
                  : t('installationOrder:processDetailModal.dragHint', {
                      defaultValue: 'Kéo biểu tượng tay cầm để sắp xếp thứ tự thực hiện',
                    })}
              </span>
            </div>
            <span className="font-medium">
              {t('installationOrder:processDetailModal.stepCount', {
                count: items.length,
                defaultValue: '{{count}} bước',
                replace: { count: items.length },
              })}
            </span>
          </div>

          <div className="flex-1 min-h-0 border rounded-lg overflow-hidden flex flex-col bg-background">
            <SortableWrapTable<ProcessOperationDetailItem>
              headerVariant="sub-primary"
              columns={columns}
              data={items}
              getRowId={(row, index) =>
                row.productionOperationDetailId || row.id || `detail-${index}`
              }
              onReorder={handleReorder}
              enableDrag={!isReadOnly}
              emptyMessage={t('installationOrder:processDetailModal.empty', {
                defaultValue: 'Chưa có bước chi tiết nào. Chọn và thêm chi tiết công đoạn ở trên.',
              })}
            />
          </div>
        </div>

        <DialogFooter className="pt-3 border-t flex items-center justify-between w-full shrink-0">
          <span className="text-xs text-muted-foreground font-medium">
            {t('installationOrder:processDetailModal.summaryCount', {
              count: items.length,
              defaultValue: 'Tổng số: {{count}} bước chi tiết',
              replace: { count: items.length },
            })}
          </span>
          <div className="flex items-center gap-2">
            <Button type="button" variant="outline" size="sm" onClick={() => onOpenChange(false)}>
              {t('action:cancel', { defaultValue: 'Hủy' })}
            </Button>
            {!isReadOnly && (
              <Button type="button" size="sm" onClick={handleSave}>
                <Check className="w-3.5 h-3.5 mr-1.5" />
                {t('action:saveAndApply', { defaultValue: 'Lưu & Áp dụng' })}
              </Button>
            )}
          </div>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

