const [activeDetailModal, setActiveDetailModal] = useState<{
  originalIndex: number;
  operationName: string;
  productionOperationId: string | null;
  initialDetails: ProcessOperationDetailItem[];
  masterDataDetails: ProcessOperationDetailItem[];
} | null>(null);

const handleOpenDetailModal = useCallback(
  (row: FieldRow, originalIndex: number) => {
    const fkInfo = row.productionOperationId
      ? (operationMap?.get(row.productionOperationId) ??
        (fk.productionOperation.getInfo(row.productionOperationId) as unknown as
          | IProductionOperation
          | undefined))
      : undefined;
    const op = row.productionOperation;
    const opName =
      op?.name ||
      row.productionOperationName ||
      row.productionOperationNameSnapshot ||
      fkInfo?.name ||
      '';

    // Trích xuất toàn bộ chi tiết công đoạn đã cấu hình trong Master Data của công đoạn này
    const masterOpDetails: IProductionOperationDetail[] =
      (fkInfo?.details && fkInfo.details.length > 0 ? fkInfo.details : undefined) ??
      (op && 'details' in op && Array.isArray((op as any).details) ? (op as any).details : undefined) ??
      [];

    const masterDetails: ProcessOperationDetailItem[] = masterOpDetails.map((d, idx) => ({
      productionOperationDetailId: d.id,
      productionOperationDetailCodeSnapshot: d.code || null,
      productionOperationDetailNameSnapshot: d.name || null,
      order: d.sortOrder ?? idx + 1,
    }));

    // Mặc định truyền hết các bước từ Master Data vào modal.
    // Nếu dòng này đã từng được tùy chỉnh (rawDetails có phần tử), giữ nguyên danh sách đã lưu.
    const rawDetails = row.processDetails || [];
    const mappedDetails: ProcessOperationDetailItem[] =
      Array.isArray(rawDetails) && rawDetails.length > 0
        ? (rawDetails as ProcessOperationDetailItem[])
        : masterDetails.length > 0
          ? masterDetails
