const [activeDetailModal, setActiveDetailModal] = useState<{
  originalIndex: number;
  operationName: string;
  productionOperationId: string | null;
  initialDetails: ProcessOperationDetailItem[];
} | null>(null);

const handleOpenDetailModal = useCallback(
  (row: FieldRow, originalIndex: number) => {
    const fkInfo = row.productionOperationId
      ? (operationMap?.get(row.productionOperationId) ??
        (fk.productionOperation.getInfo(row.productionOperationId) as unknown as
          | IProductionOperation
          | undefined))
      : undefined;
    const op = row.productionOperation;
    const opName =
      op?.name ||
      row.productionOperationName ||
      row.productionOperationNameSnapshot ||
      fkInfo?.name ||
      '';

    const rawDetails = row.processDetails || [];
    const mappedDetails: ProcessOperationDetailItem[] =
      Array.isArray(rawDetails) && rawDetails.length > 0
        ? (rawDetails as ProcessOperationDetailItem[])
        : row.productionOperationDetailId
          ? [
              {
                productionOperationDetailId: row.productionOperationDetailId,
                productionOperationDetailCodeSnapshot:
                  row.productionOperationDetailCodeSnapshot || null,
                productionOperationDetailNameSnapshot:
                  row.productionOperationDetailNameSnapshot || null,
                order: 1,
              },
            ]
          : [];

    setActiveDetailModal({
      originalIndex,
      operationName: opName,
      productionOperationId: row.productionOperationId || null,
      initialDetails: mappedDetails,
    });
  },
  [fk, operationMap],
);

const handleSaveDetailModal = useCallback(
  (updatedDetails: ProcessOperationDetailItem[]) => {
    if (!activeDetailModal) return;
    const { originalIndex } = activeDetailModal;
    form.setValue(`processes.${originalIndex}.processDetails`, updatedDetails, {
      shouldDirty: true,
    });
    if (updatedDetails.length > 0) {
      const first = updatedDetails[0];
      form.setValue(
        `processes.${originalIndex}.productionOperationDetailId`,
        first.productionOperationDetailId || null,
        { shouldDirty: true },
      );
      form.setValue(
        `processes.${originalIndex}.productionOperationDetailNameSnapshot`,
        first.productionOperationDetailNameSnapshot || null,
        { shouldDirty: true },
      );
      form.setValue(
        `processes.${originalIndex}.productionOperationDetailCodeSnapshot`,
        first.productionOperationDetailCodeSnapshot || null,
        { shouldDirty: true },
      );
    }
  },
  [activeDetailModal, form],
);

