#region Eligible Packings Query

public async Task<Result<List<InstallationOrderEligiblePackingDto>>> GetEligiblePackingsAsync(GetInstallationOrderEligiblePackingsRequest request)
{
    var result = new List<InstallationOrderEligiblePackingDto>();
    var excludedIds = request.ExcludedPackingIds?.ToHashSet() ?? [];

    if (request.ProjectId.HasValue && request.ProjectId.Value != Guid.Empty)
    {
        var projectId = request.ProjectId.Value;
        var candidatePackingsQuery = _unitOfWork.GetRepository<FinishedGoodsPacking>().Query()
            .Include(p => p.PackingCodes)
            .Include(p => p.MechanicalPackingList)
            .Include(p => p.Details)
                .ThenInclude(d => d.MechanicalPackingListDetail)
            .Where(p => p.PackingCodes.ProjectId == projectId || p.MechanicalPackingList.ProjectId == projectId);

        if (excludedIds.Count > 0)
        {
            candidatePackingsQuery = candidatePackingsQuery.Where(p => !excludedIds.Contains(p.Id));
        }

        var candidatePackings = await candidatePackingsQuery.ToListAsync();

        if (candidatePackings.Count > 0)
        {
            HashSet<Guid> receiptedPackingIds = [];
            try
            {
                var grpcRequest = new GetFgrDetailSummariesRequest();
                grpcRequest.PackingIds.AddRange(candidatePackings.Select(p => p.Id.ToString()));
                var grpcResponse = await _erpGrpcClient.GetFinishedGoodsReceiptDetailSummariesAsync(grpcRequest);
                receiptedPackingIds = grpcResponse.Items
                    .Where(item => Guid.TryParse(item.FinishedGoodsPackingId, out _))
                    .Select(item => Guid.Parse(item.FinishedGoodsPackingId))
                    .ToHashSet();
            }
            catch (Exception ex)
            {
                _logger.Warning(ex, "Không thể lấy thông tin FinishedGoodsReceiptDetail qua gRPC từ ERP");
            }

            var matchedPackings = candidatePackings
                .Where(p => receiptedPackingIds.Contains(p.Id))
                .ToList();

            foreach (var pkg in matchedPackings)
            {
                var fgId = pkg.FinishedGoodId ?? pkg.MechanicalPackingList?.FinishedGoodId;
                var mId = pkg.ModelId ?? pkg.MechanicalPackingList?.ModelId;
                var dmId = pkg.DesignModelId ?? pkg.MechanicalPackingList?.DesignModelId;

                if (!MatchItpKeys(fgId, mId, dmId, request.ItpKeys))
                    continue;

                result.Add(new InstallationOrderEligiblePackingDto
                {
                    Id = pkg.Id,
                    Order = 0,
                    FinishedGoodId = fgId,
                    FinishedGoodCodeSnapshot = pkg.FinishedGoodCodeSnapshot ?? pkg.MechanicalPackingList?.FinishedGoodsCode,
                    FinishedGoodNameSnapshot = pkg.FinishedGoodNameSnapshot ?? pkg.MechanicalPackingList?.FinishedGoodsName,
                    ModelId = mId,
                    ModelCodeSnapshot = pkg.ModelCodeSnapshot ?? pkg.MechanicalPackingList?.ModelCode,
                    ModelNameSnapshot = pkg.ModelNameSnapshot ?? pkg.MechanicalPackingList?.ModelName,
                    DesignModelId = dmId,
                    DesignModelCodeSnapshot = pkg.DesignModelCodeSnapshot ?? pkg.MechanicalPackingList?.DesignModelCode,
                    DesignModelNameSnapshot = pkg.DesignModelNameSnapshot ?? pkg.MechanicalPackingList?.DesignModelName,
                    MechanicalPackingListId = pkg.MechanicalPackingListId != Guid.Empty ? pkg.MechanicalPackingListId : pkg.MechanicalPackingList?.Id,
                    MechanicalPackingListCodeSnapshot = pkg.MechanicalPackingListCodeSnapshot ?? pkg.MechanicalPackingList?.Code,
                    MechanicalPackingListNameSnapshot = pkg.MechanicalPackingListNameSnapshot ?? pkg.MechanicalPackingList?.Code,
                    Details = _mapper.Map<List<FinishedGoodsPackingDetailDto>>(pkg.Details) ?? []
                });
            }
        }
    }

    // Fallback: Nếu không tìm thấy kiện nhập kho (hoặc không truyền ProjectId) nhưng có RefDocId (Lệnh sản xuất)
    if (result.Count == 0 && request.RefDocId.HasValue && request.RefDocId.Value != Guid.Empty)
    {
        var refDocId = request.RefDocId.Value;
        var mplQuery = _unitOfWork.GetRepository<MechanicalPackingList>().Query()
            .Include(m => m.Details)
            .Where(m => m.ProductionOrderId == refDocId);

        if (excludedIds.Count > 0)
        {
            mplQuery = mplQuery.Where(m => !excludedIds.Contains(m.Id));
        }

        var mpls = await mplQuery.ToListAsync();
        foreach (var mpl in mpls)
        {
            if (!MatchItpKeys(mpl.FinishedGoodId, mpl.ModelId, mpl.DesignModelId, request.ItpKeys))
                continue;

            result.Add(new InstallationOrderEligiblePackingDto
            {
                Id = mpl.Id,
                Order = 0,
                FinishedGoodId = mpl.FinishedGoodId,
                FinishedGoodCodeSnapshot = mpl.FinishedGoodCodeSnapshot ?? mpl.FinishedGoodsCode,
                FinishedGoodNameSnapshot = mpl.FinishedGoodNameSnapshot ?? mpl.FinishedGoodsName,
                ModelId = mpl.ModelId,
                ModelCodeSnapshot = mpl.ModelCodeSnapshot ?? mpl.ModelCode,
                ModelNameSnapshot = mpl.ModelNameSnapshot ?? mpl.ModelName,
                DesignModelId = mpl.DesignModelId,
                DesignModelCodeSnapshot = mpl.DesignModelCodeSnapshot ?? mpl.DesignModelCode,
                DesignModelNameSnapshot = mpl.DesignModelNameSnapshot ?? mpl.DesignModelName,
                MechanicalPackingListId = mpl.Id,
                MechanicalPackingListCodeSnapshot = mpl.Code,
                MechanicalPackingListNameSnapshot = mpl.Code,
                Details = mpl.Details?.Select(d => new FinishedGoodsPackingDetailDto
                {
                    Id = d.Id,
                    MechanicalPackingListDetailId = d.Id,
                    LineNum = d.LineNum,
                    ActualQuantity = d.Quantity,
                    ActualWeight = d.DesignWeight,
                    UOMId = d.UOMId,
                    UOMCodeSnapshot = d.UOMCodeSnapshot,
                    UOMNameSnapshot = d.UOMNameSnapshot,
                    SemiFinishedGoodId = d.SemiFinishedGoodId,
                    SemiFinishedGoodCodeSnapshot = d.SemiFinishedGoodCodeSnapshot,
                    SemiFinishedGoodNameSnapshot = d.SemiFinishedGoodNameSnapshot,
                    ProductDescription = d.ProductDescription,
                    TagNo = d.TagNo,
                    DimensionL = d.DimensionL,
                    DimensionW = d.DimensionW,
                    DimensionH = d.DimensionH,
                    DesignQuantity = d.Quantity,
                    DesignWeight = d.DesignWeight,
                    Remark = d.Remark,
                }).ToList() ?? []
            });
        }
    }

    return Result<List<InstallationOrderEligiblePackingDto>>.Success(result);
}

private static bool MatchItpKeys(
    Guid? finishedGoodId,
    Guid? modelId,
    Guid? designModelId,
    List<InstallationOrderItpKeyDto> itpKeys)
{
    if (itpKeys == null || itpKeys.Count == 0)
        return true;

    return itpKeys.Any(itp =>
        (!itp.FinishedGoodId.HasValue || itp.FinishedGoodId == Guid.Empty || itp.FinishedGoodId == finishedGoodId) &&
        (!itp.ModelId.HasValue || itp.ModelId == Guid.Empty || itp.ModelId == modelId) &&
        (!itp.DesignModelId.HasValue || itp.DesignModelId == Guid.Empty || itp.DesignModelId == designModelId));
}

#endregion

