import { useInstallationOrder } from '../../-hooks/use-installation-order';
import type { GetInstallationOrderEligiblePackingsRequest } from '@/types/admin/installation/installation-order.type';
import type { InstallationOrderPackingRow } from '../installation-order-form.schema';

interface PackingSelectionDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  projectId?: string | null;
  refDocId?: string | null;
  onSelect: (packings: InstallationOrderPackingRow[]) => void;
  existingPackingIds: string[];
  itpKeys: {
    finishedGoodId?: string | null;
    modelId?: string | null;
    designModelId?: string | null;
  }[];
}

export function PackingSelectionDialog({
  open,
  onOpenChange,
  projectId,
  refDocId,
  onSelect,
  existingPackingIds,
  itpKeys,
}: PackingSelectionDialogProps) {
  const { t } = useTranslation(['installationOrder', 'action', 'common']);
  const [searchKeyword, setSearchKeyword] = useState('');

  const eligiblePackingsRequest = useMemo<GetInstallationOrderEligiblePackingsRequest>(
    () => ({
      projectId: projectId || undefined,
      refDocId: refDocId || undefined,
      excludedPackingIds: existingPackingIds,
      itpKeys: itpKeys.map((itp) => ({
        finishedGoodId: itp.finishedGoodId || undefined,
        modelId: itp.modelId || undefined,
        designModelId: itp.designModelId || undefined,
      })),
    }),
    [projectId, refDocId, existingPackingIds, itpKeys],
  );

  const { eligiblePackingsQuery } = useInstallationOrder({
    queryParam: {
      eligiblePackings: {
        params: eligiblePackingsRequest,
        isEnable: open && (!!projectId || !!refDocId),
      },
    },
  });

  const [selectedPackings, setSelectedPackings] = useState<
    Record<string, InstallationOrderPackingRow>
  >({});

  useEffect(() => {
    if (open) {
      setSelectedPackings({});
      setSearchKeyword('');
    }
  }, [open]);

  const eligiblePackings = useMemo(() => {
    const rawList = eligiblePackingsQuery.data?.data || [];
    return rawList.map(
      (pkg) =>
        ({
          id: pkg.id,
          order: 0,
          finishedGoodId: pkg.finishedGoodId || null,
          finishedGoodCodeSnapshot: pkg.finishedGoodCodeSnapshot || null,
          finishedGoodNameSnapshot: pkg.finishedGoodNameSnapshot || null,
          modelId: pkg.modelId || null,
          modelCodeSnapshot: pkg.modelCodeSnapshot || null,
          modelNameSnapshot: pkg.modelNameSnapshot || null,
          designModelId: pkg.designModelId || null,
          designModelCodeSnapshot: pkg.designModelCodeSnapshot || null,
          designModelNameSnapshot: pkg.designModelNameSnapshot || null,
          mechanicalPackingListId: pkg.mechanicalPackingListId || null,
          mechanicalPackingListCodeSnapshot: pkg.mechanicalPackingListCodeSnapshot || null,
          mechanicalPackingListNameSnapshot: pkg.mechanicalPackingListNameSnapshot || null,
          details: pkg.details,
        }) as InstallationOrderPackingRow,
    );
  }, [eligiblePackingsQuery.data?.data]);

