import { useFinishedGoodsReceipt } from '@/routes/_app/inventory/finished-goods-receipt/_hooks/use-finished-goods-receipt';
import { useFinishedGoodsPacking } from '@/routes/_app/logistic/finished-goods-packing/_hooks/use-finished-goods-packing';
import { useMechanicalPackingList } from '@/routes/_app/logistic/mechanical-packing-list/_hooks/use-mechanical-packing-list';
import type { InstallationOrderPackingRow } from '../installation-order-form.schema';

interface PackingSelectionDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  projectId?: string | null;
  refDocId?: string | null;
  onSelect: (packings: InstallationOrderPackingRow[]) => void;
  existingPackingIds: string[];
  itpKeys: {
    finishedGoodId?: string | null;
    modelId?: string | null;
    designModelId?: string | null;
  }[];
}

export function PackingSelectionDialog({
  open,
  onOpenChange,
  projectId,
  refDocId,
  onSelect,
  existingPackingIds,
  itpKeys,
}: PackingSelectionDialogProps) {
  const { t } = useTranslation(['installationOrder', 'action', 'common']);
  const [searchKeyword, setSearchKeyword] = useState('');

  // 1. Fetch physically received receipts if projectId is available
  const { getAvailableForSiteDeliveryQuery } = useFinishedGoodsReceipt({
    availableForSiteDelivery: {
      projectId: projectId || '',
      isEnable: open && !!projectId,
    },
  });

  const packingIds = useMemo(() => {
    const receipts = getAvailableForSiteDeliveryQuery.data?.data || [];
    const ids: string[] = [];
    receipts.forEach((r) => {
      r.details?.forEach((d) => {
        if (d.finishedGoodsPackingId) {
          ids.push(d.finishedGoodsPackingId);
        }
      });
    });
    return Array.from(new Set(ids));
  }, [getAvailableForSiteDeliveryQuery.data?.data]);

  // 2. Fetch full FinishedGoodsPacking records (including MechanicalPackingList and Details)
  const { byIdsQuery: packingByIdsQuery } = useFinishedGoodsPacking({
    byIds: {
      ids: packingIds,
      includes: ['MechanicalPackingList', 'Details', 'PackingCodes'],
      isEnable: open && !!projectId && packingIds.length > 0,
    },
  });

  // 3. Fetch mechanical packings as fallback if projectId is missing but refDocId exists
  const { pagingQuery: mechanicalPackingQuery } = useMechanicalPackingList({
    queryParam: {
      paging: {
        params: {
          page: 1,
          pageSize: 1000,
          projectId: projectId || undefined,
          productionOrderId: !projectId && refDocId ? refDocId : undefined,
        },
        filterKeys: ['projectId', 'productionOrderId'],
        isEnable: open && !projectId && !!refDocId,
      },
    },
  });

  const [selectedPackings, setSelectedPackings] = useState<
    Record<string, InstallationOrderPackingRow>
  >({});

  useEffect(() => {
    if (open) {
      setSelectedPackings({});
      setSearchKeyword('');
    }
  }, [open]);

  const eligiblePackings = useMemo(() => {
    const list: InstallationOrderPackingRow[] = [];
    const addedIds = new Set(existingPackingIds);

    if (projectId) {
      // Móc từ FinishedGoodsPacking đã thực nhập kho
      const packings = packingByIdsQuery.data?.data || [];
      packings.forEach((pkg) => {
        if (!pkg.id || addedIds.has(pkg.id)) return;

        const fgId = pkg.finishedGoodId || pkg.mechanicalPackingList?.finishedGoodId;
        const mId = pkg.modelId || pkg.mechanicalPackingList?.modelId;
        const dmId = pkg.designModelId || pkg.mechanicalPackingList?.designModelId;

        // Check combo key match with ITPs
        const isMatch = itpKeys.some((itp) => {
          const matchFg = !itp.finishedGoodId || itp.finishedGoodId === fgId;
          const matchModel = !itp.modelId || itp.modelId === mId;
          const matchDesign = !itp.designModelId || itp.designModelId === dmId;
          return matchFg && matchModel && matchDesign;
        });

        if (isMatch) {
          addedIds.add(pkg.id);
          list.push({
            id: pkg.id,
            order: 0,
            finishedGoodId: fgId || null,
            finishedGoodCodeSnapshot: pkg.mechanicalPackingList?.finishedGoodsCode || null,
            finishedGoodNameSnapshot: pkg.mechanicalPackingList?.finishedGoodsName || null,
            modelId: mId || null,
            modelCodeSnapshot:
              pkg.modelCode || pkg.mechanicalPackingList?.modelCode || null,
            modelNameSnapshot:
              pkg.modelName || pkg.mechanicalPackingList?.modelName || null,
            designModelId: dmId || null,
            designModelCodeSnapshot:
              pkg.designModelCode || pkg.mechanicalPackingList?.designModelCode || null,
            designModelNameSnapshot:
              pkg.designModelName || pkg.mechanicalPackingList?.designModelName || null,
            mechanicalPackingListId:
              pkg.mechanicalPackingListId || pkg.mechanicalPackingList?.id || null,
            mechanicalPackingListCodeSnapshot: pkg.mechanicalPackingList?.code || null,
            mechanicalPackingListNameSnapshot: null,
            details: pkg.details,
          } as InstallationOrderPackingRow);
        }
      });
    } else if (refDocId) {
      // Fallback móc từ MechanicalPackingList
      const mpls = mechanicalPackingQuery.data?.data || [];
      mpls.forEach((mpl) => {
        if (!mpl.id || addedIds.has(mpl.id)) return;

        // Check combo key match
        const isMatch = itpKeys.some((itp) => {
          const matchFg = !itp.finishedGoodId || itp.finishedGoodId === mpl.finishedGoodId;
          const matchModel = !itp.modelId || itp.modelId === mpl.modelId;
          const matchDesign = !itp.designModelId || itp.designModelId === mpl.designModelId;
          return matchFg && matchModel && matchDesign;
        });

        if (isMatch) {
          addedIds.add(mpl.id);
          list.push({
            id: mpl.id,
            order: 0,
            finishedGoodId: mpl.finishedGoodId || null,
            finishedGoodCodeSnapshot: mpl.finishedGoodsCode || null,
            finishedGoodNameSnapshot: mpl.finishedGoodsName || null,
            modelId: mpl.modelId || null,
            modelCodeSnapshot: mpl.modelCode || null,
            modelNameSnapshot: mpl.modelName || null,
            designModelId: mpl.designModelId || null,
            designModelCodeSnapshot: mpl.designModelCode || null,
            designModelNameSnapshot: mpl.designModelName || null,
            mechanicalPackingListId: mpl.id,
            mechanicalPackingListCodeSnapshot: mpl.code || null,
            mechanicalPackingListNameSnapshot: null,
          } as InstallationOrderPackingRow);
        }
      });
    }

    return list;
  }, [
    projectId,
    refDocId,
    packingByIdsQuery.data?.data,
    mechanicalPackingQuery.data?.data,
    existingPackingIds,
    itpKeys,
  ]);

