private IBaseRepository<InstallationOrderRawMat> _rawMatRepo => _unitOfWork.GetRepository<InstallationOrderRawMat>();
private IBaseRepository<InstallationOrderPacking> _packingRepo => _unitOfWork.GetRepository<InstallationOrderPacking>();
private IBaseRepository<FinishedGoodsPacking> _finishedGoodsPackingRepo => _unitOfWork.GetRepository<FinishedGoodsPacking>();
private IBaseRepository<MechanicalPackingList> _mechanicalPackingListRepo => _unitOfWork.GetRepository<MechanicalPackingList>();

#region Eligible Packings Query

public async Task<Result<List<InstallationOrderEligiblePackingDto>>> GetEligiblePackingsAsync(GetInstallationOrderEligiblePackingsRequest request)
{
    var excludedIds = request.ExcludedPackingIds?.ToHashSet() ?? [];

    // 1. Ưu tiên: Lấy các kiện FinishedGoodsPacking đã thực tế nhập kho theo ProjectId
    if (request.ProjectId.HasValue && request.ProjectId.Value != Guid.Empty)
    {
        var packings = await GetReceiptedPackingsByProjectAsync(request.ProjectId.Value, excludedIds, request.ItpKeys);
        if (packings.Count > 0)
            return Result<List<InstallationOrderEligiblePackingDto>>.Success(packings);
    }

    // 2. Fallback: Nếu không tìm thấy kiện nhập kho hoặc không truyền ProjectId, fallback sang MechanicalPackingList theo RefDocId (Lệnh sản xuất)
    if (request.RefDocId.HasValue && request.RefDocId.Value != Guid.Empty)
    {
        var fallbackPackings = await GetFallbackMechanicalPackingsAsync(request.RefDocId.Value, excludedIds, request.ItpKeys);
        return Result<List<InstallationOrderEligiblePackingDto>>.Success(fallbackPackings);
    }

    return Result<List<InstallationOrderEligiblePackingDto>>.Success([]);
}

private async Task<List<InstallationOrderEligiblePackingDto>> GetReceiptedPackingsByProjectAsync(
    Guid projectId,
    HashSet<Guid> excludedIds,
    List<InstallationOrderItpKeyDto> itpKeys)
{
    // Phase 1: Truy vấn danh sách ID ứng viên gọn nhẹ (chỉ SELECT Id, không Include chi tiết) để tránh over-fetching và tải thừa bộ nhớ
    var candidateQuery = _finishedGoodsPackingRepo.Query()
        .AsNoTracking()
        .Where(p => p.PackingCodes.ProjectId == projectId || p.MechanicalPackingList.ProjectId == projectId);

    if (excludedIds.Count > 0)
    {
        candidateQuery = candidateQuery.Where(p => !excludedIds.Contains(p.Id));
    }

    var candidateIds = await candidateQuery
        .Select(p => p.Id)
        .ToListAsync(RequestAborted);

    if (candidateIds.Count == 0)
        return [];

    // Kiểm tra qua gRPC ERP xem kiện nào đã thực sự có phiếu nhập kho thành phẩm
    var receiptedPackingIds = await FetchReceiptedPackingIdsFromErpAsync(candidateIds);
    if (receiptedPackingIds.Count == 0)
        return [];

    // Phase 2: Chỉ eager-load dữ liệu đầy đủ và child collections cho đúng các kiện đã nhập kho
    var matchedPackings = await _finishedGoodsPackingRepo.Query()
        .AsNoTracking()
        .Include(p => p.MechanicalPackingList)
        .Include(p => p.Details)
            .ThenInclude(d => d.MechanicalPackingListDetail)
        .Where(p => receiptedPackingIds.Contains(p.Id))
        .ToListAsync(RequestAborted);

    return matchedPackings
        .Where(pkg => MatchItpKeys(
            pkg.FinishedGoodId ?? pkg.MechanicalPackingList?.FinishedGoodId,
            pkg.ModelId ?? pkg.MechanicalPackingList?.ModelId,
            pkg.DesignModelId ?? pkg.MechanicalPackingList?.DesignModelId,
            itpKeys))
        .Select(MapToEligiblePackingDto)
        .ToList();
}

private async Task<List<InstallationOrderEligiblePackingDto>> GetFallbackMechanicalPackingsAsync(
    Guid refDocId,
    HashSet<Guid> excludedIds,
    List<InstallationOrderItpKeyDto> itpKeys)
{
    var mplQuery = _mechanicalPackingListRepo.Query()
        .AsNoTracking()
        .Include(m => m.Details)
        .Where(m => m.ProductionOrderId == refDocId);

    if (excludedIds.Count > 0)
    {
        mplQuery = mplQuery.Where(m => !excludedIds.Contains(m.Id));
    }

    var mpls = await mplQuery.ToListAsync(RequestAborted);

    return mpls
        .Where(mpl => MatchItpKeys(mpl.FinishedGoodId, mpl.ModelId, mpl.DesignModelId, itpKeys))
        .Select(MapToEligiblePackingDto)
        .ToList();
}

private async Task<HashSet<Guid>> FetchReceiptedPackingIdsFromErpAsync(List<Guid> candidateIds)
{
    try
    {
        var grpcRequest = new GetFgrDetailSummariesRequest();
        grpcRequest.PackingIds.AddRange(candidateIds.Select(p => p.ToString()));
        var grpcResponse = await _erpGrpcClient.GetFinishedGoodsReceiptDetailSummariesAsync(
            grpcRequest,
            cancellationToken: RequestAborted);

        return grpcResponse.Items
            .Where(item => Guid.TryParse(item.FinishedGoodsPackingId, out _))
            .Select(item => Guid.Parse(item.FinishedGoodsPackingId))
            .ToHashSet();
    }
    catch (Exception ex)
    {
        _logger.Warning(ex, "Không thể lấy thông tin FinishedGoodsReceiptDetail qua gRPC từ ERP");
        return [];
    }
}

private InstallationOrderEligiblePackingDto MapToEligiblePackingDto(FinishedGoodsPacking pkg)
{
    return new InstallationOrderEligiblePackingDto
    {
        Id = pkg.Id,
        Order = 0,
        FinishedGoodId = pkg.FinishedGoodId ?? pkg.MechanicalPackingList?.FinishedGoodId,
        FinishedGoodCodeSnapshot = pkg.FinishedGoodCodeSnapshot ?? pkg.MechanicalPackingList?.FinishedGoodsCode,
        FinishedGoodNameSnapshot = pkg.FinishedGoodNameSnapshot ?? pkg.MechanicalPackingList?.FinishedGoodsName,
        ModelId = pkg.ModelId ?? pkg.MechanicalPackingList?.ModelId,
        ModelCodeSnapshot = pkg.ModelCodeSnapshot ?? pkg.MechanicalPackingList?.ModelCodeSnapshot,
        ModelNameSnapshot = pkg.ModelNameSnapshot ?? pkg.MechanicalPackingList?.ModelNameSnapshot,
        DesignModelId = pkg.DesignModelId ?? pkg.MechanicalPackingList?.DesignModelId,
        DesignModelCodeSnapshot = pkg.DesignModelCodeSnapshot ?? pkg.MechanicalPackingList?.DesignModelCodeSnapshot,
        DesignModelNameSnapshot = pkg.DesignModelNameSnapshot ?? pkg.MechanicalPackingList?.DesignModelNameSnapshot,
        MechanicalPackingListId = pkg.MechanicalPackingListId != Guid.Empty ? pkg.MechanicalPackingListId : pkg.MechanicalPackingList?.Id,
        MechanicalPackingListCodeSnapshot = pkg.MechanicalPackingListCodeSnapshot ?? pkg.MechanicalPackingList?.Code,
        MechanicalPackingListNameSnapshot = pkg.MechanicalPackingListNameSnapshot ?? pkg.MechanicalPackingList?.Code,
