const EMPTY_ITEMS: ProcessOperationDetailItem[] = [];

export function ProcessOperationDetailModal({
  open,
  onOpenChange,
  operationName,
  productionOperationId,
  initialDetails = EMPTY_ITEMS,
  masterDataDetails = EMPTY_ITEMS,
  onSave,
  isReadOnly = false,
}: ProcessOperationDetailModalProps) {
  const { t } = useTranslation(['installationOrder', 'action', 'common']);

  // Fetch details from master data API if not provided in masterDataDetails prop
  const { data: fetchedMasterDetails, isLoading: isFetchingMasterDetails } = useQuery({
    queryKey: ['production-operation-master-details', productionOperationId],
    queryFn: async () => {
      if (!productionOperationId) return EMPTY_ITEMS;
      const res = await productionOperationService.getById({
        id: productionOperationId,
        includes: 'Details',
      });
      return (res.data?.details ?? []).map((d: IProductionOperationDetail, idx: number) => ({
        productionOperationDetailId: d.id,
        productionOperationDetailCodeSnapshot: d.code || null,
        productionOperationDetailNameSnapshot: d.name || null,
        order: d.sortOrder ?? idx + 1,
      }));
    },
    enabled:
      open && !!productionOperationId && masterDataDetails.length === 0,
    staleTime: 5 * 60 * 1000,
  });

  const effectiveMasterDetails = useMemo(() => {
    if (masterDataDetails && masterDataDetails.length > 0) return masterDataDetails;
    return fetchedMasterDetails ?? EMPTY_ITEMS;
  }, [masterDataDetails, fetchedMasterDetails]);

  const [items, setItems] = useState<ProcessOperationDetailItem[]>(() => {
    if (initialDetails && initialDetails.length > 0) {
      return initialDetails.map((item, idx) => ({
        ...item,
        order: item.order ?? idx + 1,
      }));
    }
    if (masterDataDetails && masterDataDetails.length > 0) {
      return masterDataDetails.map((item, idx) => ({
        ...item,
        order: item.order ?? idx + 1,
      }));
    }
    return [];
  });

  const [selectedDetailId, setSelectedDetailId] = useState<string>('');

  // When fetchedMasterDetails loads from API:
  // 1. If items was empty and initialDetails was empty, populate from master data.
  // 2. If items already has items (e.g. from initialDetails), backfill any missing name snapshot.
  useEffect(() => {
    if (!fetchedMasterDetails || fetchedMasterDetails.length === 0) return;

    setItems((prevItems) => {
      if (prevItems.length === 0 && initialDetails.length === 0) {
        return fetchedMasterDetails.map((item, idx) => ({
          ...item,
          order: item.order ?? idx + 1,
        }));
      }

      let hasUpdates = false;
      const updated = prevItems.map((item) => {
        if (!item.productionOperationDetailNameSnapshot) {
          const matched = fetchedMasterDetails.find(
            (m) =>
              (item.productionOperationDetailId &&
                m.productionOperationDetailId === item.productionOperationDetailId) ||
              (item.productionOperationDetailCodeSnapshot &&
                m.productionOperationDetailCodeSnapshot ===
                  item.productionOperationDetailCodeSnapshot),
          );
          if (matched?.productionOperationDetailNameSnapshot) {
            hasUpdates = true;
            return {
              ...item,
              productionOperationDetailNameSnapshot:
                matched.productionOperationDetailNameSnapshot,
              productionOperationDetailCodeSnapshot:
                item.productionOperationDetailCodeSnapshot ||
                matched.productionOperationDetailCodeSnapshot,
            };
          }
        }
        return item;
      });

      return hasUpdates ? updated : prevItems;
    });
  }, [fetchedMasterDetails, initialDetails.length]);

  // Chỉ cho phép thêm những chi tiết công đoạn đã load từ master data mà chưa có trong danh sách
  const availableToAdd = useMemo(() => {
    const currentIds = new Set(items.map((i) => i.productionOperationDetailId).filter(Boolean));
    return effectiveMasterDetails.filter(
      (d) => d.productionOperationDetailId && !currentIds.has(d.productionOperationDetailId),
    );
  }, [effectiveMasterDetails, items]);

  const comboboxOptions = useMemo<ComboboxOption<IFlatItem>[]>(
    () =>
      availableToAdd.map((d) => {
        const code = d.productionOperationDetailCodeSnapshot || '';
        const name = d.productionOperationDetailNameSnapshot || '';
        const label = name ? (code && code !== name ? `[${code}] ${name}` : name) : code;
        return {
          value: d.productionOperationDetailId!,
          label,
          code: code || undefined,
        };
      }),
    [availableToAdd],
  );

  const handleAddDetail = useCallback(() => {
    if (!selectedDetailId) return;
    const target = effectiveMasterDetails.find(
      (d) => d.productionOperationDetailId === selectedDetailId,
    );
    if (!target) return;

    setItems((prev) => [
      ...prev,
      {
        productionOperationDetailId: target.productionOperationDetailId,
        productionOperationDetailCodeSnapshot: target.productionOperationDetailCodeSnapshot || null,
        productionOperationDetailNameSnapshot: target.productionOperationDetailNameSnapshot || null,
        order: prev.length + 1,
      },
    ]);
    setSelectedDetailId('');
  }, [selectedDetailId, effectiveMasterDetails]);

  const handleDeleteDetail = useCallback((index: number) => {
    setItems((prev) =>
      prev.filter((_, i) => i !== index).map((item, i) => ({ ...item, order: i + 1 })),
    );
  }, []);

  const handleReorder = useCallback((fromIndex: number, toIndex: number) => {
    setItems((prev) => {
      const next = [...prev];
      const [moved] = next.splice(fromIndex, 1);
      next.splice(toIndex, 0, moved);
      return next.map((item, i) => ({ ...item, order: i + 1 }));
    });
  }, []);

  const handleSave = useCallback(() => {
    const enriched = items.map((item) => {
      if (!item.productionOperationDetailNameSnapshot) {
        const matched = effectiveMasterDetails.find(
          (m) =>
            (item.productionOperationDetailId &&
              m.productionOperationDetailId === item.productionOperationDetailId) ||
            (item.productionOperationDetailCodeSnapshot &&
              m.productionOperationDetailCodeSnapshot ===
                item.productionOperationDetailCodeSnapshot),
        );
        if (matched?.productionOperationDetailNameSnapshot) {
          return {
            ...item,
            productionOperationDetailNameSnapshot:
              matched.productionOperationDetailNameSnapshot,
            productionOperationDetailCodeSnapshot:
              item.productionOperationDetailCodeSnapshot ||
              matched.productionOperationDetailCodeSnapshot,
          };
        }
      }
      return item;
    });
    onSave(enriched);
    onOpenChange(false);
  }, [items, effectiveMasterDetails, onSave, onOpenChange]);

  const columns = useMemo<SortableWrapTableColumn<ProcessOperationDetailItem>[]>(
    () => [
      {
        id: 'stt',
        header: t('common:stt', { defaultValue: 'STT' }),
        defaultWidth: 65,
        minWidth: 50,
        maxWidth: 80,
        headerAlign: 'center',
        cellAlign: 'center',
        cell: (_row, displayIndex) => (
          <span className="text-muted-foreground font-medium text-xs">{displayIndex + 1}</span>
        ),
      },
      {
        id: 'productionOperationDetailNameSnapshot',
        header: t('installationOrder:columnTitle.operationDetail', {
          defaultValue: 'Chi tiết công đoạn',
        }),
        defaultWidth: 340,
        minWidth: 200,
        cell: (row) => {
          const matchedMaster = effectiveMasterDetails.find(
            (m) =>
              (row.productionOperationDetailId &&
                m.productionOperationDetailId === row.productionOperationDetailId) ||
              (row.productionOperationDetailCodeSnapshot &&
                m.productionOperationDetailCodeSnapshot ===
                  row.productionOperationDetailCodeSnapshot),
          );
          const name =
            row.productionOperationDetailNameSnapshot ||
            matchedMaster?.productionOperationDetailNameSnapshot ||
            row.productionOperationDetailCodeSnapshot ||
            '—';
          const code =
            row.productionOperationDetailCodeSnapshot ||
            matchedMaster?.productionOperationDetailCodeSnapshot;

          return (
            <div className="flex flex-col text-xs">
              <span className="font-semibold text-foreground">{name}</span>
              {code && code !== name && (
                <span className="text-[10px] text-muted-foreground">
                  #{code}
                </span>
              )}
            </div>
          );
        },
      },
      ...(!isReadOnly
        ? [
            {
              id: 'actions',
              header: '',
              defaultWidth: 50,
              minWidth: 40,
              maxWidth: 60,
              cellAlign: 'center',
              cell: (_row, displayIndex) => (
                <RowActionButton
                  icon={Trash2}
                  title={t('action:delete', { defaultValue: 'Xóa' })}
                  variant="destructive"
                  onClick={() => handleDeleteDetail(displayIndex)}
                />
              ),
            } as SortableWrapTableColumn<ProcessOperationDetailItem>,
          ]
        : []),
    ],
    [isReadOnly, t, handleDeleteDetail, effectiveMasterDetails],
  );

