const handleOpenDetailModal = useCallback(
  (row: FieldRow, originalIndex: number) => {
    // Luôn lấy giá trị mới nhất từ form để tránh dữ liệu cũ (stale) từ row của useFieldArray
    const currentProcess =
      (form.getValues(`processes.${originalIndex}`) as FieldRow) || row;
    const opId = currentProcess.productionOperationId || null;

    const fkInfo = opId
      ? (operationMap?.get(opId) ??
        (fk.productionOperation.getInfo(opId) as unknown as
          | IProductionOperation
          | undefined))
      : undefined;
    const op = currentProcess.productionOperation || fkInfo;
    const opName =
      op?.name ||
      currentProcess.productionOperationName ||
      currentProcess.productionOperationNameSnapshot ||
      fkInfo?.name ||
      '';

    // Trích xuất toàn bộ chi tiết công đoạn đã cấu hình trong Master Data của công đoạn này
    const masterOpDetails: IProductionOperationDetail[] =
      (fkInfo?.details && fkInfo.details.length > 0 ? fkInfo.details : undefined) ??
