const [items, setItems] = useState<ProcessOperationDetailItem[]>(() => {
  if (initialDetails && initialDetails.length > 0) {
    return initialDetails.map((item, idx) => ({
      ...item,
      order: item.order ?? idx + 1,
    }));
  }
  if (masterDataDetails && masterDataDetails.length > 0) {
    return masterDataDetails.map((item, idx) => ({
      ...item,
      order: item.order ?? idx + 1,
    }));
  }
  return [];
});

const [selectedDetailId, setSelectedDetailId] = useState<string>('');

// Đồng bộ lại items khi modal mở hoặc productionOperationId thay đổi
useEffect(() => {
  if (open) {
    if (initialDetails && initialDetails.length > 0) {
      setItems(
        initialDetails.map((item, idx) => ({
          ...item,
          order: item.order ?? idx + 1,
        })),
      );
    } else if (masterDataDetails && masterDataDetails.length > 0) {
      setItems(
        masterDataDetails.map((item, idx) => ({
          ...item,
          order: item.order ?? idx + 1,
        })),
      );
    } else {
      setItems([]);
    }
    setSelectedDetailId('');
  }
}, [open, productionOperationId, initialDetails, masterDataDetails]);

// Khi fetchedMasterDetails tải xong từ API:
// 1. Nếu ban đầu không có initialDetails tùy chỉnh, áp dụng toàn bộ từ Master Data (hoặc rỗng nếu không có).
// 2. Nếu đã có initialDetails, điền bù tên/mã snapshot còn thiếu.
useEffect(() => {
  if (!open || !productionOperationId || fetchedMasterDetails === undefined) return;

  if (initialDetails.length === 0) {
    setItems(
      fetchedMasterDetails.map((item, idx) => ({
        ...item,
        order: item.order ?? idx + 1,
      })),
    );
  } else {
    setItems((prevItems) => {
      let hasUpdates = false;
      const updated = prevItems.map((item) => {
        if (!item.productionOperationDetailNameSnapshot) {
          const matched = fetchedMasterDetails.find(
            (m) =>
              (item.productionOperationDetailId &&
                m.productionOperationDetailId === item.productionOperationDetailId) ||
              (item.productionOperationDetailCodeSnapshot &&
                m.productionOperationDetailCodeSnapshot ===
                  item.productionOperationDetailCodeSnapshot),
          );
          if (matched?.productionOperationDetailNameSnapshot) {
            hasUpdates = true;
            return {
              ...item,
              productionOperationDetailNameSnapshot:
                matched.productionOperationDetailNameSnapshot,
              productionOperationDetailCodeSnapshot:
                item.productionOperationDetailCodeSnapshot ||
                matched.productionOperationDetailCodeSnapshot,
            };
          }
        }
        return item;
      });

      return hasUpdates ? updated : prevItems;
    });
  }
}, [open, productionOperationId, fetchedMasterDetails, initialDetails.length]);

