public async Task<Result<List<InstallationOrderEligiblePackingDto>>> GetEligiblePackingsAsync(GetInstallationOrderEligiblePackingsRequest request)
{
    var excludedIds = request.ExcludedPackingIds?.ToHashSet() ?? [];

    // 1. Ưu tiên: Lấy các kiện FinishedGoodsPacking đã thực tế nhập kho theo ProjectId
    if (request.ProjectId.HasValue && request.ProjectId.Value != Guid.Empty)
    {
        var packings = await GetReceiptedPackingsByProjectAsync(request.ProjectId.Value, excludedIds, request.ItpKeys);
        if (packings.Count > 0)
        {
            EnrichMissingSnapshots(packings, request.ItpKeys);
            return Result<List<InstallationOrderEligiblePackingDto>>.Success(packings);
        }
    }

    // 2. Fallback: Nếu không tìm thấy kiện nhập kho hoặc không truyền ProjectId, fallback sang MechanicalPackingList theo RefDocId (Lệnh sản xuất)
    if (request.RefDocId.HasValue && request.RefDocId.Value != Guid.Empty)
    {
        var fallbackPackings = await GetFallbackMechanicalPackingsAsync(request.RefDocId.Value, excludedIds, request.ItpKeys);
        EnrichMissingSnapshots(fallbackPackings, request.ItpKeys);
        return Result<List<InstallationOrderEligiblePackingDto>>.Success(fallbackPackings);
    }

    return Result<List<InstallationOrderEligiblePackingDto>>.Success([]);
}

private async Task<List<InstallationOrderEligiblePackingDto>> GetReceiptedPackingsByProjectAsync(
    Guid projectId,
    HashSet<Guid> excludedIds,
    List<InstallationOrderItpKeyDto> itpKeys)
{
    // Phase 1: Truy vấn danh sách ID ứng viên gọn nhẹ (chỉ SELECT Id, không Include chi tiết) để tránh over-fetching và tải thừa bộ nhớ
    var candidateQuery = _finishedGoodsPackingRepo.Query()
        .AsNoTracking()
        .Where(p => p.PackingCodes.ProjectId == projectId || p.MechanicalPackingList.ProjectId == projectId);

    if (excludedIds.Count > 0)
    {
        candidateQuery = candidateQuery.Where(p =>
            !excludedIds.Contains(p.Id) &&
            (!p.MechanicalPackingListId.HasValue || !excludedIds.Contains(p.MechanicalPackingListId.Value)));
    }

    var candidateIds = await candidateQuery
        .Select(p => p.Id)
        .ToListAsync(RequestAborted);

    if (candidateIds.Count == 0)
        return [];

    // Kiểm tra qua gRPC ERP xem kiện nào đã thực sự có phiếu nhập kho thành phẩm
    var receiptedPackingIds = await FetchReceiptedPackingIdsFromErpAsync(candidateIds);
    if (receiptedPackingIds.Count == 0)
        return [];

    // Phase 2: Chỉ eager-load dữ liệu đầy đủ và child collections cho đúng các kiện đã nhập kho
    var matchedPackings = await _finishedGoodsPackingRepo.Query()
        .AsNoTracking()
        .Include(p => p.MechanicalPackingList)
        .Include(p => p.Details)
            .ThenInclude(d => d.MechanicalPackingListDetail)
        .Where(p => receiptedPackingIds.Contains(p.Id))
        .ToListAsync(RequestAborted);

    return matchedPackings
        .Where(pkg => MatchItpKeys(
            pkg.FinishedGoodId ?? pkg.MechanicalPackingList?.FinishedGoodId,
            pkg.ModelId ?? pkg.MechanicalPackingList?.ModelId,
            pkg.DesignModelId ?? pkg.MechanicalPackingList?.DesignModelId,
            itpKeys))
        .Select(MapToEligiblePackingDto)
        .ToList();
}

private async Task<List<InstallationOrderEligiblePackingDto>> GetFallbackMechanicalPackingsAsync(
    Guid refDocId,
    HashSet<Guid> excludedIds,
    List<InstallationOrderItpKeyDto> itpKeys)
{
    var mplQuery = _mechanicalPackingListRepo.Query()
        .AsNoTracking()
        .Include(m => m.Details)
        .Where(m => m.ProductionOrderId == refDocId);

    if (excludedIds.Count > 0)
    {
        mplQuery = mplQuery.Where(m => !excludedIds.Contains(m.Id));
    }

    var mpls = await mplQuery.ToListAsync(RequestAborted);

    return mpls
        .Where(mpl => MatchItpKeys(mpl.FinishedGoodId, mpl.ModelId, mpl.DesignModelId, itpKeys))
        .Select(MapToEligiblePackingDto)
        .ToList();
}

private static void EnrichMissingSnapshots(
    List<InstallationOrderEligiblePackingDto> dtos,
    List<InstallationOrderItpKeyDto> itpKeys)
{
    if (itpKeys == null || itpKeys.Count == 0 || dtos == null || dtos.Count == 0)
        return;

    foreach (var dto in dtos)
    {
        // 1. Khớp chính xác cả FinishedGoodId + ModelId + DesignModelId
        var matched = itpKeys.FirstOrDefault(k =>
            (k.FinishedGoodId == dto.FinishedGoodId || k.FinishedGoodId == null) &&
            (k.ModelId == dto.ModelId || k.ModelId == null) &&
            (k.DesignModelId == dto.DesignModelId || k.DesignModelId == null));

        // 2. Fallback: Khớp theo FinishedGoodId
        matched ??= itpKeys.FirstOrDefault(k => k.FinishedGoodId == dto.FinishedGoodId);

        // 3. Fallback: Khớp theo ModelId hoặc DesignModelId
        matched ??= itpKeys.FirstOrDefault(k =>
            (dto.ModelId.HasValue && k.ModelId == dto.ModelId) ||
            (dto.DesignModelId.HasValue && k.DesignModelId == dto.DesignModelId));

        if (matched != null)
        {
            if (string.IsNullOrEmpty(dto.ModelCodeSnapshot)) dto.ModelCodeSnapshot = matched.ModelCodeSnapshot;
            if (string.IsNullOrEmpty(dto.ModelNameSnapshot)) dto.ModelNameSnapshot = matched.ModelNameSnapshot;
            if (string.IsNullOrEmpty(dto.DesignModelCodeSnapshot)) dto.DesignModelCodeSnapshot = matched.DesignModelCodeSnapshot;
            if (string.IsNullOrEmpty(dto.DesignModelNameSnapshot)) dto.DesignModelNameSnapshot = matched.DesignModelNameSnapshot;
            if (string.IsNullOrEmpty(dto.FinishedGoodCodeSnapshot)) dto.FinishedGoodCodeSnapshot = matched.FinishedGoodCodeSnapshot;
            if (string.IsNullOrEmpty(dto.FinishedGoodNameSnapshot)) dto.FinishedGoodNameSnapshot = matched.FinishedGoodNameSnapshot;
        }
    }
}

