  const { t } = useTranslation(['installationOrder', 'action', 'common']);
  const [searchKeyword, setSearchKeyword] = useState('');
  const [activePreviewPacking, setActivePreviewPacking] = useState<{
    title: string;
    details: PackingDetailItem[];
  } | null>(null);

  // HashMap để tra cứu nhanh các cụm đã tồn tại và ngăn chặn trùng lặp tuyệt đối
  const existingPackingMap = useMemo(() => {
    const map = new Map<string, boolean>();
    existingPackingIds.forEach((id) => {
      if (id) map.set(id, true);
    });
    return map;
  }, [existingPackingIds]);

  // HashMap liên kết ITP Keys từ tab Thành phẩm để bổ sung tên/mã snapshot Model nếu thiếu
  const itpMap = useMemo(() => {
    const map = new Map<string, (typeof itpKeys)[number]>();
    itpKeys.forEach((itp) => {
      if (itp.finishedGoodId && itp.modelId) map.set(`${itp.finishedGoodId}_${itp.modelId}`, itp);
      if (itp.finishedGoodId) map.set(`fg_${itp.finishedGoodId}`, itp);
      if (itp.modelId) map.set(`model_${itp.modelId}`, itp);
      if (itp.designModelId) map.set(`design_${itp.designModelId}`, itp);
    });
    return map;
  }, [itpKeys]);

  const eligiblePackingsRequest = useMemo<GetInstallationOrderEligiblePackingsRequest>(
    () => ({
      projectId: projectId || undefined,
      refDocId: refDocId || undefined,
      excludedPackingIds: existingPackingIds,
      itpKeys: itpKeys.map((itp) => ({
        finishedGoodId: itp.finishedGoodId || undefined,
        modelId: itp.modelId || undefined,
        designModelId: itp.designModelId || undefined,
        modelCodeSnapshot: itp.modelCodeSnapshot || undefined,
        modelNameSnapshot: itp.modelNameSnapshot || undefined,
        designModelCodeSnapshot: itp.designModelCodeSnapshot || undefined,
        designModelNameSnapshot: itp.designModelNameSnapshot || undefined,
        finishedGoodCodeSnapshot: itp.finishedGoodCodeSnapshot || undefined,
        finishedGoodNameSnapshot: itp.finishedGoodNameSnapshot || undefined,
      })),
    }),
    [projectId, refDocId, existingPackingIds, itpKeys],
  );

  const { eligiblePackingsQuery } = useInstallationOrder({
    queryParam: {
      eligiblePackings: {
        params: eligiblePackingsRequest,
        isEnable: open && (!!projectId || !!refDocId),
      },
    },
  });

  const [selectedPackings, setSelectedPackings] = useState<
    Record<string, InstallationOrderPackingRow>
  >({});

  useEffect(() => {
    if (open) {
      setSelectedPackings({});
      setSearchKeyword('');
    }
  }, [open]);

  const eligiblePackings = useMemo<InstallationOrderPackingRow[]>(() => {
    const rawList = eligiblePackingsQuery.data?.data || [];
    return rawList.map((pkg): InstallationOrderPackingRow => ({
      id: pkg.id,
      order: pkg.order ?? 0,
      finishedGoodId: pkg.finishedGoodId || null,
      finishedGoodCodeSnapshot: pkg.finishedGoodCodeSnapshot || null,
      finishedGoodNameSnapshot: pkg.finishedGoodNameSnapshot || null,
      modelId: pkg.modelId || null,
      modelCodeSnapshot: pkg.modelCodeSnapshot || null,
      modelNameSnapshot: pkg.modelNameSnapshot || null,
      designModelId: pkg.designModelId || null,
      designModelCodeSnapshot: pkg.designModelCodeSnapshot || null,
      designModelNameSnapshot: pkg.designModelNameSnapshot || null,
      mechanicalPackingListId: pkg.mechanicalPackingListId || null,
      mechanicalPackingListCodeSnapshot: pkg.mechanicalPackingListCodeSnapshot || null,
      mechanicalPackingListNameSnapshot: pkg.mechanicalPackingListNameSnapshot || null,
      details: pkg.details,
    }));
  }, [eligiblePackingsQuery.data?.data]);

  // Tra cứu bổ sung tên Model từ API nếu cả snapshot lẫn itpKeys đều thiếu
  const fk = useFkLookup(eligiblePackings, [
    {
      key: 'model',
      extractIds: (rows) =>
        rows
          .flatMap((r) => [r?.modelId, r?.designModelId])
          .filter(Boolean) as string[],
      fetchByIds: (ids) => modelService.getByIds({ ids }),
    },
  ]);

  const filteredPackings = useMemo(() => {
    const kw = searchKeyword.trim().toLowerCase();
    if (!kw) return eligiblePackings;
    return eligiblePackings.filter((row) => {
      const terms = [
        row.finishedGoodCodeSnapshot,
        row.finishedGoodNameSnapshot,
        row.modelCodeSnapshot,
        row.modelNameSnapshot,
        row.designModelCodeSnapshot,
        row.designModelNameSnapshot,
        row.mechanicalPackingListCodeSnapshot,
        row.mechanicalPackingListNameSnapshot,
      ]
        .filter(Boolean)
        .join(' ')
        .toLowerCase();
      return terms.includes(kw);
    });
  }, [eligiblePackings, searchKeyword]);

  // Chỉ cho phép chọn các cụm chưa từng được thêm vào lệnh
  const selectablePackings = useMemo(
    () =>
      filteredPackings.filter((p) => {
        const isAlreadyAdded =
          (p.mechanicalPackingListId && existingPackingMap.has(p.mechanicalPackingListId)) ||
          (p.id && existingPackingMap.has(p.id));
        return !isAlreadyAdded;
      }),
    [filteredPackings, existingPackingMap],
  );

  const isAllSelected =
    selectablePackings.length > 0 &&
    selectablePackings.every((p, idx) => {
      const key = p.mechanicalPackingListId || p.id || `${idx}`;
      return !!selectedPackings[key];
    });

  const handleToggleSelectAll = useCallback(() => {
    if (selectablePackings.length === 0) return;
    if (isAllSelected) {
      setSelectedPackings((prev) => {
        const next = { ...prev };
        selectablePackings.forEach((p, idx) => {
          const key = p.mechanicalPackingListId || p.id || `${idx}`;
          delete next[key];
        });
        return next;
      });
    } else {
      setSelectedPackings((prev) => {
        const next = { ...prev };
        selectablePackings.forEach((p, idx) => {
          const key = p.mechanicalPackingListId || p.id || `${idx}`;
          next[key] = p;
        });
        return next;
      });
    }
  }, [isAllSelected, selectablePackings]);

  const columns: ResizableWrapTableColumn<InstallationOrderPackingRow>[] = useMemo(
    () => [
      {
        id: 'select',
        header: '',
        defaultWidth: 50,
        minWidth: 45,
        headerAlign: 'center',
        cellClassName: 'text-center',
        headerCell: () => (
          <div className="flex justify-center items-center">
            <Checkbox
              checked={isAllSelected}
              onCheckedChange={() => handleToggleSelectAll()}
              disabled={selectablePackings.length === 0}
            />
          </div>
        ),
        cell: (row, idx) => {
          const key = row.mechanicalPackingListId || row.id || `${idx}`;
          const isAlreadyAdded =
            (row.mechanicalPackingListId && existingPackingMap.has(row.mechanicalPackingListId)) ||
            (row.id && existingPackingMap.has(row.id));
          const isSelected = isAlreadyAdded || !!selectedPackings[key];

          return (
            <div className="flex justify-center items-center">
              <Checkbox
                checked={isSelected}
                disabled={isAlreadyAdded}
                title={
                  isAlreadyAdded
                    ? t('installationOrder:status.alreadyAdded', { defaultValue: 'Đã thêm vào lệnh lắp đặt' })
                    : undefined
                }
                onCheckedChange={(checked) => {
                  if (isAlreadyAdded) return;
                  if (checked) {
                    setSelectedPackings((prev) => ({ ...prev, [key]: row }));
                  } else {
                    setSelectedPackings((prev) => {
                      const next = { ...prev };
                      delete next[key];
                      return next;
                    });
                  }
                }}
              />
            </div>
          );
        },
      },
      {
        id: 'stt',
        header: t('common:stt', { defaultValue: 'STT' }),
        defaultWidth: 55,
        minWidth: 50,
        headerAlign: 'center',
        cellClassName: 'text-center',
        cell: (_row, idx) => (
          <span className="text-xs font-medium text-muted-foreground">{idx + 1}</span>
        ),
      },
      // 1. Mã ITP
      {
        id: 'finishedGood',
        header: t('installationOrder:columnTitle.finishedGoodCode', { defaultValue: 'Mã ITP' }),
        defaultWidth: 180,
        minWidth: 150,
        cell: (row) => {
          const matchedItp =
            (row.finishedGoodId && row.modelId ? itpMap.get(`${row.finishedGoodId}_${row.modelId}`) : undefined) ??
            (row.finishedGoodId ? itpMap.get(`fg_${row.finishedGoodId}`) : undefined);
          const name = row.finishedGoodNameSnapshot || matchedItp?.finishedGoodNameSnapshot;
          const code = row.finishedGoodCodeSnapshot || matchedItp?.finishedGoodCodeSnapshot;
          return (
            <DoubleLineCell
              title={name}
              subtitle={code ? `#${code}` : undefined}
              fallback="—"
            />
          );
        },
      },
      // 2. Model thiết kế
      {
        id: 'designModel',
        header: t('installationOrder:columnTitle.designModel', { defaultValue: 'Model thiết kế' }),
        defaultWidth: 150,
        minWidth: 130,
        cell: (row) => {
          const matchedItp =
            (row.finishedGoodId && row.modelId ? itpMap.get(`${row.finishedGoodId}_${row.modelId}`) : undefined) ??
            (row.designModelId ? itpMap.get(`design_${row.designModelId}`) : undefined) ??
            (row.finishedGoodId ? itpMap.get(`fg_${row.finishedGoodId}`) : undefined);
          const fkInfo = row.designModelId ? fk.model.getInfo(row.designModelId) : undefined;
          const name = row.designModelNameSnapshot || matchedItp?.designModelNameSnapshot || fkInfo?.name;
          const code = row.designModelCodeSnapshot || matchedItp?.designModelCodeSnapshot || fkInfo?.code;
          return <DoubleLineCell title={name} subtitle={code} fallback="—" />;
        },
      },
      // 3. Model hiệu suất
      {
        id: 'model',
        header: t('installationOrder:columnTitle.model', { defaultValue: 'Model hiệu suất' }),
        defaultWidth: 150,
        minWidth: 130,
        cell: (row) => {
          const matchedItp =
            (row.finishedGoodId && row.modelId ? itpMap.get(`${row.finishedGoodId}_${row.modelId}`) : undefined) ??
            (row.modelId ? itpMap.get(`model_${row.modelId}`) : undefined) ??
            (row.finishedGoodId ? itpMap.get(`fg_${row.finishedGoodId}`) : undefined);
          const fkInfo = row.modelId ? fk.model.getInfo(row.modelId) : undefined;
          const name = row.modelNameSnapshot || matchedItp?.modelNameSnapshot || fkInfo?.name;
          const code = row.modelCodeSnapshot || matchedItp?.modelCodeSnapshot || fkInfo?.code;
          return <DoubleLineCell title={name} subtitle={code} fallback="—" />;
        },
      },
      // 4. Mã / Tên Packing List Cơ Khí (Kèm icon con mắt 👁️ xem chi tiết)
      {
        id: 'mechanicalPackingList',
        header: t('installationOrder:columnTitle.mechanicalPackingList', {
          defaultValue: 'Mã / Tên Packing List Cơ Khí',
        }),
        defaultWidth: 240,
        minWidth: 190,
        cell: (row) => {
          const isAlreadyAdded =
            (row.mechanicalPackingListId && existingPackingMap.has(row.mechanicalPackingListId)) ||
            (row.id && existingPackingMap.has(row.id));

          return (
            <div className="flex items-center justify-between gap-1 w-full">
              <div className="flex items-center gap-1.5 min-w-0">
                <DoubleLineCell
                  title={row.mechanicalPackingListNameSnapshot}
                  subtitle={
                    row.mechanicalPackingListCodeSnapshot
                      ? `#${row.mechanicalPackingListCodeSnapshot}`
                      : undefined
                  }
                  fallback="—"
                />
                {isAlreadyAdded && (
                  <span className="inline-flex items-center px-1.5 py-0.5 rounded text-[10px] font-semibold bg-muted text-muted-foreground shrink-0 border border-muted-foreground/20">
                    {t('installationOrder:status.alreadyAdded', { defaultValue: 'Đã thêm' })}
                  </span>
                )}
              </div>
              <Button
                type="button"
                variant="ghost"
                size="icon"
                className="h-7 w-7 text-primary hover:text-primary hover:bg-primary/10 shrink-0"
                title={t('installationOrder:action.viewPackingDetail', {
                  defaultValue: 'Xem chi tiết đóng kiện',
                })}
                onClick={() =>
                  setActivePreviewPacking({
                    title:
                      row.mechanicalPackingListNameSnapshot ||
                      row.mechanicalPackingListCodeSnapshot ||
                      'Chi tiết cụm đóng kiện',
                    details: (row.details as PackingDetailItem[]) || [],
                  })
                }
              >
                <Eye className="h-3.5 w-3.5" />
              </Button>
            </div>
          );
        },
      },
    ],
    [isAllSelected, handleToggleSelectAll, selectablePackings.length, selectedPackings, existingPackingMap, itpMap, fk, t],
  );

  const handleConfirm = () => {
    // Làm giàu dữ liệu với tên/mã snapshot đã resolve trước khi đẩy ra onSelect
    const enrichedList = Object.values(selectedPackings).map((p) => {
      const matchedItp =
        (p.finishedGoodId && p.modelId ? itpMap.get(`${p.finishedGoodId}_${p.modelId}`) : undefined) ??
        (p.finishedGoodId ? itpMap.get(`fg_${p.finishedGoodId}`) : undefined);
      const fkDesign = p.designModelId ? fk.model.getInfo(p.designModelId) : undefined;
      const fkUser = p.modelId ? fk.model.getInfo(p.modelId) : undefined;

      return {
        ...p,
        designModelNameSnapshot:
          p.designModelNameSnapshot || matchedItp?.designModelNameSnapshot || fkDesign?.name || null,
        designModelCodeSnapshot:
          p.designModelCodeSnapshot || matchedItp?.designModelCodeSnapshot || fkDesign?.code || null,
        modelNameSnapshot:
          p.modelNameSnapshot || matchedItp?.modelNameSnapshot || fkUser?.name || null,
        modelCodeSnapshot:
          p.modelCodeSnapshot || matchedItp?.modelCodeSnapshot || fkUser?.code || null,
        finishedGoodNameSnapshot:
          p.finishedGoodNameSnapshot || matchedItp?.finishedGoodNameSnapshot || null,
        finishedGoodCodeSnapshot:
          p.finishedGoodCodeSnapshot || matchedItp?.finishedGoodCodeSnapshot || null,
      };
    });
    onSelect(enrichedList);
    onOpenChange(false);
  };

  const isLoading = eligiblePackingsQuery.isFetching;

  return (
    <>
      <Dialog open={open} onOpenChange={onOpenChange}>
        <DialogContent className="w-[94vw] max-w-7xl max-h-[90vh] h-[86vh] flex flex-col p-6 overflow-hidden">
          <DialogHeader className="pb-3 border-b shrink-0">
            <DialogTitle className="text-lg font-bold flex items-center gap-2">
              <span className="w-1.5 h-4 bg-primary rounded-full" />
              <span>
                {t('installationOrder:action.selectPacking', { defaultValue: 'Chọn cụm nhập kho thành phẩm' })}
              </span>
            </DialogTitle>
            <DialogDescription className="text-sm text-muted-foreground">
              {t('installationOrder:action.selectPackingDescription', {
                defaultValue:
                  'Chọn các Cụm đóng kiện đã nhập kho thực tế để đưa vào danh sách thi công của Lệnh lắp đặt.',
              })}
            </DialogDescription>
          </DialogHeader>

          <div className="flex-1 min-h-0 py-3 flex flex-col gap-2.5 overflow-hidden">
            {eligiblePackings.length > 0 && (
              <div className="relative shrink-0">
                <Search className="absolute left-2.5 top-2.5 h-4 w-4 text-muted-foreground" />
                <DebouncedInput
                  placeholder={t('installationOrder:searchPackingPlaceholder', {
                    defaultValue: 'Tìm theo mã ITP, tên thành phẩm, model, mã packing list...',
                  })}
                  value={searchKeyword}
                  onChange={(val) => setSearchKeyword(String(val ?? ''))}
                  className="pl-8 h-9 text-sm"
                />
              </div>
            )}

            {filteredPackings.length > 0 && (
              <div className="flex items-center justify-between px-3 py-2 bg-muted/40 rounded-lg border shrink-0">
                <div className="flex items-center gap-2">
                  <Checkbox
                    id="select-all-packings"
                    checked={isAllSelected}
                    onCheckedChange={handleToggleSelectAll}
                    disabled={selectablePackings.length === 0}
                  />
                  <label
                    htmlFor="select-all-packings"
                    className="text-sm font-medium cursor-pointer select-none text-foreground"
                  >
                    {t('common:action.selectAll', { defaultValue: 'Chọn tất cả' })}
                  </label>
                </div>
                <span className="text-xs text-muted-foreground font-medium">
                  {t('installationOrder:selectedPackingsCount', {
                    selected: Object.keys(selectedPackings).length,
                    total: eligiblePackings.length,
                    defaultValue: `Đã chọn ${Object.keys(selectedPackings).length} / ${eligiblePackings.length} cụm`,
                  })}
                </span>
              </div>
            )}

            <div className="flex-1 min-h-0 border rounded-lg overflow-hidden flex flex-col bg-background">
              {isLoading ? (
                <TableSkeleton columns={6} rows={4} showToolbar={false} showHeader={true} />
              ) : (
                <ResizableWrapTable
                  data={filteredPackings}
                  columns={columns}
                  headerVariant="sub-primary"
                  emptyMessage={
                    eligiblePackings.length === 0
                      ? t('installationOrder:empty.eligiblePackings', {
                          defaultValue: 'Không tìm thấy cụm nào đủ điều kiện hoặc đã được chọn hết.',
                        })
                      : t('common:noMatchingData', {
                          defaultValue: 'Không tìm thấy cụm nào phù hợp với từ khóa tìm kiếm.',
                        })
                  }
                />
              )}
            </div>
          </div>

          <DialogFooter className="pt-3 border-t flex items-center justify-between w-full shrink-0">
            <div className="text-xs text-muted-foreground font-medium">
              {t('installationOrder:packingTotalEligible', {
                total: eligiblePackings.length,
                defaultValue: 'Khả dụng: {{total}} cụm',
                replace: { total: eligiblePackings.length },
              })}
            </div>
            <div className="flex items-center gap-2">
              <Button type="button" variant="outline" size="sm" onClick={() => onOpenChange(false)}>
                {t('action:cancel', { defaultValue: 'Hủy' })}
              </Button>
              <Button
                type="button"
                size="sm"
                onClick={handleConfirm}
                disabled={Object.keys(selectedPackings).length === 0}
              >
                <Layers className="w-3.5 h-3.5 mr-1.5" />
                {t('action:addSelected', { defaultValue: 'Thêm đã chọn' })} ({Object.keys(selectedPackings).length})
              </Button>
            </div>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      <PackingDetailViewDialog
        open={!!activePreviewPacking}
        onOpenChange={(open) => {
          if (!open) setActivePreviewPacking(null);
        }}
        packingTitle={activePreviewPacking?.title}
        details={activePreviewPacking?.details}
      />
    </>
  );
}

