import { useState, useMemo, useCallback } from 'react';
import { useTranslation } from 'react-i18next';
import { useFieldArray, useFormContext, useWatch } from 'react-hook-form';
import { Eye, Plus, Trash2 } from 'lucide-react';
import { format } from 'date-fns';
import { Button } from '@shared/ui';
import {
  DoubleLineCell,
  LazyCombobox,
  ResizableWrapTable,
  RowActionButton,
  type ResizableWrapTableColumn,
} from '@shared/components';
import { useFkLookup } from '@shared/hooks';
import { modelService } from '@/services/admin/model-service';
import { DatePicker } from '@shared/components/custom/date-picker';
import { CustomSelect } from '@shared/components/custom/custom-select';
import { EProductionTeamType } from '@/enums/production-team-type.enum';
import { ProductionTeamTypeLabels } from '@/types/admin/production-unit.type';
import { PackingDetailViewDialog } from './packing-detail-view-dialog';
import { PackingSelectionDialog } from './packing-selection-dialog';
import type { PackingDetailItem } from '@/routes/_app/logistic/finished-goods-packing/_components/packing-detail-table';
import type {
  InstallationOrderFormValues,
  InstallationOrderPackingRow,
} from '../installation-order-form.schema';

export type { InstallationOrderPackingRow };

interface InstallationOrderPackingsTabProps {
  isReadOnly?: boolean;
}

const manufacturingMethodOptions = [
  { value: `${EProductionTeamType.Internal}`, label: ProductionTeamTypeLabels[EProductionTeamType.Internal] },
  { value: `${EProductionTeamType.Subcontractor}`, label: ProductionTeamTypeLabels[EProductionTeamType.Subcontractor] },
  { value: `${EProductionTeamType.Outsourcing}`, label: ProductionTeamTypeLabels[EProductionTeamType.Outsourcing] },
];

export function InstallationOrderPackingsTab({
  isReadOnly = false,
}: InstallationOrderPackingsTabProps) {
  const { t } = useTranslation(['installationOrder', 'action', 'common']);
  const form = useFormContext<InstallationOrderFormValues>();

  const { fields, append, remove } = useFieldArray({
    control: form.control,
    name: 'packings',
  });

  const rawWatchedPackings = useWatch({
    control: form.control,
    name: 'packings',
  });
  const watchedPackings = useMemo<InstallationOrderPackingRow[]>(
    () => (Array.isArray(rawWatchedPackings) ? rawWatchedPackings : []),
    [rawWatchedPackings],
  );

  const watchedFinishedGoods = form.watch('finishedGoods') || [];

  // HashMap để tra cứu nhanh thông tin Model từ tab Thành phẩm (ITP)
  const itpMap = useMemo(() => {
    const map = new Map<string, (typeof watchedFinishedGoods)[number]>();
    watchedFinishedGoods.forEach((fg) => {
      if (fg.finishedGoodId && fg.modelId) map.set(`${fg.finishedGoodId}_${fg.modelId}`, fg);
      if (fg.finishedGoodId) map.set(`fg_${fg.finishedGoodId}`, fg);
      if (fg.modelId) map.set(`model_${fg.modelId}`, fg);
      if (fg.designModelId) map.set(`design_${fg.designModelId}`, fg);
    });
    return map;
  }, [watchedFinishedGoods]);

  // Tra cứu bổ sung thông tin Model nếu cả snapshot lẫn ITP đều chưa có tên
  const fk = useFkLookup(watchedPackings, [
    {
      key: 'model',
      extractIds: (rows) =>
        rows
          .flatMap((r) => [r?.modelId, r?.designModelId])
          .filter(Boolean) as string[],
      fetchByIds: (ids) => modelService.getByIds({ ids }),
    },
  ]);

  const [searchText, setSearchText] = useState('');
  const [activeDialogPacking, setActiveDialogPacking] = useState<{
    title: string;
    details: PackingDetailItem[];
  } | null>(null);

  const [selectionDialogOpen, setSelectionDialogOpen] = useState(false);

  const handleOpenDetailDialog = useCallback((row: InstallationOrderPackingRow) => {
    const title =
      row.mechanicalPackingListNameSnapshot ||
      row.mechanicalPackingListCodeSnapshot ||
      row.finishedGoodNameSnapshot ||
      'Cụm đóng kiện';
    setActiveDialogPacking({
      title,
      details: row.details || [],
    });
  }, []);

  const handleAddRow = useCallback(() => {
    append({
      order: fields.length + 1,
      manufacturingMethod: EProductionTeamType.Internal,
    });
  }, [append, fields.length]);

  const filteredPackings = useMemo(() => {
    if (!searchText.trim()) return watchedPackings;
    const q = searchText.toLowerCase();
    return watchedPackings.filter((p) =>
      (p.finishedGoodNameSnapshot || '').toLowerCase().includes(q) ||
      (p.finishedGoodCodeSnapshot || '').toLowerCase().includes(q) ||
      (p.mechanicalPackingListNameSnapshot || '').toLowerCase().includes(q) ||
      (p.mechanicalPackingListCodeSnapshot || '').toLowerCase().includes(q) ||
      (p.productionTeamNameSnapshot || '').toLowerCase().includes(q),
    );
  }, [watchedPackings, searchText]);

  const columns: ResizableWrapTableColumn<InstallationOrderPackingRow>[] = useMemo(
    () => [
      {
        id: 'stt',
        header: t('common:stt', { defaultValue: 'STT' }),
        defaultWidth: 60,
        minWidth: 50,
        maxWidth: 80,
        headerAlign: 'center',
        cellClassName: 'text-center',
        cell: (_row, index) => (
          <span className="text-xs font-medium text-muted-foreground">{index + 1}</span>
        ),
      },
      // 1. Mã ITP
      {
        id: 'finishedGood',
        header: t('installationOrder:columnTitle.finishedGoodCode', { defaultValue: 'Mã ITP' }),
        defaultWidth: 170,
        minWidth: 140,
        cell: (row) => {
          const matchedItp =
            (row.finishedGoodId && row.modelId ? itpMap.get(`${row.finishedGoodId}_${row.modelId}`) : undefined) ??
            (row.finishedGoodId ? itpMap.get(`fg_${row.finishedGoodId}`) : undefined);
          const name = row.finishedGoodNameSnapshot || matchedItp?.finishedGoodNameSnapshot;
          const code = row.finishedGoodCodeSnapshot || matchedItp?.finishedGoodCodeSnapshot;
          return (
            <DoubleLineCell
              title={name}
              subtitle={code ? `#${code}` : undefined}
              fallback="—"
            />
          );
        },
      },
      // 2. Model thiết kế
      {
        id: 'designModel',
        header: t('installationOrder:columnTitle.designModel', { defaultValue: 'Model thiết kế' }),
        defaultWidth: 150,
        minWidth: 130,
        cell: (row) => {
          const matchedItp =
            (row.finishedGoodId && row.modelId ? itpMap.get(`${row.finishedGoodId}_${row.modelId}`) : undefined) ??
            (row.designModelId ? itpMap.get(`design_${row.designModelId}`) : undefined) ??
            (row.finishedGoodId ? itpMap.get(`fg_${row.finishedGoodId}`) : undefined);
          const fkInfo = row.designModelId ? fk.model.getInfo(row.designModelId) : undefined;
          const name = row.designModelNameSnapshot || matchedItp?.designModelNameSnapshot || fkInfo?.name;
          const code = row.designModelCodeSnapshot || matchedItp?.designModelCodeSnapshot || fkInfo?.code;
          return <DoubleLineCell title={name} subtitle={code} fallback="—" />;
        },
      },
      // 3. Model hiệu suất
      {
        id: 'model',
        header: t('installationOrder:columnTitle.model', { defaultValue: 'Model hiệu suất' }),
        defaultWidth: 150,
        minWidth: 130,
        cell: (row) => {
          const matchedItp =
            (row.finishedGoodId && row.modelId ? itpMap.get(`${row.finishedGoodId}_${row.modelId}`) : undefined) ??
            (row.modelId ? itpMap.get(`model_${row.modelId}`) : undefined) ??
            (row.finishedGoodId ? itpMap.get(`fg_${row.finishedGoodId}`) : undefined);
          const fkInfo = row.modelId ? fk.model.getInfo(row.modelId) : undefined;
          const name = row.modelNameSnapshot || matchedItp?.modelNameSnapshot || fkInfo?.name;
          const code = row.modelCodeSnapshot || matchedItp?.modelCodeSnapshot || fkInfo?.code;
          return <DoubleLineCell title={name} subtitle={code} fallback="—" />;
        },
      },
      // 4. Mã / Tên Packing List Cơ Khí (Kèm icon con mắt 👁️ xem chi tiết cụm đóng kiện)
      {
        id: 'mechanicalPackingList',
        header: t('installationOrder:columnTitle.mechanicalPackingList', {
          defaultValue: 'Mã / Tên Packing List Cơ Khí',
        }),
        defaultWidth: 220,
        minWidth: 180,
        cell: (row) => (
          <div className="flex items-center justify-between gap-1 w-full">
            <DoubleLineCell
              title={row.mechanicalPackingListNameSnapshot}
              subtitle={
                row.mechanicalPackingListCodeSnapshot
                  ? `#${row.mechanicalPackingListCodeSnapshot}`
                  : undefined
              }
              fallback="—"
            />
            {row.mechanicalPackingListId && (
              <Button
                type="button"
                variant="ghost"
                size="icon"
                className="h-7 w-7 text-primary hover:text-primary hover:bg-primary/10 shrink-0"
                title={t('installationOrder:action.viewPackingDetail', {
                  defaultValue: 'Xem chi tiết đóng kiện',
                })}
                onClick={() => handleOpenDetailDialog(row)}
              >
                <Eye className="h-3.5 w-3.5" />
              </Button>
            )}
          </div>
        ),
      },
      // 5. Nguồn nhân công
      {
        id: 'manufacturingMethod',
        header: t('installationOrder:columnTitle.manufacturingMethod', {
          defaultValue: 'Nguồn nhân công',
        }),
        defaultWidth: 150,
        minWidth: 130,
        cell: (row, index) => {
          const methodKey = row.manufacturingMethod;
          if (isReadOnly) {
            const label =
              methodKey != null && methodKey in ProductionTeamTypeLabels
                ? ProductionTeamTypeLabels[methodKey as EProductionTeamType]
                : '—';
            return <span className="text-xs">{label}</span>;
          }
          return (
            <CustomSelect
              options={manufacturingMethodOptions}
              value={methodKey != null ? `${methodKey}` : ''}
              onChangeValue={(val) =>
                form.setValue(
                  `packings.${index}.manufacturingMethod`,
                  Number(val) as EProductionTeamType,
                  { shouldDirty: true },
                )
              }
              placeholder={t('installationOrder:placeholder.manufacturingMethod', {
                defaultValue: 'Chọn nguồn...',
              })}
              className="h-8 text-xs w-full"
            />
          );
        },
      },
      // 6. Tổ LĐ
      {
        id: 'productionTeam',
        header: t('installationOrder:columnTitle.productionTeam', { defaultValue: 'Tổ LĐ' }),
        defaultWidth: 160,
        minWidth: 140,
        cell: (row, index) => {
          if (isReadOnly) {
            return (
              <span className="text-xs">
                {row.productionTeamNameSnapshot || row.productionTeamCodeSnapshot || '—'}
              </span>
            );
          }
          return (
            <LazyCombobox
              entityCode="HR.ProductionTeam"
              value={row.productionTeamId || ''}
              onValueChange={(val, snapName, snapCode) => {
                const id = Array.isArray(val) ? val[0] : val;
                form.setValue(`packings.${index}.productionTeamId`, id || null, { shouldDirty: true });
                form.setValue(`packings.${index}.productionTeamNameSnapshot`, snapName || null, { shouldDirty: true });
                form.setValue(`packings.${index}.productionTeamCodeSnapshot`, snapCode || null, { shouldDirty: true });
              }}
              placeholder={t('installationOrder:placeholder.productionTeam', {
                defaultValue: 'Chọn tổ LĐ...',
              })}
              className="h-8 text-xs w-full"
            />
          );
        },
      },
      // 7. Ngày bắt đầu
      {
        id: 'startDate',
        header: t('installationOrder:columnTitle.estStartDate', { defaultValue: 'Ngày bắt đầu' }),
        defaultWidth: 145,
        minWidth: 120,
        cell: (row, index) => {
          if (isReadOnly) {
            return <span className="text-xs">{row.startDate || '—'}</span>;
          }
          return (
            <DatePicker
              value={row.startDate ? new Date(row.startDate) : undefined}
              onChange={(val) => {
                const formatted = val ? format(val, 'yyyy-MM-dd') : '';
                form.setValue(`packings.${index}.startDate`, formatted, { shouldDirty: true });
              }}
              placeholder="yyyy-MM-dd"
              className="h-8 text-xs"
            />
          );
        },
      },
      // 8. Ngày kết thúc
      {
        id: 'endDate',
        header: t('installationOrder:columnTitle.estEndDate', { defaultValue: 'Ngày kết thúc' }),
        defaultWidth: 145,
        minWidth: 120,
        cell: (row, index) => {
          if (isReadOnly) {
            return <span className="text-xs">{row.endDate || '—'}</span>;
          }
          return (
            <DatePicker
              value={row.endDate ? new Date(row.endDate) : undefined}
              onChange={(val) => {
                const formatted = val ? format(val, 'yyyy-MM-dd') : '';
                form.setValue(`packings.${index}.endDate`, formatted, { shouldDirty: true });
              }}
              placeholder="yyyy-MM-dd"
              className="h-8 text-xs"
            />
          );
        },
      },
      // 9. Buổi kết thúc
      {
        id: 'endDaySession',
        header: t('installationOrder:columnTitle.endDaySession', { defaultValue: 'Buổi kết thúc' }),
        defaultWidth: 140,
        minWidth: 120,
        cell: (row, index) => {
          if (isReadOnly) {
            return <span className="text-xs">{row.endDaySessionId || '—'}</span>;
          }
          return (
            <LazyCombobox
              entityCode="ServiceDesk.DaySession"
              value={row.endDaySessionId || ''}
              onValueChange={(val) => {
                const id = Array.isArray(val) ? val[0] : val;
                form.setValue(`packings.${index}.endDaySessionId`, id || null, { shouldDirty: true });
              }}
              placeholder={t('installationOrder:placeholder.selectDaySession', {
                defaultValue: 'Chọn buổi...',
              })}
              className="h-8 text-xs w-full"
            />
          );
        },
      },
      // 10. Loại thợ
      {
        id: 'workerType',
        header: t('installationOrder:columnTitle.workerType', { defaultValue: 'Loại thợ' }),
        defaultWidth: 140,
        minWidth: 120,
        cell: (row, index) => {
          if (isReadOnly) {
            return <span className="text-xs">{row.workerTypeId || '—'}</span>;
          }
          return (
            <LazyCombobox
              entityCode="WorkerType"
              value={row.workerTypeId || ''}
              onValueChange={(val) => {
                const id = Array.isArray(val) ? val[0] : val;
                form.setValue(`packings.${index}.workerTypeId`, id || null, { shouldDirty: true });
              }}
              placeholder={t('installationOrder:placeholder.selectWorkerType', {
                defaultValue: 'Chọn loại thợ...',
              })}
              className="h-8 text-xs w-full"
            />
          );
        },
      },
      // 11. Chi phí LĐ (ProductionCost)
      {
        id: 'productionCost',
        header: t('installationOrder:columnTitle.cost', { defaultValue: 'Chi phí LĐ' }),
        defaultWidth: 160,
        minWidth: 140,
        cell: (row, index) => {
          if (isReadOnly) {
            return <span className="text-xs">{row.productionCostId || '—'}</span>;
          }
          return (
            <LazyCombobox
              entityCode="MasterData.ProductionCost"
              value={row.productionCostId || ''}
              onValueChange={(val) => {
                const id = Array.isArray(val) ? val[0] : val;
                form.setValue(`packings.${index}.productionCostId`, id || null, { shouldDirty: true });
              }}
              placeholder={t('installationOrder:placeholder.productionCost', {
                defaultValue: 'Chọn đơn giá khoán...',
              })}
              className="h-8 text-xs w-full"
            />
          );
        },
      },
      // 12. Thao tác (Xóa)
      ...(!isReadOnly
        ? [
            {
              id: 'actions',
              header: '',
              defaultWidth: 50,
              minWidth: 45,
              headerAlign: 'center' as const,
              cellClassName: 'text-center',
              cell: (_row: InstallationOrderPackingRow, index: number) => (
                <RowActionButton
                  icon={Trash2}
                  title={t('action:delete', { defaultValue: 'Xóa' })}
                  variant="destructive"
                  onClick={() => remove(index)}
                />
              ),
            },
          ]
        : []),
    ],
    [isReadOnly, t, form, handleOpenDetailDialog, remove, itpMap, fk],
  );

  return (
    <div className="space-y-3">
      <div className="border rounded-md overflow-hidden">
        <ResizableWrapTable
          data={filteredPackings}
          columns={columns}
          emptyMessage={t('installationOrder:empty.packings', {
            defaultValue: 'Chưa có cụm thành phẩm đóng kiện nào.',
          })}
          toolbarProps={{
            searchValue: searchText,
            onSearchChange: setSearchText,
            searchDebounce: 300,
            searchPlaceholder: t('installationOrder:placeholder.searchPackings', {
              defaultValue: 'Tìm kiếm mã ITP, packing list, tổ LĐ...',
            }),
            totalCount: watchedPackings.length,
            filteredCount: filteredPackings.length,
            actions: !isReadOnly ? (
              <div className="flex gap-2">
                <Button type="button" size="sm" onClick={() => setSelectionDialogOpen(true)} className="gap-1 text-xs">
                  <Plus className="h-4 w-4" />
                  {t('action:selectPacking', { defaultValue: 'Chọn cụm nhập kho' })}
                </Button>
                <Button type="button" size="sm" onClick={handleAddRow} variant="outline" className="gap-1 text-xs">
                  <Plus className="h-4 w-4" />
                  {t('action:add', { defaultValue: 'Thêm dòng rỗng' })}
                </Button>
              </div>
            ) : undefined,
          }}
        />
      </div>

      <PackingDetailViewDialog
        open={!!activeDialogPacking}
        onOpenChange={(open) => {
          if (!open) setActiveDialogPacking(null);
        }}
        packingTitle={activeDialogPacking?.title}
        details={activeDialogPacking?.details}
      />

      <PackingSelectionDialog
        open={selectionDialogOpen}
        onOpenChange={setSelectionDialogOpen}
        projectId={form.watch('projectId')}
        refDocId={form.watch('refDocId')}
        existingPackingIds={watchedPackings.flatMap((p) => [p.mechanicalPackingListId, p.id]).filter(Boolean) as string[]}
        itpKeys={(form.watch('finishedGoods') || []).map((fg) => ({
          finishedGoodId: fg.finishedGoodId || fg.finishedGood?.id || null,
          modelId: fg.modelId || fg.model?.id || null,
          designModelId: fg.designModelId || fg.designModel?.id || null,
          modelCodeSnapshot: fg.modelCodeSnapshot || fg.model?.code || null,
          modelNameSnapshot: fg.modelNameSnapshot || fg.model?.name || null,
          designModelCodeSnapshot: fg.designModelCodeSnapshot || fg.designModel?.code || null,
          designModelNameSnapshot: fg.designModelNameSnapshot || fg.designModel?.name || null,
          finishedGoodCodeSnapshot: fg.finishedGoodCodeSnapshot || fg.finishedGood?.code || null,
          finishedGoodNameSnapshot: fg.finishedGoodNameSnapshot || fg.finishedGood?.name || null,
        }))}
        onSelect={(selected) => {
          // HashMap ngăn chặn thêm trùng lặp mã packing list vào bảng
          const currentPackings = (form.getValues('packings') as InstallationOrderPackingRow[]) || [];
          const existingMap = new Map<string, boolean>();
          currentPackings.forEach((p) => {
            if (p.mechanicalPackingListId) existingMap.set(p.mechanicalPackingListId, true);
            if (p.id) existingMap.set(p.id, true);
          });

          selected.forEach((p) => {
            const key = p.mechanicalPackingListId || p.id;
            if (key && existingMap.has(key)) {
              return; // Bỏ qua cụm đã tồn tại
            }
            if (key) {
              existingMap.set(key, true);
            }

            append({
              order: (form.getValues('packings')?.length ?? 0) + 1,
              manufacturingMethod: EProductionTeamType.Internal,
              ...p,
            });
          });
        }}
      />
    </div>
  );
}

