private async Task EnrichModelsAndFinishedGoodsFromMasterDataAsync(List<InstallationOrderEligiblePackingDto> dtos)
{
    if (dtos == null || dtos.Count == 0) return;

    // 1. Enrich Model & DesignModel
    var modelIds = dtos
        .Select(d => d.ModelId)
        .Concat(dtos.Select(d => d.DesignModelId))
        .Where(id => id.HasValue && id.Value != Guid.Empty)
        .Select(id => id.Value.ToString())
        .ToHashSet();

    if (modelIds.Count > 0)
    {
        try
        {
            var response = await masterDataGrpcClient.GetFinishedGoodModelsByIdsAsync(
                new GetIdsRequest { Ids = { modelIds } },
                cancellationToken: RequestAborted);

            if (response != null && response.Success && response.Data != null && response.Data.Count > 0)
            {
                var map = response.Data.ToDictionary(x => x.Id, x => x, StringComparer.OrdinalIgnoreCase);
                foreach (var dto in dtos)
                {
                    if (dto.ModelId.HasValue && map.TryGetValue(dto.ModelId.Value.ToString(), out var m))
                    {
                        if (string.IsNullOrEmpty(dto.ModelCodeSnapshot)) dto.ModelCodeSnapshot = m.Code;
                        if (string.IsNullOrEmpty(dto.ModelNameSnapshot)) dto.ModelNameSnapshot = m.Name;
                    }

                    if (dto.DesignModelId.HasValue && map.TryGetValue(dto.DesignModelId.Value.ToString(), out var dm))
                    {
                        if (string.IsNullOrEmpty(dto.DesignModelCodeSnapshot)) dto.DesignModelCodeSnapshot = dm.Code;
                        if (string.IsNullOrEmpty(dto.DesignModelNameSnapshot)) dto.DesignModelNameSnapshot = dm.Name;
                    }
                }
            }
        }
        catch (Exception ex)
        {
            _logger.Warning(ex, "Lỗi khi enrich Model cho EligiblePackings từ MasterData gRPC");
        }
    }

    // 2. Enrich FinishedGood nếu thiếu snapshot
    var fgIds = dtos
        .Where(d => d.FinishedGoodId.HasValue && d.FinishedGoodId.Value != Guid.Empty &&
                    (string.IsNullOrEmpty(d.FinishedGoodCodeSnapshot) || string.IsNullOrEmpty(d.FinishedGoodNameSnapshot)))
        .Select(d => d.FinishedGoodId!.Value.ToString())
        .ToHashSet();

    if (fgIds.Count > 0)
    {
        try
        {
            var fgResponse = await masterDataGrpcClient.GetFinishedGoodsByIdsAsync(
                new GetIdsRequest { Ids = { fgIds } },
                cancellationToken: RequestAborted);

            if (fgResponse != null && fgResponse.Success && fgResponse.Items != null && fgResponse.Items.Count > 0)
            {
                var fgMap = fgResponse.Items.ToDictionary(x => x.Id, x => x, StringComparer.OrdinalIgnoreCase);
                foreach (var dto in dtos)
                {
                    if (dto.FinishedGoodId.HasValue && fgMap.TryGetValue(dto.FinishedGoodId.Value.ToString(), out var fg))
                    {
                        if (string.IsNullOrEmpty(dto.FinishedGoodCodeSnapshot)) dto.FinishedGoodCodeSnapshot = fg.Code;
                        if (string.IsNullOrEmpty(dto.FinishedGoodNameSnapshot)) dto.FinishedGoodNameSnapshot = fg.Name;
                    }
                }
            }
        }
        catch (Exception ex)
        {
            _logger.Warning(ex, "Lỗi khi enrich FinishedGood cho EligiblePackings từ MasterData gRPC");
        }
    }
}

