      rows
        .flatMap((r) => [r?.modelId, r?.designModelId])
        .filter(Boolean) as string[],
    fetchByIds: (ids) => modelService.getByIds({ ids }),
  },
]);

const checkIsAlreadyAdded = useCallback(
  (p: InstallationOrderPackingRow) => {
    const codeKey = p.mechanicalPackingListCodeSnapshot?.trim().toLowerCase();
    const mplIdKey = p.mechanicalPackingListId?.toLowerCase();
    const idKey = p.id?.toLowerCase();
    return Boolean(
      (codeKey && existingPackingMap.has(codeKey)) ||
      (mplIdKey && existingPackingMap.has(mplIdKey)) ||
      (idKey && existingPackingMap.has(idKey)),
    );
  },
  [existingPackingMap],
);

const getPackingKey = useCallback((p: InstallationOrderPackingRow, idx: number) => {
  return (
    p.mechanicalPackingListCodeSnapshot?.trim().toLowerCase() ||
    p.mechanicalPackingListId?.toLowerCase() ||
    p.id?.toLowerCase() ||
    `row_${idx}`
  );
}, []);

const filteredPackings = useMemo(() => {
  const kw = searchKeyword.trim().toLowerCase();
  if (!kw) return eligiblePackings;
  return eligiblePackings.filter((row) => {
    const terms = [
      row.finishedGoodCodeSnapshot,
      row.finishedGoodNameSnapshot,
      row.modelCodeSnapshot,
      row.modelNameSnapshot,
      row.designModelCodeSnapshot,
      row.designModelNameSnapshot,
      row.mechanicalPackingListCodeSnapshot,
      row.mechanicalPackingListNameSnapshot,
    ]
      .filter(Boolean)
      .join(' ')
      .toLowerCase();
    return terms.includes(kw);
  });
}, [eligiblePackings, searchKeyword]);

// Chỉ cho phép chọn các cụm chưa từng được thêm vào lệnh (kiểm tra qua HashMap cả ID lẫn Mã)
const selectablePackings = useMemo(
  () => filteredPackings.filter((p) => !checkIsAlreadyAdded(p)),
  [filteredPackings, checkIsAlreadyAdded],
);

const isAllSelected =
  selectablePackings.length > 0 &&
  selectablePackings.every((p, idx) => {
    const key = getPackingKey(p, idx);
    return !!selectedPackings[key];
  });

const handleToggleSelectAll = useCallback(() => {
  if (selectablePackings.length === 0) return;
  if (isAllSelected) {
    setSelectedPackings((prev) => {
      const next = { ...prev };
      selectablePackings.forEach((p, idx) => {
        const key = getPackingKey(p, idx);
        delete next[key];
      });
      return next;
    });
  } else {
    setSelectedPackings((prev) => {
      const next = { ...prev };
      selectablePackings.forEach((p, idx) => {
        const key = getPackingKey(p, idx);
        next[key] = p;
      });
      return next;
    });
  }
}, [isAllSelected, selectablePackings, getPackingKey]);

