    // 1. Ưu tiên: Lấy các kiện FinishedGoodsPacking đã thực tế nhập kho theo ProjectId
    if (request.ProjectId.HasValue && request.ProjectId.Value != Guid.Empty)
    {
        var packings = await GetReceiptedPackingsByProjectAsync(request.ProjectId.Value, excludedIds, request.ItpKeys);
        if (packings.Count > 0)
        {
            EnrichMissingSnapshots(packings, request.ItpKeys);
            await EnrichModelsAndFinishedGoodsFromMasterDataAsync(packings);
            return Result<List<InstallationOrderEligiblePackingDto>>.Success(packings);
        }

        // Fallback 1A: Nếu chưa có phiếu nhập kho thực tế trong ERP, lấy MechanicalPackingList theo ProjectId
        var mplByProject = await GetFallbackMechanicalPackingsByProjectAsync(request.ProjectId.Value, excludedIds, request.ItpKeys);
        if (mplByProject.Count > 0)
        {
            EnrichMissingSnapshots(mplByProject, request.ItpKeys);
            await EnrichModelsAndFinishedGoodsFromMasterDataAsync(mplByProject);
            return Result<List<InstallationOrderEligiblePackingDto>>.Success(mplByProject);
        }
    }

    // 2. Fallback: Nếu không tìm thấy kiện nhập kho hoặc không truyền ProjectId, fallback sang MechanicalPackingList theo RefDocId (Lệnh sản xuất)
    if (request.RefDocId.HasValue && request.RefDocId.Value != Guid.Empty)
    {
        var fallbackPackings = await GetFallbackMechanicalPackingsAsync(request.RefDocId.Value, excludedIds, request.ItpKeys);
        if (fallbackPackings.Count > 0)
        {
            EnrichMissingSnapshots(fallbackPackings, request.ItpKeys);
            await EnrichModelsAndFinishedGoodsFromMasterDataAsync(fallbackPackings);
            return Result<List<InstallationOrderEligiblePackingDto>>.Success(fallbackPackings);
        }
    }

    // 3. Fallback: Nếu không có ProjectId/RefDocId hoặc chưa ra kết quả, tìm MechanicalPackingList khớp theo FinishedGoodId & ModelId từ ItpKeys
    if (request.ItpKeys != null && request.ItpKeys.Count > 0)
    {
        var mplByItp = await GetFallbackMechanicalPackingsByItpKeysAsync(excludedIds, request.ItpKeys);
        if (mplByItp.Count > 0)
        {
            EnrichMissingSnapshots(mplByItp, request.ItpKeys);
            await EnrichModelsAndFinishedGoodsFromMasterDataAsync(mplByItp);
            return Result<List<InstallationOrderEligiblePackingDto>>.Success(mplByItp);
        }
    }

    return Result<List<InstallationOrderEligiblePackingDto>>.Success([]);
