private async Task<List<InstallationOrderEligiblePackingDto>> GetFallbackMechanicalPackingsByProjectAsync(
    Guid projectId,
    HashSet<Guid> excludedIds,
    List<InstallationOrderItpKeyDto> itpKeys)
{
    var mplQuery = _mechanicalPackingListRepo.Query()
        .AsNoTracking()
        .Include(m => m.Details)
        .Where(m => m.ProjectId == projectId);

    if (excludedIds.Count > 0)
    {
        mplQuery = mplQuery.Where(m => !excludedIds.Contains(m.Id));
    }

    var mpls = await mplQuery.ToListAsync(RequestAborted);

    return mpls
        .Where(mpl => MatchItpKeys(mpl.FinishedGoodId, mpl.ModelId, mpl.DesignModelId, itpKeys))
        .Select(MapToEligiblePackingDto)
        .ToList();
}

private async Task<List<InstallationOrderEligiblePackingDto>> GetFallbackMechanicalPackingsByItpKeysAsync(
    HashSet<Guid> excludedIds,
    List<InstallationOrderItpKeyDto> itpKeys)
{
    var fgIds = itpKeys
        .Where(k => k.FinishedGoodId.HasValue && k.FinishedGoodId.Value != Guid.Empty)
        .Select(k => k.FinishedGoodId!.Value)
        .ToHashSet();

    if (fgIds.Count == 0) return [];

    var mplQuery = _mechanicalPackingListRepo.Query()
        .AsNoTracking()
        .Include(m => m.Details)
        .Where(m => m.FinishedGoodId.HasValue && fgIds.Contains(m.FinishedGoodId.Value));

    if (excludedIds.Count > 0)
    {
        mplQuery = mplQuery.Where(m => !excludedIds.Contains(m.Id));
    }

    var mpls = await mplQuery.ToListAsync(RequestAborted);

    return mpls
        .Where(mpl => MatchItpKeys(mpl.FinishedGoodId, mpl.ModelId, mpl.DesignModelId, itpKeys))
        .Select(MapToEligiblePackingDto)
        .ToList();
}

