import { useState, useMemo, useCallback } from 'react';
import { useTranslation } from 'react-i18next';
import { Eye } from 'lucide-react';
import { Button, TableSkeleton } from '@shared/ui';
import {
  DoubleLineCell,
  ResizableWrapTable,
  type ResizableWrapTableColumn,
} from '@shared/components';
import { PackingDetailViewDialog } from '@/routes/_app/installation-management/installation-order/-components/installation-detail-tab/packing-detail-view-dialog';
import type { PackingDetailItem } from '@/routes/_app/logistic/finished-goods-packing/_components/packing-detail-table';
import type { InstallationOrderEligiblePackingDto } from '@/types/admin/installation/installation-order.type';

interface DeliveryPackagingReceiptedPackingsTabProps {
  packings: InstallationOrderEligiblePackingDto[];
  isLoading?: boolean;
  itpMap?: Map<string, any>;
}

export function DeliveryPackagingReceiptedPackingsTab({
  packings = [],
  isLoading = false,
  itpMap,
}: DeliveryPackagingReceiptedPackingsTabProps) {
  const { t } = useTranslation(['DeliveryPackaging', 'common', 'action']);
  const [searchText, setSearchText] = useState('');
  const [activeDialogPacking, setActiveDialogPacking] = useState<{
    title: string;
    details: PackingDetailItem[];
  } | null>(null);

  const handleOpenDetailDialog = useCallback((row: InstallationOrderEligiblePackingDto) => {
    const title =
      row.mechanicalPackingListNameSnapshot ||
      row.mechanicalPackingListCodeSnapshot ||
      row.finishedGoodNameSnapshot ||
      'Cụm đóng kiện';
    setActiveDialogPacking({
      title,
      details: (row.details as PackingDetailItem[]) || [],
    });
  }, []);

  const filteredPackings = useMemo(() => {
    if (!searchText.trim()) return packings;
    const q = searchText.toLowerCase().trim();
    return packings.filter((p) => {
      const terms = [
        p.finishedGoodCodeSnapshot,
        p.finishedGoodNameSnapshot,
        p.modelCodeSnapshot,
        p.modelNameSnapshot,
        p.designModelCodeSnapshot,
        p.designModelNameSnapshot,
        p.mechanicalPackingListCodeSnapshot,
        p.mechanicalPackingListNameSnapshot,
      ]
        .filter(Boolean)
        .join(' ')
        .toLowerCase();
      return terms.includes(q);
    });
  }, [packings, searchText]);

  const columns: ResizableWrapTableColumn<InstallationOrderEligiblePackingDto>[] = useMemo(
    () => [
      {
        id: 'stt',
        header: t('common:stt', { defaultValue: 'STT' }),
        defaultWidth: 55,
        minWidth: 50,
        maxWidth: 70,
        headerAlign: 'center',
        cellClassName: 'text-center',
        cell: (_row, index) => (
          <span className="text-xs font-medium text-muted-foreground">{index + 1}</span>
        ),
      },
      // 1. Mã ITP / Thành phẩm
      {
        id: 'finishedGood',
        header: t('DeliveryPackaging:columnTitle.finishedGoodCode', {
          defaultValue: 'Mã ITP / Thành phẩm',
        }),
        defaultWidth: 220,
        minWidth: 180,
        cell: (row) => {
          const matchedItp =
            (row.finishedGoodId && row.modelId ? itpMap?.get(`${row.finishedGoodId}_${row.modelId}`) : undefined) ??
            (row.finishedGoodId ? itpMap?.get(`fg_${row.finishedGoodId}`) : undefined);
          const name = row.finishedGoodNameSnapshot || matchedItp?.finishedGoodNameSnapshot;
          const code = row.finishedGoodCodeSnapshot || matchedItp?.finishedGoodCodeSnapshot;
          return (
            <DoubleLineCell
              title={name}
              subtitle={code ? `#${code}` : undefined}
              fallback="—"
            />
          );
        },
      },
      // 2. Model thiết kế
      {
        id: 'designModel',
        header: t('DeliveryPackaging:columnTitle.designModel', {
          defaultValue: 'Model thiết kế',
        }),
        defaultWidth: 180,
        minWidth: 140,
        cell: (row) => {
          const matchedItp =
            (row.finishedGoodId && row.modelId ? itpMap?.get(`${row.finishedGoodId}_${row.modelId}`) : undefined) ??
            (row.designModelId ? itpMap?.get(`design_${row.designModelId}`) : undefined) ??
            (row.finishedGoodId ? itpMap?.get(`fg_${row.finishedGoodId}`) : undefined);
          const name = row.designModelNameSnapshot || matchedItp?.designModelNameSnapshot;
          const code = row.designModelCodeSnapshot || matchedItp?.designModelCodeSnapshot;
          return (
            <DoubleLineCell
              title={name}
              subtitle={code ? `#${code}` : undefined}
              fallback="—"
            />
          );
        },
      },
      // 3. Model hiệu suất
      {
        id: 'model',
        header: t('DeliveryPackaging:columnTitle.model', {
          defaultValue: 'Model hiệu suất',
        }),
        defaultWidth: 180,
        minWidth: 140,
        cell: (row) => {
          const matchedItp =
            (row.finishedGoodId && row.modelId ? itpMap?.get(`${row.finishedGoodId}_${row.modelId}`) : undefined) ??
            (row.modelId ? itpMap?.get(`model_${row.modelId}`) : undefined) ??
            (row.finishedGoodId ? itpMap?.get(`fg_${row.finishedGoodId}`) : undefined);
          const name = row.modelNameSnapshot || matchedItp?.modelNameSnapshot;
          const code = row.modelCodeSnapshot || matchedItp?.modelCodeSnapshot;
          return (
            <DoubleLineCell
              title={name}
              subtitle={code ? `#${code}` : undefined}
              fallback="—"
            />
          );
        },
      },
      // 4. Mã / Tên Packing List Cơ Khí (Kèm icon con mắt 👁️ xem chi tiết cụm)
      {
        id: 'mechanicalPackingList',
        header: t('DeliveryPackaging:columnTitle.mechanicalPackingList', {
          defaultValue: 'Mã / Tên Packing List Cơ Khí',
        }),
        defaultWidth: 280,
        minWidth: 220,
        cell: (row) => {
          const hasDetailOrId = Boolean(
            row.mechanicalPackingListId ||
            row.mechanicalPackingListCodeSnapshot ||
            (row.details && row.details.length > 0)
          );

          return (
            <div className="flex items-center justify-between gap-1 w-full">
              <DoubleLineCell
                title={row.mechanicalPackingListNameSnapshot}
                subtitle={
                  row.mechanicalPackingListCodeSnapshot
                    ? `#${row.mechanicalPackingListCodeSnapshot}`
                    : undefined
                }
                fallback="—"
              />
              {hasDetailOrId && (
                <Button
                  type="button"
                  variant="ghost"
                  size="icon"
                  className="h-7 w-7 text-primary hover:text-primary hover:bg-primary/10 shrink-0"
                  title={t('DeliveryPackaging:action.viewPackingDetail', {
                    defaultValue: 'Xem chi tiết đóng kiện',
                  })}
                  onClick={() => handleOpenDetailDialog(row)}
                >
                  <Eye className="h-3.5 w-3.5" />
                </Button>
              )}
            </div>
          );
        },
      },
      // 5. Số chi tiết / bộ phận
      {
        id: 'detailCount',
        header: t('DeliveryPackaging:columnTitle.detailCount', {
          defaultValue: 'Số chi tiết',
        }),
        defaultWidth: 100,
        minWidth: 80,
        headerAlign: 'center',
        cellClassName: 'text-center',
        cell: (row) => (
          <span className="text-xs font-semibold tabular-nums">
            {row.details?.length ?? 0}
          </span>
        ),
      },
      // 6. Tổng khối lượng thực tế (kg)
      {
        id: 'totalActualWeight',
        header: t('DeliveryPackaging:columnTitle.totalActualWeight', {
          defaultValue: 'Tổng KL thực tế (kg)',
        }),
        defaultWidth: 150,
        minWidth: 120,
        headerAlign: 'right',
        cellClassName: 'text-right',
        cell: (row) => {
          const totalKg = (row.details || []).reduce(
            (sum, d) => sum + (d.actualWeight || d.designWeight || 0),
            0,
          );
          return (
            <span className="text-xs font-mono font-medium">
              {totalKg > 0
                ? totalKg.toLocaleString('vi-VN', { maximumFractionDigits: 2 })
                : '—'}
            </span>
          );
        },
      },
    ],
    [t, itpMap, handleOpenDetailDialog],
  );

  return (
    <div className="space-y-3">
      <div className="border rounded-md overflow-hidden bg-background">
        {isLoading ? (
          <TableSkeleton columns={7} rows={4} showToolbar={false} showHeader={true} />
        ) : (
          <ResizableWrapTable
            data={filteredPackings}
            columns={columns}
            tableMinWidth={1050}
            headerVariant="sub-primary"
            emptyMessage={t('DeliveryPackaging:empty.packings', {
              defaultValue:
                'Chưa có cụm đóng kiện nào phù hợp với thành phẩm và model đã chọn.',
            })}
            toolbarProps={{
              searchValue: searchText,
              onSearchChange: setSearchText,
              searchDebounce: 300,
              searchPlaceholder: t('DeliveryPackaging:placeholder.searchPackings', {
                defaultValue: 'Tìm theo mã ITP, tên thành phẩm, model, mã packing list...',
              }),
              totalCount: packings.length,
              filteredCount: filteredPackings.length,
            }}
          />
        )}
      </div>

      <PackingDetailViewDialog
        open={!!activeDialogPacking}
        onOpenChange={(open) => {
          if (!open) setActiveDialogPacking(null);
        }}
        packingTitle={activeDialogPacking?.title}
        details={activeDialogPacking?.details}
      />
    </div>
  );
}

