const materialModelMap = useMemo(
  () =>
    new Map<string, IModel>((materialModelQuery.data?.data ?? []).map((item) => [item.id, item])),
  [materialModelQuery.data],
);
const fgMap = useMemo(
  () =>
    new Map<string, IFlatItem>(
      (finishedGoodDropdown.data?.data ?? []).map((item) => [item.id, item]),
    ),
  [finishedGoodDropdown.data],
);
const warehouseMap = useMemo(
  () =>
    new Map<string, IFlatItem>(
      (warehouseDropdownData ?? []).map((item) => [
        item.id,
        { id: item.id, name: item.name, code: item.code },
      ]),
    ),
  [warehouseDropdownData],
);

const watchedProjectId = useWatch({ control: form?.control, name: 'projectId' }) as
  | string
  | undefined;

const itpKeys = useMemo(
  () =>
    (watchedGoods || []).map((g) => {
      const fg = g.finishedGoodId ? fgMap.get(g.finishedGoodId) : undefined;
      const model = g.modelId ? materialModelMap.get(g.modelId) : undefined;
      const designModel = g.designModelId ? materialModelMap.get(g.designModelId) : undefined;
      return {
        finishedGoodId: g.finishedGoodId || undefined,
        modelId: g.modelId || undefined,
        designModelId: g.designModelId || undefined,
        finishedGoodCodeSnapshot:
          (g as any).finishedGoodCodeSnapshot || (g as any).finishedGoodCode || fg?.code || undefined,
        finishedGoodNameSnapshot:
          (g as any).finishedGoodNameSnapshot || (g as any).finishedGoodName || fg?.name || undefined,
        modelCodeSnapshot:
          (g as any).modelCodeSnapshot || (g as any).modelCode || model?.code || undefined,
        modelNameSnapshot:
          (g as any).modelNameSnapshot || (g as any).modelName || model?.name || undefined,
        designModelCodeSnapshot:
          (g as any).designModelCodeSnapshot || (g as any).designModelCode || designModel?.code || undefined,
        designModelNameSnapshot:
          (g as any).designModelNameSnapshot || (g as any).designModelName || designModel?.name || undefined,
      };
    }),
  [watchedGoods, fgMap, materialModelMap],
);

const itpMap = useMemo(() => {
  const map = new Map<string, any>();
  itpKeys.forEach((item) => {
    if (item.finishedGoodId && item.modelId) {
      map.set(`${item.finishedGoodId}_${item.modelId}`, item);
    }
    if (item.finishedGoodId) {
      map.set(`fg_${item.finishedGoodId}`, item);
    }
    if (item.modelId) {
      map.set(`model_${item.modelId}`, item);
    }
    if (item.designModelId) {
      map.set(`design_${item.designModelId}`, item);
    }
  });
  return map;
}, [itpKeys]);

const { eligiblePackingsQuery } = useInstallationOrder({
  queryParam: {
    eligiblePackings: {
      params: {
        projectId: watchedProjectId || undefined,
        itpKeys,
      },
      isEnable: shouldFetch && (!!watchedProjectId || itpKeys.length > 0),
    },
  },
});

const resolvedPackings = eligiblePackingsQuery.data?.data || [];

