const deduplicatedPackings = useMemo(() => {
  const seen = new Set<string>();
  const result: InstallationOrderEligiblePackingDto[] = [];
  for (const p of packings) {
    const codeKey = p.mechanicalPackingListCodeSnapshot?.trim().toLowerCase();
    const idKey = p.mechanicalPackingListId || p.id;
    const key = codeKey ? `code_${codeKey}` : `id_${idKey}`;
    if (!seen.has(key)) {
      seen.add(key);
      result.push(p);
    }
  }
  return result;
}, [packings]);

const filteredPackings = useMemo(() => {
  if (!searchText.trim()) return deduplicatedPackings;
  const q = searchText.toLowerCase().trim();
  return deduplicatedPackings.filter((p) => {
    const terms = [
