144: export function useFkLookup<
145:   TData extends object,
146:   TSources extends readonly FkLookupSource<TData>[],
147: >(data: TData[], sources: TSources): UseFkLookupReturn<TSources[number]['key']> {
148:   // `sources` gần như luôn là mảng inline mới mỗi render. Ta không thể "đóng băng" nó — các
149:   // closure `extractIds`/`fetchByIds` capture state của caller nên phải luôn là bản mới nhất.
150:   // Thay vào đó ta ổn định hoá *kết quả* (idsPerSource, result) theo signature nội dung.
151:   const sourcesRef = useRef(sources);
152:   sourcesRef.current = sources;
153:   const currentSources = sourcesRef.current;
154: 
155:   const sourceKeysSignature = sources.map((s) => `${s.key}:${s.cacheKeySuffix ?? ''}`).join(',');
156: 
157:   // ── 1. Extract & dedupe IDs cho mỗi source ────────────────────────────────
158:   const computedIds = useMemo(() => {
159:     return currentSources.map((source: FkLookupSource<TData>) => {
160:       const rawIds = source.extractIds(data);
161:       const uniqueIds = [...new Set(rawIds.filter((id): id is string => !!id))];
162:       return uniqueIds;
163:     });
164:     // eslint-disable-next-line react-hooks/exhaustive-deps
165:   }, [data, sourceKeysSignature]);
166: 
167:   // Caller thường viết `pagingQuery.data?.data ?? []` → `data` đổi identity mà nội dung không đổi,
168:   // làm `computedIds` (và qua đó queryKey + options của useQueries) bị dựng lại mỗi render.
169:   // Giữ lại mảng cũ khi nội dung id không đổi.
170:   const idsSignature = computedIds.map((ids) => ids.join(',')).join('~');
171:   const idsRef = useRef(computedIds);
172:   const idsSignatureRef = useRef(idsSignature);
173:   if (idsSignatureRef.current !== idsSignature) {
174:     idsSignatureRef.current = idsSignature;
175:     idsRef.current = computedIds;
176:   }
177:   const idsPerSource = idsRef.current;
178: 
179:   // ── 2. Parallel queries via useQueries ─────────────────────────────────────
180:   const queries = useQueries({
181:     queries: currentSources.map((source: FkLookupSource<TData>, index: number) => {
182:       const ids = idsPerSource[index] ?? [];
183:       return {
184:         queryKey: ['fk-lookup', source.key, source.cacheKeySuffix ?? '', ids],
185:         queryFn: () => source.fetchByIds(ids),
186:         enabled: ids.length > 0,
187:         staleTime: source.staleTime ?? DEFAULT_STALE_TIME,
188:       };
189:     }),
190:   });
