const existingPackingMap = useMemo(() => {
  const map = new Map<string, boolean>();
  (existingPackingIds || []).forEach((id) => {
    if (id) map.set(id.toLowerCase(), true);
  });
  (existingPackingCodes || []).forEach((code) => {
    if (code && code.trim()) map.set(code.trim().toLowerCase(), true);
  });
  return map;
}, [existingPackingIds, existingPackingCodes]);

