const checkIsAlreadyAdded = useCallback(
  (p: InstallationOrderPackingRow) => {
    const codeKey = p.mechanicalPackingListCodeSnapshot?.trim().toLowerCase();
    const nameKey = p.mechanicalPackingListNameSnapshot?.trim().toLowerCase();
    const mplIdKey = p.mechanicalPackingListId?.toLowerCase();
    const idKey = p.id?.toLowerCase();
    return Boolean(
      (codeKey && (existingPackingMap.has(codeKey) || existingPackingMap.has(codeKey.replace(/-/g, '')))) ||
      (nameKey && (existingPackingMap.has(nameKey) || existingPackingMap.has(nameKey.replace(/-/g, '')))) ||
      (mplIdKey && (existingPackingMap.has(mplIdKey) || existingPackingMap.has(mplIdKey.replace(/-/g, '')))) ||
      (idKey && (existingPackingMap.has(idKey) || existingPackingMap.has(idKey.replace(/-/g, '')))),
    );
  },
  [existingPackingMap],
);

const getPackingKey = useCallback((p: InstallationOrderPackingRow, idx: number) => {
  return (
    p.mechanicalPackingListCodeSnapshot?.trim().toLowerCase() ||
    p.mechanicalPackingListId?.toLowerCase() ||
    p.id?.toLowerCase() ||
    `row_${idx}`
  );
}, []);

// Lọc chỉ giữ lại các cụm CHƯA ĐƯỢC THÊM để đưa vào bảng
const unaddedEligiblePackings = useMemo(() => {
  return eligiblePackings.filter((p) => !checkIsAlreadyAdded(p));
}, [eligiblePackings, checkIsAlreadyAdded]);

const addedCount = eligiblePackings.length - unaddedEligiblePackings.length;

const filteredPackings = useMemo(() => {
  const kw = searchKeyword.trim().toLowerCase();
  if (!kw) return unaddedEligiblePackings;
  return unaddedEligiblePackings.filter((row) => {
    const terms = [
      row.finishedGoodCodeSnapshot,
      row.finishedGoodNameSnapshot,
      row.modelCodeSnapshot,
      row.modelNameSnapshot,
      row.designModelCodeSnapshot,
      row.designModelNameSnapshot,
      row.mechanicalPackingListCodeSnapshot,
      row.mechanicalPackingListNameSnapshot,
    ]
      .filter(Boolean)
      .join(' ')
      .toLowerCase();
    return terms.includes(kw);
  });
}, [unaddedEligiblePackings, searchKeyword]);

const selectablePackings = filteredPackings;

