const handleConfirm = () => {
  // Làm giàu dữ liệu với tên/mã snapshot đã resolve trước khi đẩy ra onSelect, đồng thời loại trừ cụm đã thêm
  const enrichedList = Object.values(selectedPackings)
    .filter((p) => !checkIsAlreadyAdded(p))
    .map((p) => {
      const matchedItp =
        (p.finishedGoodId && p.modelId ? itpMap.get(`${p.finishedGoodId}_${p.modelId}`) : undefined) ??
        (p.finishedGoodId ? itpMap.get(`fg_${p.finishedGoodId}`) : undefined);
      const fkDesign = p.designModelId ? fk.model.getInfo(p.designModelId) : undefined;
      const fkUser = p.modelId ? fk.model.getInfo(p.modelId) : undefined;

      const designName = p.designModelNameSnapshot || matchedItp?.designModelNameSnapshot || fkDesign?.name || null;
      const designCode = p.designModelCodeSnapshot || matchedItp?.designModelCodeSnapshot || fkDesign?.code || null;
      const modelName = p.modelNameSnapshot || matchedItp?.modelNameSnapshot || fkUser?.name || null;
      const modelCode = p.modelCodeSnapshot || matchedItp?.modelCodeSnapshot || fkUser?.code || null;

      return {
        ...p,
        designModelNameSnapshot: designName,
        designModelCodeSnapshot: designCode,
        modelNameSnapshot: modelName,
        modelCodeSnapshot: modelCode,
        finishedGoodNameSnapshot:
          p.finishedGoodNameSnapshot || matchedItp?.finishedGoodNameSnapshot || null,
        finishedGoodCodeSnapshot:
          p.finishedGoodCodeSnapshot || matchedItp?.finishedGoodCodeSnapshot || null,
      };
    });
  onSelect(enrichedList);
  onOpenChange(false);
};

