import { useMemo } from 'react';
import { useTranslation } from 'react-i18next';
import { Info, Loader2 } from 'lucide-react';
import {
  Button,
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from '@shared/ui';
import {
  FinishedGoodsPackingDetailTable,
  type PackingDetailItem,
} from '@/routes/_app/logistic/finished-goods-packing/_components/packing-detail-table';
import { useMechanicalPackingList } from '@/routes/_app/logistic/mechanical-packing-list/_hooks/use-mechanical-packing-list';

interface PackingDetailViewDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  packingTitle?: string;
  details?: PackingDetailItem[];
  mechanicalPackingListId?: string | null;
}

export function PackingDetailViewDialog({
  open,
  onOpenChange,
  packingTitle,
  details = [],
  mechanicalPackingListId,
}: PackingDetailViewDialogProps) {
  const { t } = useTranslation(['installationOrder', 'deliveryPackaging', 'action', 'common']);

  const shouldFetchFromMpl = open && (!details || details.length === 0) && !!mechanicalPackingListId;

  const { getByIdQuery } = useMechanicalPackingList({
    id: shouldFetchFromMpl ? mechanicalPackingListId! : undefined,
    queryParam: {
      getById: {
        isEnable: shouldFetchFromMpl,
        includes: ['Details'],
      },
    },
  });

  const effectiveDetails = useMemo<PackingDetailItem[]>(() => {
    if (details && details.length > 0) return details;
    const mplDetails = getByIdQuery?.data?.data?.details;
    if (Array.isArray(mplDetails) && mplDetails.length > 0) {
      return mplDetails.map((d) => ({
        id: d.id,
        lineNum: d.lineNum,
        actualQuantity: d.quantity,
        actualWeight: d.actualWeight ?? d.designWeight,
        designQuantity: d.quantity,
        designWeight: d.designWeight,
        uomId: d.uomId,
        uomCodeSnapshot: d.uomCodeSnapshot,
        uomNameSnapshot: d.uomNameSnapshot,
        semiFinishedGoodId: d.semiFinishedGoodId,
        semiFinishedGoodCodeSnapshot: d.semiFinishedGoodCodeSnapshot,
        semiFinishedGoodNameSnapshot: d.semiFinishedGoodNameSnapshot,
        productDescription: d.productDescription,
        tagNo: d.tagNo,
        dimensionL: d.dimensionL,
        dimensionW: d.dimensionW,
        dimensionH: d.dimensionH,
        remark: d.remark,
      })) as PackingDetailItem[];
    }
    return [];
  }, [details, getByIdQuery?.data?.data?.details]);

  const isLoading = shouldFetchFromMpl && getByIdQuery.isFetching;

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="w-[96vw] max-w-[96vw] sm:max-w-[96vw] md:max-w-[95vw] lg:max-w-[92vw] xl:max-w-[1500px] h-[90vh] max-h-[92vh] flex flex-col p-6 overflow-hidden">
        <DialogHeader className="pb-3 border-b shrink-0">
          <DialogTitle className="text-lg font-bold flex items-center gap-2">
            <span className="w-1.5 h-4 bg-primary rounded-full" />
            <span>
              {t('installationOrder:packingDetailDialog.title', {
                defaultValue: 'Chi tiết Cụm nhập kho thành phẩm thực tế',
              })}
            </span>
            {packingTitle && (
              <span className="inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium bg-primary/10 text-primary border border-primary/20">
                {packingTitle}
              </span>
            )}
          </DialogTitle>
          <DialogDescription className="text-sm text-muted-foreground">
            {t('installationOrder:packingDetailDialog.description', {
              defaultValue:
                'Xem thông tin quy cách, kích thước, khối lượng và chi tiết các bộ phận đã nhập kho từ phân hệ Đóng kiện.',
            })}
          </DialogDescription>
        </DialogHeader>

        <div className="flex-1 min-h-0 py-3 flex flex-col gap-3 overflow-hidden">
          <div className="flex items-start gap-2.5 text-xs text-muted-foreground bg-primary/5 border border-primary/15 p-3 rounded-lg shrink-0">
            <Info className="w-4 h-4 text-primary shrink-0 mt-0.5" />
            <div className="flex-1 leading-relaxed">
              {t('installationOrder:packingDetailDialog.asBuiltNotice', {
                defaultValue:
                  'Dữ liệu thực tế khi đã nhập kho từ phân hệ Đóng kiện (FinishedGoodsPackingDetail), hiển thị quy cách, kích thước, khối lượng bảo ôn quy đổi và khối lượng cơ khí thực tế.',
              })}
            </div>
          </div>

          <div className="flex-1 min-h-0 border rounded-lg overflow-hidden bg-background flex flex-col">
            {isLoading ? (
              <div className="flex-1 flex flex-col items-center justify-center gap-2 text-muted-foreground">
                <Loader2 className="h-6 w-6 animate-spin text-primary" />
                <span className="text-xs">
                  {t('common:loading', { defaultValue: 'Đang tải chi tiết...' })}
                </span>
              </div>
            ) : (
              <div className="flex-1 overflow-auto">
                <FinishedGoodsPackingDetailTable details={effectiveDetails} headerTone="primary" />
              </div>
            )}
          </div>
        </div>

        <DialogFooter className="pt-3 border-t flex items-center justify-between w-full shrink-0">
          <div className="text-xs text-muted-foreground font-medium">
            {t('installationOrder:packingDetailDialog.totalItems', {
              count: effectiveDetails.length,
              defaultValue: 'Tổng cộng: {{count}} chi tiết',
              replace: { count: effectiveDetails.length },
            })}
          </div>
          <Button type="button" variant="outline" size="sm" onClick={() => onOpenChange(false)}>
            {t('action:close', { defaultValue: 'Đóng' })}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

