const [searchText, setSearchText] = useState('');
const [activeDialogPacking, setActiveDialogPacking] = useState<{
  title: string;
  details: PackingDetailItem[];
  mechanicalPackingListId?: string | null;
} | null>(null);

const [selectionDialogOpen, setSelectionDialogOpen] = useState(false);

const handleOpenDetailDialog = useCallback((row: InstallationOrderPackingRow) => {
  const title =
    row.mechanicalPackingListNameSnapshot ||
    row.mechanicalPackingListCodeSnapshot ||
    row.finishedGoodNameSnapshot ||
    'Cụm đóng kiện';
  setActiveDialogPacking({
    title,
    details: (row.details as PackingDetailItem[]) || [],
    mechanicalPackingListId: row.mechanicalPackingListId || null,
  });
}, []);

const handleAddRow = useCallback(() => {
  append({
    order: fields.length + 1,
    manufacturingMethod: EProductionTeamType.Internal,
  });
}, [append, fields.length]);

useEffect(() => {
  if (isReadOnly) return;
  setToolbar?.(
    <div className="flex items-center gap-2">
      {canAddDetail && (
        <>
          <Button
            type="button"
            variant="outline"
            size="sm"
            onClick={() => setSelectionDialogOpen(true)}
            className="h-8 border-primary/40 text-primary hover:bg-primary/5 hover:text-primary transition-colors shadow-2xs"
          >
            <Plus className="h-3.5 w-3.5 mr-1" />
            {t('action:selectPacking', { defaultValue: 'Chọn cụm nhập kho' })}
          </Button>
          <Button
            type="button"
            variant="outline"
            size="sm"
            onClick={handleAddRow}
            className="h-8 border-primary/40 text-primary hover:bg-primary/5 hover:text-primary transition-colors shadow-2xs"
          >
            <Plus className="h-3.5 w-3.5 mr-1" />
            {t('action:add', { defaultValue: 'Thêm dòng rỗng' })}
          </Button>
        </>
      )}
      {canSaveTab && onSaveTab && (
        <Button
          type="button"
          size="sm"
          variant="ghost"
          className="h-8 border border-primary/35 bg-white px-3 text-xs font-semibold text-primary shadow-sm hover:border-primary/55 hover:bg-primary/5 hover:text-primary"
          onClick={onSaveTab}
          disabled={isSavingTab}
        >
          <Save className="mr-1 h-3.5 w-3.5" />
          {isSavingTab
