270:         IQueryable<TEntity> query,
271:         Expression<Func<TEntity, Guid>> idSelector,
272:         List<Guid> ids)
273:     {
274:         if (ids.Count == 0)
275:         {
276:             return query.Where(_ => false);
277:         }
278: 
279:         var distinctIds = ids
280:             .Where(id => id != Guid.Empty)
281:             .Distinct()
282:             .ToList();
283: 
284:         if (distinctIds.Count == 0)
285:         {
286:             return query.Where(_ => false);
287:         }
288: 
289:         var predicate = Expression.Lambda<Func<TEntity, bool>>(
290:             BuildContains(distinctIds, idSelector.Body),
291:             idSelector.Parameters);
292:         return query.Where(predicate);
