const columns = useMemo<ColumnDef<IFinishedGoodsPacking>[]>(
  () => [
    {
      id: 'select',
      header: ({ table }) => (
        <Checkbox
          checked={
            table.getIsAllPageRowsSelected() ||
            (table.getIsSomePageRowsSelected() && 'indeterminate')
          }
          onCheckedChange={(value) => table.toggleAllPageRowsSelected(!!value)}
          aria-label="Select all"
          className="translate-y-[2px]"
        />
      ),
      cell: ({ row }) => (
        <Checkbox
          checked={row.getIsSelected()}
          onCheckedChange={(value) => row.toggleSelected(!!value)}
          aria-label="Select row"
          className="translate-y-[2px]"
        />
      ),
      enableSorting: false,
      enableHiding: false,
    },
    {
      accessorKey: 'packingCodes.packingCode',
      header: t('finishedGoodsPacking:table.columns.packingCode'),
      cell: ({ row }) =>
        row.original.packingCodes?.packingCode || row.original.packingCodes?.code || '-',
      enableSorting: true,
      enableColumnFilter: true,
      meta: {
        filterElement: () => (
          <PackingCodeFilter
            value={queryParams.packingCode ?? ''}
            onChange={(val) => updateFilters({ packingCode: val || undefined })}
            t={t}
          />
        ),
      },
    },
    {
      accessorKey: 'packingCodes.project.name',
      header: t('finishedGoodsPacking:table.columns.project'),
      cell: ({ row }) => {
        const project = row.original.packingCodes?.project;
        return <DoubleLineCell title={project?.name} subtitle={project?.code} />;
      },
      enableSorting: false,
      enableColumnFilter: true,
      meta: {
        filterElement: () => (
          <ProjectCombobox
            value={queryParams.projectId || ''}
            onValueChange={(val) => updateFilters({ projectId: val || undefined })}
            placeholder={t('common:component.placeholder.select')}
          />
        ),
      },
    },
    {
      id: 'refDoc',
      header: t('finishedGoodsPacking:table.columns.refDoc', {
        defaultValue: 'Phiếu tham chiếu',
      }),
      cell: ({ row }) => {
        const wiInfo = row.original.workItemInfo;
        return (
          <RefDocCell
            refTypeName={wiInfo?.refType}
            refDocCode={wiInfo?.refDocNum}
            fallback="Tạo độc lập"
          />
        );
      },
      meta: { width: 180 },
    },
    {
      accessorKey: 'mechanicalPackingList.finishedGoodsCode',
      header: t('finishedGoodsPacking:table.columns.finishedGoodsCode'),
      cell: ({ row }) => (
        <DoubleLineCell
          title={row.original?.mechanicalPackingList?.finishedGoodsName}
          subtitle={
            row.original?.mechanicalPackingList?.finishedGoodsCode
              ? `Mã: #${row.original.mechanicalPackingList.finishedGoodsCode}`
              : undefined
          }
        />
      ),
      enableSorting: true,
      enableColumnFilter: false,
    },
    {
      accessorKey: 'modelCode',
      header: t('finishedGoodsPacking:table.columns.performanceModel', 'Model hiệu suất'),
      cell: ({ row }) => {
        const code = row.original?.modelCode || row.original?.mechanicalPackingList?.modelCode;
        const name = row.original?.modelName || row.original?.mechanicalPackingList?.modelName;
        return <DoubleLineCell title={name} subtitle={code ? `Mã: #${code}` : undefined} />;
      },
      enableSorting: true,
      enableColumnFilter: true,
      meta: {
        filterElement: () => (
          <DebouncedInput
            value={queryParams.modelCode ?? ''}
            onChange={(val) => updateFilters({ modelCode: val ? String(val) : undefined })}
            placeholder={t('common:component.placeholder.search')}
          />
        ),
      },
    },
    {
      accessorKey: 'designModelCode',
      header: t('finishedGoodsPacking:table.columns.designModel', 'Model thiết kế'),
      cell: ({ row }) => {
        const code =
          row.original?.designModelCode || row.original?.mechanicalPackingList?.designModelCode;
        const name =
          row.original?.designModelName || row.original?.mechanicalPackingList?.designModelName;
        return <DoubleLineCell title={name} subtitle={code ? `Mã: #${code}` : undefined} />;
      },
      enableSorting: true,
      enableColumnFilter: true,
      meta: {
        filterElement: () => (
          <DebouncedInput
            value={queryParams.designModelCode ?? ''}
            onChange={(val) => updateFilters({ designModelCode: val ? String(val) : undefined })}
            placeholder={t('common:component.placeholder.search')}
          />
        ),
      },
    },
    {
      accessorKey: 'createdDate',
      header: t('finishedGoodsPacking:table.columns.createdDate'),
      enableSorting: true,
      enableColumnFilter: true,
      cell: CreatedDateCell,
      meta: {
        filterElement: () => (
          <DateFilter
            value={{ fromDate: queryParams.fromDate, toDate: queryParams.toDate }}
            onChange={(next) => updateFilters(next)}
          />
        ),
      },
    },
    {
      accessorKey: 'lastModifiedDate',
      header: t('finishedGoodsPacking:table.columns.lastModifiedDate', {
        defaultValue: 'Ngày chỉnh sửa',
      }),
      enableSorting: true,
      cell: ({ row }: { row: { original: IFinishedGoodsPacking } }) => {
        const date = row.original.lastModifiedDate
          ? new Date(row.original.lastModifiedDate)
          : undefined;
        return (
          <div className="flex flex-col gap-0.5">
            <span className="text-slate-500 text-sm">
              {date ? format(date, 'dd/MM/yyyy') : '-'}
            </span>
            {row.original.modifiedByUser && (
              <span
                className="text-[11px] text-muted-foreground/70 truncate"
                title={row.original.modifiedByUser}
              >
                {row.original.modifiedByUser}
              </span>
            )}
          </div>
        );
      },
    },
    {
      accessorKey: 'dimensions',
      header: t('finishedGoodsPacking:table.columns.dimensions'),
      cell: ({ row }) => row.original.dimensions || '-',
      enableSorting: true,
    },
    {
      accessorKey: 'actualTotalWeight',
      header: t('finishedGoodsPacking:table.columns.actualTotalWeight'),
      cell: ({ row }) =>
        row.original.actualTotalWeight != null
          ? Number(row.original.actualTotalWeight).toLocaleString()
          : '-',
      enableSorting: true,
    },
    {
      accessorKey: 'status',
      header: t('finishedGoodsPacking:table.columns.status'),
      cell: StatusCellElement,
      enableSorting: false,
      enableColumnFilter: true,
      meta: {
        sticky: 'right',
        filterElement: () => (
          <StatusFilter
            options={
              workItemStatusQuery.data?.data?.map((s: any) => {
                return {
                  label: (
                    <div className="flex items-center gap-2">
                      <DynamicIcon
                        name={s.icon}
                        style={{ width: 14, height: 14, color: s.color }}
                      />
                      <span>{s.name}</span>
                    </div>
                  ),
                  value: s.code,
                };
              }) || []
            }
            value={queryParams.statusCode || ''}
            onChange={(val) => updateFilters({ statusCode: val || undefined })}
            t={t}
          />
        ),
      },
    },
    {
      accessorKey: 'stepAndStatus',
      header: t('finishedGoodsPacking:table.columns.stepAndStatus'),
      cell: StepAndStatusCell,
      enableSorting: false,
      enableColumnFilter: false,
      meta: { sticky: 'right' },
    },
    {
      id: 'actions',
      enableHiding: false,
      cell: ({ row }) => {
        if (!canUpdate && !canDelete && !canView) return null;
        return (
          <div className="flex justify-end gap-2">
            {canUpdate && (
              <Button
                variant="outline"
                size="icon-sm"
                className="text-gray-600 hover:text-primary"
                onClick={() => handleEdit(row.original)}
                title={t('action:edit', 'Chỉnh sửa')}
              >
                <SquarePen className="h-4 w-4" />
              </Button>
            )}
            {canView && (
              <Button
                variant="outline"
                size="icon-sm"
                className="text-gray-600 hover:text-primary"
                onClick={() => handleViewDetail(row.original.id)}
                title={t('action:viewDetail', 'Xem chi tiết')}
              >
                <Eye className="h-4 w-4" />
              </Button>
            )}
            {canDelete && (
              <Button
                variant="outline"
                size="icon-sm"
                className="text-destructive hover:bg-destructive/10"
                onClick={() => setDeleteId(row.original.id)}
                title={t('action:delete', 'Xóa')}
              >
                <Trash2 className="h-4 w-4" />
              </Button>
            )}
          </div>
        );
      },
      meta: {
        width: 150,
        sticky: 'right',
      },
    },
  ],

