359:     private async Task LoadMechDetailSnapshotsAsync(IEnumerable<Guid> mechDetailIds)
360:     {
361:         if (mechDetailIds == null) return;
362:         var ids = mechDetailIds.Distinct().ToList();
363:         if (ids.Count == 0) return;
364: 
365:         var mechDetails = await _unitOfWork.GetRepository<MechanicalPackingListDetail>().Query()
366:             .Where(d => ids.Contains(d.Id))
367:             .ToListAsync();
368: 
369:         _pendingPackingDetailSnapshots = mechDetails.ToDictionary(d => d.Id, d => new PackingDetailSnapshot(
370:             UOMId: d.UOMId,
371:             SemiFinishedGoodId: d.SemiFinishedGoodId,
372:             ProductDescription: d.ProductDescription ?? string.Empty,
373:             TagNo: d.TagNo ?? string.Empty,
374:             DimensionL: d.DimensionL,
375:             DimensionW: d.DimensionW,
376:             DimensionH: d.DimensionH,
377:             DesignQuantity: d.Quantity,
378:             DesignWeight: d.DesignWeight,
379:             InsulationFactoryWeight: d.InsulationFactoryWeight,
380:             InsulationMasonryWeight: d.InsulationMasonryWeight,
381:             LoosePartsFactoryWeight: d.LoosePartsFactoryWeight,
382:             Remark: d.Remark ?? string.Empty));
383:     }
384: 
385:     private async Task PopulatePackingDetailSnapshotsAsync(Guid packingId)
386:     {
387:         if (_pendingPackingDetailSnapshots == null || _pendingPackingDetailSnapshots.Count == 0) return;
388:         var detailRepo = _unitOfWork.GetRepository<FinishedGoodsPackingDetail>();
389:         var details = await detailRepo.Query()
390:             .Where(d => d.FinishedGoodsPackingId == packingId)
391:             .ToListAsync();
392: 
393:         foreach (var d in details)
394:         {
395:             if (!_pendingPackingDetailSnapshots.TryGetValue(d.MechanicalPackingListDetailId, out var s)) continue;
396:             d.UOMId = s.UOMId;
397:             d.SemiFinishedGoodId = s.SemiFinishedGoodId;
398:             d.ProductDescription = s.ProductDescription;
399:             d.TagNo = s.TagNo;
400:             d.DimensionL = s.DimensionL;
401:             d.DimensionW = s.DimensionW;
402:             d.DimensionH = s.DimensionH;
403:             d.DesignQuantity = s.DesignQuantity;
404:             d.DesignWeight = s.DesignWeight;
405:             d.InsulationFactoryWeight = s.InsulationFactoryWeight;
406:             d.InsulationMasonryWeight = s.InsulationMasonryWeight;
407:             d.LoosePartsFactoryWeight = s.LoosePartsFactoryWeight;
408: 
409:             if (string.IsNullOrEmpty(d.Remark))
410:             {
411:                 d.Remark = s.Remark;
412:             }
413: 
414:             // Calculated fields
415:             d.CalculatedDesignWeight = s.DesignQuantity != 0
416:                 ? (s.DesignWeight / s.DesignQuantity) * d.ActualQuantity
417:                 : 0;
418:             d.CalculatedInsulationFactoryWeight = s.InsulationFactoryWeight.HasValue && s.DesignQuantity != 0
419:                 ? (s.InsulationFactoryWeight.Value / s.DesignQuantity) * d.ActualQuantity
420:                 : null;
421:             d.CalculatedInsulationMasonryWeight = s.InsulationMasonryWeight.HasValue && s.DesignQuantity != 0
422:                 ? (s.InsulationMasonryWeight.Value / s.DesignQuantity) * d.ActualQuantity
423:                 : null;
424:             d.CalculatedLoosePartsFactoryWeight = s.LoosePartsFactoryWeight.HasValue && s.DesignQuantity != 0
425:                 ? (s.LoosePartsFactoryWeight.Value / s.DesignQuantity) * d.ActualQuantity
426:                 : null;
427:             d.CalculatedMechanicalWeight = d.ActualWeight - (
428:                 (d.CalculatedInsulationFactoryWeight ?? 0) +
429:                 (d.CalculatedInsulationMasonryWeight ?? 0) +
430:                 (d.CalculatedLoosePartsFactoryWeight ?? 0)
431:             );
432:         }
433:         await _unitOfWork.SaveChangesAsync();
434:         _pendingPackingDetailSnapshots = null;
435:     }
