437:     private async Task<Result> BeforeCreateValidationAsync(CreateFinishedGoodsPackingDto dto)
438:     {
439:         var packingCodeRepo = _unitOfWork.GetRepository<ServiceDesk.Data.Entities.PackingList.PackingCodes>();
440:         var packingCode = await packingCodeRepo.GetByIdAsync(dto.PackingCodesId);
441:         if (packingCode == null)
442:             return Result.Failure("Mã kiện (Packing Code) không tồn tại.", System.Net.HttpStatusCode.BadRequest);
443: 
444:         // Lock PackingCode atomically on create — CAS: only succeeds if still Unused.
445:         // Workflow is now Open → Close (no Submit step), so the lock happens at assignment time.
446:         var rowsUpdated = await packingCodeRepo.BulkUpdateAsync(
447:             predicate: x => x.Id == dto.PackingCodesId && x.UseStatus == EPackingCodeStatusEnums.Unused,
448:             setPropertyCalls: setter => setter.SetProperty(x => x.UseStatus, EPackingCodeStatusEnums.Used));
449: 
450:         if (rowsUpdated == 0)
451:             return Result.Failure("Mã kiện này đã được sử dụng. Vui lòng chọn mã khác!", System.Net.HttpStatusCode.BadRequest);
452: 
453:         return Result.Success();
454:     }
