501:         var result = await _workItemLifecycleService.CreateWithWorkItemAsync<FinishedGoodsPackingDto>(
502:             WorkItemCategoryCode,
503:             async () =>
504:             {
505:                 var preResult = await BeforeCreateValidationAsync(dto);
506:                 if (!preResult.IsSuccess)
507:                     return Result<FinishedGoodsPackingDto>.Failure(preResult.Message, preResult.StatusCode);
508: 
509:                 if (dto.Details?.Count > 0)
510:                 {
511:                     var lockResult = await ValidateNoLockedDetailsAsync(
512:                         dto.Details.Select(d => d.MechanicalPackingListDetailId));
513:                     if (!lockResult.IsSuccess)
514:                         return Result<FinishedGoodsPackingDto>.Failure(lockResult.Message, lockResult.StatusCode);
515:                 }
516: 
517:                 CalculateDimensionsAndWeight(dto);
518:                 var createResult = await base.Create(dto);
519:                 if (createResult.IsSuccess && createResult.Data != null)
520:                 {
521:                     createResult.Data.RefDocId = dto.RefDocId;
522:                     createResult.Data.RefTypeId = dto.RefTypeId;
523:                 }
524:                 return createResult;
525:             },
526:             (result, categoryInfo, createdById) => BuildCreateWorkItemRequest(result, categoryInfo, createdById, refTypeId),
527:             useTransaction: true);
528: 
529:         if (result.IsSuccess && result.Data != null)
530:         {
531:             result.Data.RefDocId = dto.RefDocId;
532:             result.Data.RefTypeId = dto.RefTypeId;
533:         }
534:         return result;
