#region Auto Filter (productionOrderId/modelCode/designModelCode/statusCode intercept)

private WorkItemFilterContext WorkItemFilterContext()
    => new(memoryCache, _masterDataGrpcClient, _logger, WorkItemCategoryCode);

protected override async Task<IQueryable<FinishedGoodsPacking>> BeforeApplyAutoFilterCoreAsync(IQueryable<FinishedGoodsPacking> query, IAutoFilter parameters)
{
    if (parameters == null || string.IsNullOrWhiteSpace(parameters.Filters))
    {
        return query;
    }

    var filters = parameters.Filters;

    // 1. Lọc theo Lệnh sản xuất (ProductionOrderId)
    var productionOrderId = PopFilter(ref filters, "productionOrderId")
        ?? PopFilter(ref filters, "refDocId")
        ?? PopFilter(ref filters, "MechanicalPackingList.ProductionOrderId");

    if (productionOrderId is not null)
    {
        if (Guid.TryParse(productionOrderId, out var poId))
        {
            query = query.Where(x => x.MechanicalPackingList.ProductionOrderId == poId);
        }
        else
        {
            query = query.Where(x => false);
        }
    }

    // 2. Lọc theo Model hiệu suất (modelCode)
    var modelCode = PopFilter(ref filters, "modelCode");
    if (modelCode is not null)
    {
        try
        {
            var response = await _masterDataGrpcClient.GetFinishedGoodModelsByCodesAsync(
                new GetIdsByCodesRequest { Codes = { modelCode } });

            var modelIds = response?.Data?
                .Select(x => Guid.TryParse(x.Id, out var id) ? id : Guid.Empty)
                .Where(x => x != Guid.Empty)
                .ToList() ?? [];

            if (modelIds.Count > 0)
            {
                query = query.Where(x => x.ModelId.HasValue && modelIds.Contains(x.ModelId.Value));
            }
            else
            {
                query = query.Where(x => false);
            }
        }
        catch (Exception ex)
        {
            _logger.Warning(ex, "Lỗi khi lấy ID Model qua gRPC cho filter modelCode");
            query = query.Where(x => false);
        }
    }

    // 3. Lọc theo Model thiết kế (designModelCode)
    var designModelCode = PopFilter(ref filters, "designModelCode");
    if (designModelCode is not null)
    {
        try
        {
            var response = await _masterDataGrpcClient.GetFinishedGoodModelsByCodesAsync(
                new GetIdsByCodesRequest { Codes = { designModelCode } });

            var modelIds = response?.Data?
                .Select(x => Guid.TryParse(x.Id, out var id) ? id : Guid.Empty)
                .Where(x => x != Guid.Empty)
                .ToList() ?? [];

            if (modelIds.Count > 0)
            {
                query = query.Where(x => x.DesignModelId.HasValue && modelIds.Contains(x.DesignModelId.Value));
            }
            else
            {
                query = query.Where(x => false);
            }
        }
        catch (Exception ex)
        {
            _logger.Warning(ex, "Lỗi khi lấy ID Model qua gRPC cho filter designModelCode");
            query = query.Where(x => false);
        }
    }

    parameters.Filters = filters;

    // 4. Các filter ảo WorkItem (statusCode, stepId, stepStatus, ...)
    return await WorkItemAutoFilterHelper.ApplyVirtualFiltersAsync(query, parameters, x => x.Id, WorkItemFilterContext());
}

#endregion

