#region Auto Filter (statusCode/stepId/refDocId intercept)

private WorkItemFilterContext WorkItemFilterContext()
    => new(memoryCache, _masterDataGrpcClient, _logger, WorkItemCategoryCode);

protected override Task<IQueryable<FinishedGoodsPacking>> BeforeApplyAutoFilterCoreAsync(IQueryable<FinishedGoodsPacking> query, IAutoFilter parameters)
    => WorkItemAutoFilterHelper.ApplyVirtualFiltersAsync(query, parameters, x => x.Id, WorkItemFilterContext());

#endregion

#region Auto Filter (StatusCode intercept)
protected override async Task<IQueryable<FinishedGoodsPacking>> BeforeApplyAutoFilterAsync(IQueryable<FinishedGoodsPacking> query, AutoFilterPaging parameters)
{
    if (!string.IsNullOrEmpty(parameters.Filters))
    {
        var statusCodeMatch = System.Text.RegularExpressions.Regex.Match(
            parameters.Filters,
            @"(?i)(?:^|&&|,)\s*statusCode==([^&,]+)");

        if (statusCodeMatch.Success)
        {
            var statusCode = statusCodeMatch.Groups[1].Value.Trim();

            parameters.Filters = System.Text.RegularExpressions.Regex
                .Replace(parameters.Filters, @"(?i)(^|&&|,)\s*statusCode==[^&,]+", "")
                .Trim('&', ',', ' ');
            parameters.Filters = parameters.Filters.Replace("&&&&", "&&").Replace(",,", ",");

            if (!string.IsNullOrEmpty(statusCode))
            {
                var ids = await WorkItemGrpcFilterHelper.GetWorkItemIdsByStatusAsync(
                    memoryCache,
                    _masterDataGrpcClient,
                    _logger,
                    WorkItemCategoryCode,
                    statusCode);
                if (ids.Count == 0)
                {
                    query = query.Where(x => false);
                }
                else
                {
                    query = query.Where(x => ids.Contains(x.Id));
                }
            }
        }

        var modelCodeMatch = System.Text.RegularExpressions.Regex.Match(
            parameters.Filters,
            @"(?i)(?:^|&&|,)\s*modelCode==([^&,]+)");

        if (modelCodeMatch.Success)
        {
            var modelCode = modelCodeMatch.Groups[1].Value.Trim();

            parameters.Filters = System.Text.RegularExpressions.Regex
                .Replace(parameters.Filters, @"(?i)(^|&&|,)\s*modelCode==[^&,]+", "")
                .Trim('&', ',', ' ');
            parameters.Filters = parameters.Filters.Replace("&&&&", "&&").Replace(",,", ",");

            if (!string.IsNullOrEmpty(modelCode))
            {
                try
                {
                    var response = await _masterDataGrpcClient.GetFinishedGoodModelsByCodesAsync(
                        new GetIdsByCodesRequest { Codes = { modelCode } });

                    var modelIds = response?.Data?
                        .Select(x => Guid.TryParse(x.Id, out var id) ? id : Guid.Empty)
                        .Where(x => x != Guid.Empty)
                        .ToList() ?? [];

                    if (modelIds.Count > 0)
                    {
                        query = query.Where(x => x.ModelId.HasValue && modelIds.Contains(x.ModelId.Value));
                    }
                    else
                    {
                        query = query.Where(x => false);
                    }
                }
                catch (Exception ex)
                {
                    _logger.Warning(ex, "Lỗi khi lấy ID Model qua gRPC cho filter modelCode");
                    query = query.Where(x => false);
                }
            }
        }
    }

    return await base.BeforeApplyAutoFilterAsync(query, parameters);
}
#endregion

