import React from 'react';
import { useTranslation } from 'react-i18next';
import { Wrench, Cpu } from 'lucide-react';
import { cn } from '@shared/utils';
import { EFinishedGoodsPackingType } from '@/types/packaging-and-warehouse/finished-goods-packing.type';

export interface PackingTypeBadgeProps {
  readonly type?: EFinishedGoodsPackingType | number | string | null;
  readonly size?: 'sm' | 'default' | 'lg';
  readonly className?: string;
  readonly showIcon?: boolean;
}

/**
 * PackingTypeBadge
 * Renders a prominent visual indicator for Finished Goods Packing Type:
 * - Mechanical (Cơ khí - 1): Sky/Blue theme with Wrench icon
 * - Component (Linh kiện - 2): Purple/Indigo theme with Cpu icon
 */
export function PackingTypeBadge({
  type,
  size = 'default',
  className,
  showIcon = true,
}: PackingTypeBadgeProps) {
  const { t } = useTranslation('finishedGoodsPacking');

  const numericType = Number(type);
  const isComponent = numericType === EFinishedGoodsPackingType.Component || numericType === 2;

  const config = isComponent
    ? {
        label: t('types.component', { defaultValue: 'Linh kiện' }),
        Icon: Cpu,
        wrapperClass:
          'bg-gradient-to-r from-purple-50 via-purple-50/80 to-indigo-50/70 border-purple-300 text-purple-700 shadow-2xs hover:border-purple-400 dark:from-purple-950/60 dark:via-purple-950/40 dark:to-indigo-950/40 dark:border-purple-800 dark:text-purple-300',
        iconBadgeClass: 'bg-purple-600 text-white shadow-2xs ring-1 ring-purple-600/30',
      }
    : {
        label: t('types.mechanical', { defaultValue: 'Cơ khí' }),
        Icon: Wrench,
        wrapperClass:
          'bg-gradient-to-r from-sky-50 via-sky-50/80 to-blue-50/70 border-sky-300 text-sky-700 shadow-2xs hover:border-sky-400 dark:from-sky-950/60 dark:via-sky-950/40 dark:to-blue-950/40 dark:border-sky-800 dark:text-sky-300',
        iconBadgeClass: 'bg-sky-600 text-white shadow-2xs ring-1 ring-sky-600/30',
      };

  const sizeClasses = {
    sm: {
      pill: 'px-2 py-0.5 text-xs font-semibold gap-1.5',
      iconBox: 'w-4 h-4',
      icon: 'w-2.5 h-2.5',
    },
    default: {
      pill: 'px-2.5 py-1 text-xs font-semibold gap-1.5',
      iconBox: 'w-4.5 h-4.5',
      icon: 'w-3 h-3',
    },
    lg: {
      pill: 'px-3 py-1 text-sm font-bold gap-2',
      iconBox: 'w-5.5 h-5.5',
      icon: 'w-3.5 h-3.5',
    },
  }[size];

  const { Icon } = config;

  return (
    <span
      className={cn(
        'inline-flex items-center rounded-full border transition-all duration-150 select-none shrink-0 tracking-wide',
        config.wrapperClass,
        sizeClasses.pill,
        className,
      )}
    >
      {showIcon && (
        <span
          className={cn(
            'flex items-center justify-center rounded-full shrink-0',
            config.iconBadgeClass,
            sizeClasses.iconBox,
          )}
        >
          <Icon className={sizeClasses.icon} />
        </span>
      )}
      <span className="truncate">{config.label}</span>
    </span>
  );
}

