Nên tách thành một hàm riêng `ValidateDetailQuantitiesAsync` để có thể tái sử dụng cho cả **Create** và **Update** (loại trừ các phiếu đã bị `Cancelled` và loại trừ chính phiếu đang cập nhật):

```csharp
private async Task<Result> ValidateDetailQuantitiesAsync(
    Guid mechanicalPackingListId,
    IEnumerable<CreateFinishedGoodsPackingDetailDto>? details,
    Guid? excludePackingId = null)
{
    if (details == null) return Result.Success();

    // 1. Gom nhóm số lượng theo từng chi tiết kỹ thuật trong DTO hiện tại
    var requestedQuantities = details
        .Where(d => d.MechanicalPackingListDetailId != Guid.Empty && d.ActualQuantity > 0)
        .GroupBy(d => d.MechanicalPackingListDetailId)
        .ToDictionary(g => g.Key, g => g.Sum(x => x.ActualQuantity));

    if (requestedQuantities.Count == 0) return Result.Success();

    var detailIds = requestedQuantities.Keys.ToList();

    // 2. Lấy số lượng thiết kế từ cả 2 bảng (Cơ khí & Vật tư/Linh kiện)
    var mechDetails = await _unitOfWork.GetRepository<MechanicalPackingListDetail>().Query()
        .AsNoTracking()
        .Where(d => detailIds.Contains(d.Id))
        .Select(d => new { d.Id, d.Quantity, DisplayName = !string.IsNullOrEmpty(d.TagNo) ? d.TagNo : d.ProductDescription })
        .ToListAsync();

    var missingIds = detailIds.Except(mechDetails.Select(d => d.Id)).ToList();
    var matDetails = missingIds.Count > 0
        ? await _unitOfWork.GetRepository<MaterialPackingListDetail>().Query()
            .AsNoTracking()
            .Where(m => missingIds.Contains(m.Id))
            .Select(m => new { m.Id, m.Quantity, DisplayName = !string.IsNullOrEmpty(m.MaterialCodeSnapshot) ? m.MaterialCodeSnapshot : m.MaterialNameSnapshot })
            .ToListAsync()
        : [];

    var targetDict = mechDetails.Concat(matDetails)
        .ToDictionary(d => d.Id, d => (d.Quantity, DisplayName: d.DisplayName ?? d.Id.ToString()));

    // 3. Tính tổng số lượng đã đóng trong các phiếu trước đó (Bỏ qua các phiếu đã HỦY và phiếu đang cập nhật nếu có)
    var cancelledIds = await GetCancelledWorkItemIdsAsync();

    var existingPackingQuery = _repository.Query()
        .AsNoTracking()
        .Where(p => p.MechanicalPackingListId == mechanicalPackingListId);

    if (cancelledIds.Count > 0)
        existingPackingQuery = existingPackingQuery.Where(p => !cancelledIds.Contains(p.Id));

    if (excludePackingId.HasValue && excludePackingId.Value != Guid.Empty)
        existingPackingQuery = existingPackingQuery.Where(p => p.Id != excludePackingId.Value);

    var existingPackingIds = await existingPackingQuery.Select(p => p.Id).ToListAsync();

    var alreadyPackedSums = existingPackingIds.Count > 0
        ? await _unitOfWork.GetRepository<FinishedGoodsPackingDetail>().Query()
            .AsNoTracking()
            .Where(d => existingPackingIds.Contains(d.FinishedGoodsPackingId) && detailIds.Contains(d.MechanicalPackingListDetailId))
            .GroupBy(d => d.MechanicalPackingListDetailId)
            .Select(g => new { DetailId = g.Key, TotalActual = g.Sum(x => x.ActualQuantity) })
            .ToDictionaryAsync(x => x.DetailId, x => x.TotalActual)
        : [];

    // 4. Kiểm tra từng chi tiết: Yêu cầu đóng <= Còn lại được phép đóng
    foreach (var (detailId, requestedQty) in requestedQuantities)
    {
        if (!targetDict.TryGetValue(detailId, out var target))
        {
            return Result.Failure($"Không tìm thấy thông tin chi tiết kỹ thuật cho ID: {detailId}", System.Net.HttpStatusCode.BadRequest);
        }

        var alreadyPacked = alreadyPackedSums.GetValueOrDefault(detailId, 0m);
        var remainingAllowed = target.Quantity - alreadyPacked;

        if (requestedQty > remainingAllowed)
