Dictionary<Guid, (decimal Quantity, string DisplayName)> targetDict;

if (packingType == EFinishedGoodsPackingType.Mechanical)
{
    var mechDetails = await _unitOfWork.GetRepository<MechanicalPackingListDetail>().Query()
        .AsNoTracking()
        .Where(d => detailIds.Contains(d.Id))
        .Select(d => new { d.Id, d.Quantity, DisplayName = !string.IsNullOrEmpty(d.TagNo) ? d.TagNo : d.ProductDescription })
        .ToListAsync();

    targetDict = mechDetails.ToDictionary(d => d.Id, d => (d.Quantity, DisplayName: d.DisplayName ?? d.Id.ToString()));
}
else if (packingType == EFinishedGoodsPackingType.Component)
{
    var matDetails = await _unitOfWork.GetRepository<MaterialPackingListDetail>().Query()
        .AsNoTracking()
        .Where(m => detailIds.Contains(m.Id))
        .Select(m => new { m.Id, m.Quantity, DisplayName = !string.IsNullOrEmpty(m.MaterialCodeSnapshot) ? m.MaterialCodeSnapshot : m.MaterialNameSnapshot })
        .ToListAsync();

    targetDict = matDetails.ToDictionary(d => d.Id, d => (d.Quantity, DisplayName: d.DisplayName ?? d.Id.ToString()));
}
else
{
    // Fallback nếu không truyền Type
    var mechDetails = await _unitOfWork.GetRepository<MechanicalPackingListDetail>().Query()
        .AsNoTracking()
        .Where(d => detailIds.Contains(d.Id))
        .Select(d => new { d.Id, d.Quantity, DisplayName = !string.IsNullOrEmpty(d.TagNo) ? d.TagNo : d.ProductDescription })
        .ToListAsync();

    var missingIds = detailIds.Except(mechDetails.Select(d => d.Id)).ToList();
    var matDetails = missingIds.Count > 0
        ? await _unitOfWork.GetRepository<MaterialPackingListDetail>().Query()
            .AsNoTracking()
            .Where(m => missingIds.Contains(m.Id))
            .Select(m => new { m.Id, m.Quantity, DisplayName = !string.IsNullOrEmpty(m.MaterialCodeSnapshot) ? m.MaterialCodeSnapshot : m.MaterialNameSnapshot })
            .ToListAsync()
        : [];

    targetDict = mechDetails.Concat(matDetails)
        .ToDictionary(d => d.Id, d => (d.Quantity, DisplayName: d.DisplayName ?? d.Id.ToString()));
}
