501:         d.CalculatedLoosePartsFactoryWeight = s.LoosePartsFactoryWeight.HasValue && s.DesignQuantity != 0
502:             ? (s.LoosePartsFactoryWeight.Value / s.DesignQuantity) * d.ActualQuantity
503:             : null;
504:         d.CalculatedMechanicalWeight = d.ActualWeight - (
505:             (d.CalculatedInsulationFactoryWeight ?? 0) +
506:             (d.CalculatedInsulationMasonryWeight ?? 0) +
507:             (d.CalculatedLoosePartsFactoryWeight ?? 0)
508:         );
