protected override async Task AfterMapperAsync(CreateFinishedGoodsPackingDto dto, FinishedGoodsPacking entity)
{
    if (entity.Details != null)
    {
        foreach (var detail in entity.Details)
        {
            if (dto.Type == EFinishedGoodsPackingType.Component)
            {
                detail.MaterialPackingListDetailId ??= detail.MechanicalPackingListDetailId;
                detail.MechanicalPackingListDetailId = null;
            }
            else if (dto.Type == EFinishedGoodsPackingType.Mechanical)
            {
                detail.MechanicalPackingListDetailId ??= detail.MaterialPackingListDetailId;
                detail.MaterialPackingListDetailId = null;
            }

            ApplyMechDetailSnapshot(detail);
            detail.FinishedGoodsPackingId = entity.Id;
            if (string.IsNullOrEmpty(detail.FinishedGoodsPackingCodeSnapshot)) detail.FinishedGoodsPackingCodeSnapshot = entity.Code;
            if (string.IsNullOrEmpty(detail.FinishedGoodsPackingNameSnapshot)) detail.FinishedGoodsPackingNameSnapshot = entity.Code;
        }
    }

    if (string.IsNullOrEmpty(entity.MechanicalPackingListCodeSnapshot) && entity.MechanicalPackingListId != Guid.Empty)
    {
        var mechList = await _unitOfWork.GetRepository<MechanicalPackingList>().GetByIdAsync(entity.MechanicalPackingListId);
        if (mechList != null)
        {
            entity.MechanicalPackingListCodeSnapshot = mechList.Code;
            entity.MechanicalPackingListNameSnapshot = mechList.FinishedGoodsName ?? mechList.Code;
        }
    }

    if (string.IsNullOrEmpty(entity.PackingCodesCodeSnapshot) && entity.PackingCodesId != Guid.Empty)
    {
        var packingCode = await _unitOfWork.GetRepository<PackingCodes>().GetByIdAsync(entity.PackingCodesId);
        if (packingCode != null)
        {
            entity.PackingCodesCodeSnapshot = packingCode.Code;
            entity.PackingCodesNameSnapshot = packingCode.PackingCode ?? packingCode.Code;
        }
    }

    _snapshotLifecycle.ApplyCurrent(entity, _snapshotPolicy.Apply);
    _pendingPackingDetailSnapshots = null;
}

protected override FinishedGoodsPacking BuildIncomingGraph(UpdateFinishedGoodsPackingDto dto, FinishedGoodsPacking existing) => new()
{
    Details = dto.Details?.Select(d =>
    {
        var isComp = dto.Type == EFinishedGoodsPackingType.Component ||
                     (dto.Type == null && existing.Type == EFinishedGoodsPackingType.Component);
        var mechDetailId = isComp ? null : (d.MechanicalPackingListDetailId ?? d.MaterialPackingListDetailId);
        var matDetailId = isComp ? (d.MaterialPackingListDetailId ?? d.MechanicalPackingListDetailId) : null;

        var detail = new FinishedGoodsPackingDetail
        {
            FinishedGoodsPackingId = existing.Id,
            MechanicalPackingListDetailId = mechDetailId,
            MaterialPackingListDetailId = matDetailId,
            LineNum = d.LineNum,
            ActualQuantity = d.ActualQuantity,
            ActualWeight = d.ActualWeight,
            Remark = d.Remark,
            ProductionTeamId = d.ProductionTeamId,
            PartQuantity = d.PartQuantity,
            Weight = d.Weight,
            PackingStandardId = d.PackingStandardId,
            PackagingSpecificationId = d.PackagingSpecificationId,
            MmccdcRequirement = d.MmccdcRequirement,
            LaborRequirement = d.LaborRequirement,
            ChecklistCode = d.ChecklistCode,
        };
        ApplyMechDetailSnapshot(detail);
        if (detail.UOMId == Guid.Empty && existing.Details != null)
        {
            var targetId = matDetailId ?? mechDetailId;
            var existingDetail = existing.Details.FirstOrDefault(x =>
                (x.MechanicalPackingListDetailId == targetId || x.MaterialPackingListDetailId == targetId) && x.LineNum == d.LineNum);
            if (existingDetail != null)
            {
                detail.UOMId = existingDetail.UOMId;
                detail.SemiFinishedGoodId ??= existingDetail.SemiFinishedGoodId;
                if (string.IsNullOrEmpty(detail.ProductDescription)) detail.ProductDescription = existingDetail.ProductDescription;
                if (string.IsNullOrEmpty(detail.TagNo)) detail.TagNo = existingDetail.TagNo;
                if (detail.DimensionL == 0) detail.DimensionL = existingDetail.DimensionL;
                if (detail.DimensionW == 0) detail.DimensionW = existingDetail.DimensionW;
                if (detail.DimensionH == 0) detail.DimensionH = existingDetail.DimensionH;
                if (detail.DesignQuantity == 0) detail.DesignQuantity = existingDetail.DesignQuantity;
                if (detail.DesignWeight == 0) detail.DesignWeight = existingDetail.DesignWeight;
                detail.InsulationFactoryWeight ??= existingDetail.InsulationFactoryWeight;
                detail.InsulationMasonryWeight ??= existingDetail.InsulationMasonryWeight;
                detail.LoosePartsFactoryWeight ??= existingDetail.LoosePartsFactoryWeight;
                if (string.IsNullOrEmpty(detail.MechanicalPackingListDetailCodeSnapshot))
                    detail.MechanicalPackingListDetailCodeSnapshot = existingDetail.MechanicalPackingListDetailCodeSnapshot;
                if (string.IsNullOrEmpty(detail.MechanicalPackingListDetailNameSnapshot))
                    detail.MechanicalPackingListDetailNameSnapshot = existingDetail.MechanicalPackingListDetailNameSnapshot;
                if (string.IsNullOrEmpty(detail.MaterialPackingListDetailCodeSnapshot))
                    detail.MaterialPackingListDetailCodeSnapshot = existingDetail.MaterialPackingListDetailCodeSnapshot;
                if (string.IsNullOrEmpty(detail.MaterialPackingListDetailNameSnapshot))
                    detail.MaterialPackingListDetailNameSnapshot = existingDetail.MaterialPackingListDetailNameSnapshot;
            }
        }
        return detail;
    }).ToList() ?? []
};

