private void ApplyMechDetailSnapshot(FinishedGoodsPackingDetail d)
{
    var targetId = d.MechanicalPackingListDetailId ?? d.MaterialPackingListDetailId ?? Guid.Empty;
    if (_pendingPackingDetailSnapshots == null ||
        !_pendingPackingDetailSnapshots.TryGetValue(targetId, out var s))
        return;

    d.UOMId = s.UOMId;
    d.SemiFinishedGoodId = s.SemiFinishedGoodId;
    d.ProductDescription = s.ProductDescription;
    d.TagNo = s.TagNo;
    d.DimensionL = s.DimensionL;
    d.DimensionW = s.DimensionW;
    d.DimensionH = s.DimensionH;
    d.DesignQuantity = s.DesignQuantity;
    d.DesignWeight = s.DesignWeight;
    d.InsulationFactoryWeight = s.InsulationFactoryWeight;
    d.InsulationMasonryWeight = s.InsulationMasonryWeight;
    d.LoosePartsFactoryWeight = s.LoosePartsFactoryWeight;

    if (d.MaterialPackingListDetailId.HasValue)
    {
        d.MaterialPackingListDetailCodeSnapshot = s.TagNo;
        d.MaterialPackingListDetailNameSnapshot = s.ProductDescription;
    }
    if (d.MechanicalPackingListDetailId.HasValue)
    {
        d.MechanicalPackingListDetailCodeSnapshot = s.TagNo;
        d.MechanicalPackingListDetailNameSnapshot = s.ProductDescription;
    }

    if (string.IsNullOrEmpty(d.Remark))
    {
        d.Remark = s.Remark;
    }

    // Calculated fields
    d.CalculatedDesignWeight = s.DesignQuantity != 0
        ? (s.DesignWeight / s.DesignQuantity) * d.ActualQuantity
        : 0;
    d.CalculatedInsulationFactoryWeight = s.InsulationFactoryWeight.HasValue && s.DesignQuantity != 0
        ? (s.InsulationFactoryWeight.Value / s.DesignQuantity) * d.ActualQuantity
        : null;
    d.CalculatedInsulationMasonryWeight = s.InsulationMasonryWeight.HasValue && s.DesignQuantity != 0
        ? (s.InsulationMasonryWeight.Value / s.DesignQuantity) * d.ActualQuantity
        : null;
    d.CalculatedLoosePartsFactoryWeight = s.LoosePartsFactoryWeight.HasValue && s.DesignQuantity != 0
        ? (s.LoosePartsFactoryWeight.Value / s.DesignQuantity) * d.ActualQuantity
        : null;
    d.CalculatedMechanicalWeight = d.ActualWeight - (
        (d.CalculatedInsulationFactoryWeight ?? 0) +
        (d.CalculatedInsulationMasonryWeight ?? 0) +
        (d.CalculatedLoosePartsFactoryWeight ?? 0)
    );
}

