public async Task<Result> AdjustDetailAsync(Guid id, Guid detailId, AdjustMechanicalPackingListDetailDto dto, CancellationToken cancellationToken = default)
{
    if (!await CheckIsPackingStepAsync(id, cancellationToken))
        return Result.Failure("Phiếu packing list không ở bước CHỜ ĐÓNG KIỆN (PACKING).", System.Net.HttpStatusCode.UnprocessableEntity);

    var detailRepo = _unitOfWork.GetRepository<MechanicalPackingListDetail>();
    var detail = await detailRepo.Query().AsNoTracking()
        .FirstOrDefaultAsync(d => d.Id == detailId && d.MechanicalPackingListId == id, cancellationToken);

    var matRepo = _unitOfWork.GetRepository<MaterialPackingListDetail>();
    var matDetail = detail == null
        ? await matRepo.Query().AsNoTracking().FirstOrDefaultAsync(d => d.Id == detailId && d.MechanicalPackingListId == id, cancellationToken)
        : null;

    if (detail == null && matDetail == null)
        return Result.Failure("Không tìm thấy chi tiết packing list.", System.Net.HttpStatusCode.NotFound);

    var changeRepo = _unitOfWork.GetRepository<MechanicalPackingListDetailChange>();

    if (detail != null)
    {
        // Validate lower-bound cho chi tiết cơ khí
        var (packedQty, packedWt) = await GetPackedActualAsync(detailId, cancellationToken);
        if (dto.Quantity < packedQty)
            return Result.Failure(
                $"Số lượng điều chỉnh ({dto.Quantity}) không được nhỏ hơn số lượng đã đóng kiện ({packedQty}).",
                System.Net.HttpStatusCode.BadRequest);
        if (dto.DesignWeight < packedWt)
            return Result.Failure(
                $"Trọng lượng thiết kế điều chỉnh ({dto.DesignWeight}) không được nhỏ hơn trọng lượng đã đóng kiện ({packedWt}).",
                System.Net.HttpStatusCode.BadRequest);

        var newData = JsonSerializer.Serialize(new { dto.Quantity, dto.DesignWeight });
        var diff = JsonSerializer.Serialize(new
        {
            Quantity = new { Old = detail.Quantity, New = dto.Quantity, Delta = dto.Quantity - detail.Quantity },
            DesignWeight = new { Old = detail.DesignWeight, New = dto.DesignWeight, Delta = dto.DesignWeight - detail.DesignWeight }
        });

        var existingPending = await changeRepo.Query()
            .FirstOrDefaultAsync(c => c.TargetDetailId == detailId
                                      && c.RequestStatus == ChangeRequestStatus.Pending
                                      && c.RequestType == ChangeRequestType.Modify, cancellationToken);

        if (existingPending != null)
        {
            existingPending.NewData = newData;
            existingPending.Diff = diff;
        }
        else
        {
            var request = new MechanicalPackingListDetailChange
            {
                Id = Guid.NewGuid(),
                MechanicalPackingListId = id,
                TargetDetailId = detailId,
                TargetDetailCodeSnapshot = detail.TagNo,
                TargetDetailNameSnapshot = detail.ProductDescription,
                RequestType = ChangeRequestType.Modify,
                RequestStatus = ChangeRequestStatus.Pending,
                OldData = JsonSerializer.Serialize(new { detail.Quantity, detail.DesignWeight }),
                NewData = newData,
                Diff = diff
            };
            await changeRepo.AddAsync(request);
        }
    }
    else if (matDetail != null)
    {
        // Validate lower-bound cho chi tiết linh kiện / NVL
        var (packedQty, _) = await GetPackedActualAsync(detailId, cancellationToken);
        if (dto.Quantity < packedQty)
            return Result.Failure(
                $"Số lượng điều chỉnh ({dto.Quantity}) không được nhỏ hơn số lượng đã đóng kiện ({packedQty}).",
                System.Net.HttpStatusCode.BadRequest);

        var newData = JsonSerializer.Serialize(new { dto.Quantity });
        var diff = JsonSerializer.Serialize(new
        {
            Quantity = new { Old = matDetail.Quantity, New = dto.Quantity, Delta = dto.Quantity - matDetail.Quantity }
        });

        var existingPending = await changeRepo.Query()
            .FirstOrDefaultAsync(c => c.TargetMaterialDetailId == detailId
                                      && c.RequestStatus == ChangeRequestStatus.Pending
                                      && c.RequestType == ChangeRequestType.Modify, cancellationToken);

        if (existingPending != null)
        {
            existingPending.NewData = newData;
            existingPending.Diff = diff;
        }
        else
        {
            var request = new MechanicalPackingListDetailChange
            {
                Id = Guid.NewGuid(),
                MechanicalPackingListId = id,
                TargetMaterialDetailId = detailId,
                TargetMaterialDetailCodeSnapshot = matDetail.MaterialCodeSnapshot,
                TargetMaterialDetailNameSnapshot = matDetail.MaterialNameSnapshot,
                RequestType = ChangeRequestType.Modify,
                RequestStatus = ChangeRequestStatus.Pending,
                OldData = JsonSerializer.Serialize(new { matDetail.Quantity }),
                NewData = newData,
                Diff = diff
            };
            await changeRepo.AddAsync(request);
        }
    }

    await _unitOfWork.SaveChangesAsync(cancellationToken);
    return Result.Success();
}

