private async Task<Result> ApproveRequestsAsync(Guid id, IEnumerable<MechanicalPackingListDetailChange> requests, CancellationToken cancellationToken)
{
    var changeRepo = _unitOfWork.GetRepository<MechanicalPackingListDetailChange>();
    var stamp = await CreateResolveStampAsync();

    foreach (var req in requests)
    {
        var applied = await ApplyChangeRequestAsync(id, req, cancellationToken);
        if (!applied.IsSuccess)
            return Result.Failure(applied.Message, applied.StatusCode);

        // ADD: backfill TargetDetailId = dòng vừa commit để Enrich đối chiếu ngược về request
        var updatedReq = req.RequestType == ChangeRequestType.Add
            ? req with { TargetDetailId = applied.Data }
            : req;

        await changeRepo.UpdateAsync(Resolve(updatedReq, ChangeRequestStatus.Approved, stamp));
    }

    await _unitOfWork.SaveChangesAsync(cancellationToken);
    return Result.Success();
}

