const fs = require('fs');
const file = 'c:/Users/Admin/Desktop/CogainCore/cogain-core/backend/src/Services/ServiceDesk/ServiceDesk.Services/Implement/PackingList/MechanicalPackingLists/MechanicalPackingListService.Enrich.cs';
