export const renderPackingStatusCell = (
  status: number | null | undefined,
  actualQty: number | null | undefined,
  designQty: number | string | null | undefined,
  labels: { full: string; partial: string; empty: string },
) => {
  const resolved = status ?? EPackingReportStatus.Empty;
  let label = labels.empty;
  let badgeClass = 'border-slate-200 bg-slate-50 text-slate-600';

  if (resolved === EPackingReportStatus.Full) {
    label = labels.full;
    badgeClass = 'border-emerald-200 bg-emerald-50 text-emerald-700';
  } else if (resolved === EPackingReportStatus.Partial) {
    label = labels.partial;
    badgeClass = 'border-amber-200 bg-amber-50 text-amber-700';
  }

  const formattedActual =
    actualQty !== null && actualQty !== undefined ? Number(actualQty).toLocaleString() : '0';

  const numDesignQty = Number(designQty) || 0;

  return (
    <div className="flex flex-col items-center gap-1 w-full justify-center text-center">
      <span className={`${STATUS_BADGE_BASE} ${badgeClass}`}>{label}</span>
      <span className="text-[11px] text-muted-foreground whitespace-nowrap">
        SL: {formattedActual} / {numDesignQty.toLocaleString()}
      </span>
    </div>
  );
};

