// State for cascading selects
const [selectedMechId, setSelectedMechId] = useState<string>('');
const [isIndependent, setIsIndependent] = useState(false);
const isFormPopulating = useRef(false);

const targetMechId = useMemo(() => {
  return (
    selectedMechId ||
    (isEditMode ? (editingItem?.mechanicalPackingListId || '') : '')
  );
}, [selectedMechId, isEditMode, editingItem?.mechanicalPackingListId]);

// ─── Form setup ─────────────────────────────────────────────────────────────
const formSchema = useMemo(() => createFormSchema(t, isIndependent), [t, isIndependent]);

const form = useForm<FormValues>({
  resolver: zodResolver(formSchema),
  defaultValues: {
    type: EFinishedGoodsPackingType.Mechanical,
    packingCodesId: '',
    mechanicalPackingListId: '',
    productionOrderId: '',
    dimensionL: '',
    dimensionW: '',
    dimensionH: '',
    details: [],
  },
});

const watchedType =
  useWatch({ control: form.control, name: 'type' }) ?? EFinishedGoodsPackingType.Mechanical;
const isComponent = watchedType === EFinishedGoodsPackingType.Component;

const { fields, append, remove, replace } = useFieldArray({
  control: form.control,
  name: 'details',
});

const PACKING_TYPE_OPTIONS = useMemo(
  () => [
    {
      id: 'packing-type-mechanical',
      value: EFinishedGoodsPackingType.Mechanical,
      label: t('dialogs.add.types.mechanical', { defaultValue: 'Cơ khí' }),
      Icon: Wrench,
    },
    {
      id: 'packing-type-component',
      value: EFinishedGoodsPackingType.Component,
      label: t('dialogs.add.types.component', { defaultValue: 'Linh kiện' }),
      Icon: Cpu,
    },
  ],
  [t],
);

const {
  createMutation,
  updateMutation,
  getByIdQuery,
  getActiveByMechListQuery: existingPackingsQuery,
} = useFinishedGoodsPacking({
  id: editingItem?.id,
  queryParam: {
    getById: {
      isEnable: isEditMode && open,
      includes: [
        'PackingCodes',
        'MechanicalPackingList',
        'MechanicalPackingList.ProductionOrder',
        ...FINISHED_GOODS_PACKING_DETAIL_INCLUDES,
      ],
    },
  },
  activeByMechList: {
    mechanicalPackingListId: targetMechId,
    excludePackingId: editingItem?.id,
    isEnable: !!targetMechId,
  },
});

const isPending = createMutation.isPending || updateMutation.isPending;
const fullItem = isEditMode ? (getByIdQuery.data?.data ?? editingItem) : null;

// ─── Data queries ───────────────────────────────────────────────────────────

// Get selected MechanicalPackingList details (both Details and MaterialDetails)
const { getByIdQuery: selectedMechListQuery } = useMechanicalPackingList({
  id: targetMechId,
  queryParam: {
    getById: {
      isEnable: !!targetMechId && open,
      includes: ['Details', 'MaterialDetails'],
    },
  },
});

const selectedMechList = selectedMechListQuery.data?.data as IMechanicalPackingList | undefined;
const activeMech = useMemo(() => {
  return (
    selectedMechList ||
    fullItem?.mechanicalPackingList ||
    (editingItem?.mechanicalPackingList as IMechanicalPackingList | undefined)
  );
}, [selectedMechList, fullItem?.mechanicalPackingList, editingItem?.mechanicalPackingList]);

// Derive projectId from the selected MechanicalPackingList data
const derivedProjectId = useMemo(() => {
  const mechData = selectedMechListQuery.data?.data as any;
  return (
    mechData?.projectId ||
    (activeMech as any)?.projectId ||
    (fullItem as any)?.project?.id ||
    (fullItem as any)?.projectId ||
    (fullItem as any)?.packingCodes?.projectId ||
    (editingItem as any)?.project?.id ||
    (editingItem as any)?.projectId ||
    (editingItem as any)?.packingCodes?.projectId ||
    ''
  );
}, [selectedMechListQuery.data, activeMech, fullItem, editingItem]);

// Packing codes query - uses projectId derived from selected MechanicalPackingList
const { getAvailableForProjectQuery: packingCodesQuery } = usePackingCodes({
  availableForProject: {
    projectId: derivedProjectId,
    packingGroupType: EPackingGroupType.WarehouseReceipt,
    isEnable: open && !!derivedProjectId,
  },
});

