// In edit mode, include the current packing code even if it's now "Used"
const packingCodeOptions = useMemo(() => {
  const queryItems = (packingCodesQuery.data?.data as any[]) ?? [];
  const options = queryItems.map((pc: any) => ({
    label: pc.packingCode || pc.code,
    value: pc.id,
  }));
  const currentCodeId =
    fullItem?.packingCodesId || editingItem?.packingCodesId || form.getValues('packingCodesId');
  if (isEditMode && currentCodeId) {
    const currentExists = options.some((o) => o.value === currentCodeId);
    const codeLabel =
      (fullItem as any)?.packingCodes?.packingCode ||
      (fullItem as any)?.packingCodes?.code ||
      (fullItem as any)?.packingCodesCodeSnapshot ||
      (editingItem as any)?.packingCodes?.packingCode ||
      (editingItem as any)?.packingCodes?.code ||
      (editingItem as any)?.packingCodesCodeSnapshot;
    if (!currentExists && codeLabel) {
      options.unshift({
        label: codeLabel,
        value: currentCodeId,
      });
    }
  }
  return options;
}, [packingCodesQuery.data, isEditMode, fullItem, editingItem, form]);

// ─── Computed values ────────────────────────────────────────────────────────

const watchedDetails = useWatch({ control: form.control, name: 'details' });

const computedWeight = useMemo(() => {
  const details = watchedDetails || [];
  if (details.length > 0) {
    return details.reduce((sum, d) => sum + (Number(d.actualWeight) || 0), 0);
  }
  return fullItem?.actualTotalWeight ?? editingItem?.actualTotalWeight ?? 0;
}, [watchedDetails, fullItem?.actualTotalWeight, editingItem?.actualTotalWeight]);

