const isPending = createMutation.isPending || updateMutation.isPending;
const fullItem = isEditMode ? (getByIdQuery.data?.data ?? editingItem) : null;

const targetProjectId = useMemo(
  () => selectedProjectId || fullItem?.projectId || (editingItem as any)?.projectId || '',
  [selectedProjectId, fullItem, editingItem],
);

const targetSalesOrderId = useMemo(
  () => selectedSalesOrderId || fullItem?.salesOrderId || (editingItem as any)?.salesOrderId || '',
  [selectedSalesOrderId, fullItem, editingItem],
);

const { getAvailableForSiteDeliveryQuery: inStockPackingsQuery } = useFinishedGoodsReceipt({
  availableForSiteDelivery: {
    projectId: targetProjectId || undefined,
    salesOrderId: targetSalesOrderId || undefined,
    isEnable: open && (!!targetProjectId || !!targetSalesOrderId),
    // Chặn double-pack: loại kiện đã đóng ở phiếu khác; khi sửa thì bỏ qua chính phiếu này.
    excludeDeliveryPackingId: editingItem?.id,
  },
});

const isHeaderLoading = isEditMode && (getByIdQuery.isLoading || !getByIdQuery.data?.data);

const isDetailsLoading =
  isHeaderLoading ||
  ((!!targetProjectId || !!targetSalesOrderId) &&
    inStockPackingsQuery.isLoading &&
    !inStockPackingsQuery.data);

// ─── Data queries ───────────────────────────────────────────────────────────

const { dropdownQuery: projectsQuery } = useProject({
  queryParam: { dropdown: { isEnable: true } },
});

const { dropdownQuery: salesOrdersQuery, getByIdQuery: salesOrderQuery } = useSaleOrder({
  id: targetSalesOrderId || undefined,
  queryParam: {
    dropdown: { isEnable: open },
    getById: {
      isEnable: open && !!targetSalesOrderId,
      includes: ['Details'],
    },
  },
});

const { getAvailableForSourceQuery: packingCodesQuery } = usePackingCodes({
  availableForSource: {
    projectId: targetProjectId || undefined,
    salesOrderId: targetSalesOrderId || undefined,
    packingGroupType: EPackingGroupType.Delivery,
    isEnable: open && (!!targetProjectId || !!targetSalesOrderId),
  },
});

