const tabs = useMemo<FormTabItemConfig[]>(() => {
  const list: FormTabItemConfig[] = [
    {
      value: 'finishedGoods',
      label: t('installationOrder:tab.finishedGoods', { defaultValue: 'ITP' }),
      icon: Package,
      badgeCount: watchedFinishedGoods.length,
      content: (
        <InstallationOrderFinishedGoodsTab
          canAddDetail={canAddDetail}
          isReadOnly={isReadOnly}
          onSaveTab={onSaveFinishedGoodsTab}
          isSavingTab={isSavingFinishedGoodsTab}
          canSaveTab={canSaveTab}
          setToolbar={setActiveTabToolbar}
        />
      ),
    },
    {
      value: 'packings',
      label: t('installationOrder:tab.packings', { defaultValue: 'Cụm thành phẩm' }),
      icon: Boxes,
      badgeCount: watchedPackings.length,
      content: (
        <InstallationOrderPackingsTab
          canAddDetail={canAddDetail}
          isReadOnly={isReadOnly}
          onSaveTab={onSavePackingsTab}
          isSavingTab={isSavingPackingsTab}
          canSaveTab={canSaveTab}
          setToolbar={setActiveTabToolbar}
        />
      ),
    },
    {
      value: 'processes',
      label: t('installationOrder:tab.processes', { defaultValue: 'Quy trình' }),
      icon: Workflow,
      badgeCount: watchedProcesses.length,
      content: (
        <InstallationOrderProcessesTab
          canAddDetail={canAddDetail}
          isReadOnly={isReadOnly}
          sourceData={sourceData}
          isIndependent={isIndependent}
          operationMap={operationMap}
          onSaveTab={onSaveProcessesTab}
          isSavingTab={isSavingProcessesTab}
          canSaveTab={canSaveTab}
          setToolbar={setActiveTabToolbar}
          semiFinishedIdToModelId={semiFinishedIdToModelId}
        />
      ),
    },
    {
      value: 'details',
      label: t('installationOrder:tab.details', { defaultValue: 'BOR' }),
      icon: ClipboardList,
      badgeCount: watchedDetails.length,
      content: (
        <InstallationOrderDetailsTab
          canAddDetail={canAddDetail}
          isReadOnly={isReadOnly}
          sourceData={sourceData}
          isIndependent={isIndependent}
          operationMap={operationMap}
          costMap={costMap}
          standardMap={standardMap}
          uomMap={uomMap}
          productionTeamDropdown={productionTeamDropdown}
          onSaveTab={onSaveDetailsTab}
          isSavingTab={isSavingDetailsTab}
          canSaveTab={canSaveTab}
          setToolbar={setActiveTabToolbar}
          semiFinishedIdToModelId={semiFinishedIdToModelId}
        />
      ),
    },
  ];

  if (systemFinishedGoods.length > 0) {
    list.push({
      value: 'systemProcess',
      label: t('installationOrder:tab.systemProcess', {
        defaultValue: 'Quy trình lắp đặt hệ',
      }),
      icon: Wrench,
      badgeCount: systemFinishedGoods.length,
      content: (
        <InstallationOrderSystemProcessTab systemFinishedGoods={systemFinishedGoods} />
      ),
    });
  }

  list.push(
